  str_guide_pop_title = "연쇄 스킬",
  str_guide_pop_desc = "연결이 <color=#ff8f3d>일정 길이</color>에 도달하면, <color=#ff8f3d>자동으로 연쇄 스킬이 발동</color>됩니다.\n일반적으로 <color=#ff8f3d>연결이 길수록</color>, 연쇄 스킬의 <color=#ff8f3d>효과가 강해집니다</color>.\n모든 오로리안의 연쇄 스킬은 다양한 효과과 발동 조건을 가지고 있으니 여러 방식으로 조합해 보세요.",
  str_guide_pop_close = "닫기",
