  str_guide_pop_title_lineskill = "연쇄 스킬",
  str_guide_pop_desc_lineskill = "연결이 <color=#ff8f3d>일정 길이</color>에 도달하면, <color=#ff8f3d>자동으로 연쇄 스킬이 발동</color>됩니다.\n일반적으로 <color=#ff8f3d>연결이 길수록</color>, 연쇄 스킬의 <color=#ff8f3d>효과가 강해집니다</color>.\n모든 오로리안의 연쇄 스킬은 다양한 효과과 발동 조건을 가지고 있으니 다양한 방식으로 조합해 보세요.",
  str_guide_pop_extra_lineskill = "──오로리안의 가치는 그들이 보여주는 힘 이상의 것이지.\n                                      《라인하르트의 메시지 3》",
  str_guide_pop_title_moreline = "다수의 오로리안 연결",
  str_guide_pop_desc_moreline = "다수의 오로리안이 출전한 상태에서는, 연결된 칸의 속성과 대응하는 오로리안만 행동합니다.\n<color=#ff5f51>빨간색 칸</color>은 <color=#ff5f51>불 속성</color> 오로리안과, <color=#6fd5ff>파란색 칸</color>은 <color=#6fd5ff>물 속성</color> 오로리안과, \n<color=#85ff3b>초록색 칸</color>은 <color=#85ff3b>숲 속성</color> 오로리안과, <color=#fee039>노란색 칸</color>은 <color=#fee039>번개 속성</color> 오로리안과 대응합니다.\n리더 오로리안은 <color=#ff8f3d>칸 속성에 관계없이</color> 턴마다 반드시 움직일 수 있으니 안심하세요.",
  str_guide_pop_extra_moreline = "──세계는 신의 가호를 받았고, 그녀는 빛으로 마음을 채웠다.\n                                      《라인하르트의 메시지 1》",
  str_guide_pop_title_mainskill1 = "액티브 스킬",
  str_guide_pop_desc_mainskill1 = "액티브 스킬은 선제공격과 비선제공격으로 나뉘며, <color=#ff8f3d>선제공격 스킬</color>은 전투가 시작되면 바로 시전할 수 있습니다.\n액티브 스킬은 <color=#ff8f3d>라인 연결 전에 시전해야</color> 하며, 시전 후 <color=#ff8f3d>쿨다운 시간에 진입합니다</color>.\n오로리안의 액티브 스킬은 다양한 유형이 존재하며, 각종 스킬을 적절히 조합하면 최고의 효율을 발휘할 수 있습니다.",
  str_guide_pop_extra_mainskill1 = "──머나먼 세월은 우리 마음속에 갈등을 심기도, 아름다운 경이로움을 키워내기도 하지.\n                                      《라인하르트의 메시지 2》",
  str_guide_pop_title_mainskill2 = "색 변경 스킬",
  str_guide_pop_desc_mainskill2 = "색 변경 스킬은 일종의 특수 스킬로, <color=#ff8f3d>어떤 칸을 전환</color>하거나 <color=#ff8f3d>보드를 변경</color>할 수 있습니다.\n색 변경 시 더 많은 <color=#ff8f3d>연결을 할 수 있으며</color>, 이는 가장 강력한 서포터 스킬입니다.\n적절한 때에 전략적으로 이용하여 전세를 뒤집어 보세요.",
  str_guide_pop_extra_mainskill2 = "──영원히 변하지 않는 유일한 것이 있다면, 바로 변화 그 자신이다.\n                                      《라인하르트의 메시지 4》",
  str_guide_pop_title_levelup = "오로리안 레벨업",
  str_guide_pop_desc_levelup = "레벨을 높여 오로리안의 힘을 증가시켜 주세요.",
  str_guide_pop_extra_levelup = "레벨 설명 XXX",
  str_guide_pop_title_lineskillrange = "연쇄 스킬 범위",
  str_guide_pop_desc_lineskillrange = "오로리안 연쇄 스킬의 범위를 확인하는 것은 전투의 효율을 높이는 가장 기본적인 수단입니다.\n오로리안의 스킬 범위는 다양하며, 연결 후 <color=#ff8f3d>길게 누르고 있으면</color> 발동 가능한 모든 스킬의 범위가 <color=#ff8f3d>자동으로 나타납니다</color>.\n이를 참고해서 <color=#ff8f3d>연결의 종료 지점을 조정</color>하면 오로리안이 더 적합한 범위에 스킬을 시전하도록 할 수 있습니다.",
  str_guide_pop_extra_lineskillrange = "──전우 간 최고의 명예는 목숨을 서로에게 맡기는 것이다.\n                                      《라인하르트의 메시지 7》",
  str_guide_pop_title_leaderskill = "리더 스킬",
  str_guide_pop_desc_leaderskill = "일부 오로리안은 다른 오로리안을 능가하는 특수 패시브 스킬인 '리더 스킬'을 가지고 있습니다.",
  str_guide_pop_extra_leaderskill = "리더 스킬은 같은 속성 오로리안의 수치를 대폭 증가시킬 수 있는 매우 희귀한 스킬입니다.",
  str_guide_pop_title_jiguan = "트랩",
  str_guide_pop_desc_jiguan = "파이어 트랩은 <color=#ff8f3d>일정한 패턴으로 돌아가며</color> <color=#ff8f3d>가로열 또는 세로열</color> 위에 머물러 있는 대상에게 피해를 입힙니다.\n트랩은 <color=#ff8f3d>우리 편을 공격하기도</color>, <color=#ff8f3d>적을 공격하기도 하므로</color> 적절히 이용하면 매우 효과적입니다.\n공격 범위로부터 멀리 떨어지면서 트랩에 연결이 막히지 않도록 유의하세요.",
  str_guide_pop_extra_jiguan = "──옛 시대엔 쓰레기들이 많았어. 하지만 재미있는 물건도... 아주 많았다고! 그렇지?\n                                      《그로누 관찰일기》",
  str_guide_pop_title_muchaoguai = "하이브 몬스터",
  str_guide_pop_desc_muchaoguai = "하이브 몬스터는 <color=#ff8f3d>이동할 수 없지만</color> <color=#ff8f3d>끊임없이 암귀를 소환</color>할 수 있습니다.\n제때 처리하지 않으면 필드를 모두 뒤덮게 됩니다.\n<color=#ff8f3d>몬스터의 본체를 직접 공격</color>하는 것이 가장 좋은 방법이며, 중형 몬스터라면 더욱 필수적입니다.\n<color=#ff8f3d>범위 공격</color>은 가장 효과적인 수단입니다.",
  str_guide_pop_extra_muchaoguai = "──어떤 암귀들은 정말 구역질이 나. 찢어버리고 나면, 끈적거리는 뭔가가...(데이터 삭제됨)\n                                      《그로누 관찰일기》",
  str_guide_pop_title_shenyuan = "심연 칸",
  str_guide_pop_desc_shenyuan = "심연 칸은 지나갈 수 없지만, 비행 몬스터는 통과할 수 있으며, 순간이동으로도 통과할 수 있습니다.",
  str_guide_pop_extra_shenyuan = "순간이동으로 통과할 수 있습니다.",
  str_guide_pop_title_moredamge = "암귀의 체형과 피해",
  str_guide_pop_desc_moredamge = "암귀는 <color=#ff8f3d>다양한 체형</color>을 가지고 있으며, 1칸 크기가 가장 보편적입니다.\n4칸 크기, 심지어는 더 큰 대형 암귀도 존재하는데, 이들은 매우 강하지만, 전투 시 더 쉽게 타깃이 될 수 있습니다.\n<color=#ff8f3d>많은 칸을 차지하면 범위 공격에 의해 더 많은 피해를 받으며</color>, 연쇄 공격도 마찬가지입니다.",
  str_guide_pop_extra_moredamge = "──더 큰 녀석일수록 오히려 상대하기 쉽지. 눈을 감고 좀 때리다 보면 끝나 있거든.\n                             《바튼 어록》(미발간)",
  str_guide_pop_title_leveltask = "스테이지 퀘스트",
  str_guide_pop_desc_leveltask = "스테이지에는 다양한 퀘스트가 제시되며, 완료 시 스테이지를 클리어할 수 있습니다.",
  str_guide_pop_extra_leveltask = "스테이지 퀘스트를 완료해야 스테이지를 클리어할 수 있습니다.",
  str_guide_pop_title_escape = "탈출 지점",
  str_guide_pop_desc_escape = "탈출 지점은 특수 스테이지의 승리 방법으로, <color=#ff8f3d>해당 지점까지 이동</color>하면 스테이지를 즉시 완료할 수 있습니다.\n단, 탈출 지점은 초기에는 <color=#ff8f3d>비활성화 상태</color>이며, 전제 조건을 달성한 후에만 개방됩니다.\n개방 조건은 다양하며, <color=#ff8f3d>특정 요소의 수집 또는 암귀 처치</color>일 수 있습니다.",
  str_guide_pop_extra_escape = "──도망은 수치스러운 게 아냐. 잠깐의 양보는 더 큰 포부를 위해서니까...\n                                      《시로나의 편지》",
  str_guide_pop_title_monsterinfo = "상세정보 보기",
  str_guide_pop_desc_monsterinfo = "<color=#ff8f3d>몬스터 아래의 지면 칸을 길게 누르면</color> 몬스터의 공격 범위 등 상세 정보를 볼 수 있습니다.\n상대의 특징을 수시로 확인해야만 전투의 우위를 점할 수 있습니다.",
  str_guide_pop_extra_monsterinfo = "──지피지기면, 백전백승이다.\n                                      《미지의 서: 발췌 단편》",
  str_guide_pop_title_jiguangshike = "오로라 타임",
  str_guide_pop_desc_jiguangshike = "<color=#ff8f3d>15칸 이상의 연결을 달성하면 오로라 타임이 발동되며</color> 추가 행동 기회를 얻게 됩니다.\n오로라 타임에는 오로리안이 준비된 액티브 스킬을 시전하거나, 연결을 통해 연쇄 스킬을 발동시킬 수 있습니다.\n오로라 타임은 <color=#ff8f3d>턴마다 한 번만 발동되며</color> 전투에 큰 이점을 가져다줍니다.",
  str_guide_pop_extra_jiguangshike = "──빛의 마력에 대해 우리가 알고 있는 건 그저 빙산의 일각일 뿐이다.\n                                      《미지의 서: 발췌 단편》",
  str_guide_pop_title_jianglihuihe = "보상 시간",
  str_guide_pop_desc_jianglihuihe = "특정 난이도의 백야 흑금 던전을 일정 횟수 누적 클리어 시 보상 시간이 시작됩니다.\n필드에 흑금 암귀가 여러 마리 나타나며, 처치 시 추가 나이티움을 얻을 수 있습니다.\n단, 흑금 암귀는 <color=#ff8f3d>행동력이 높아</color> 공격을 피해 도망칠 수도 있습니다.",
  str_guide_pop_extra_jianglihuihe = "──행운의 시간은, 매일 한 번쯤은 오기 마련이죠!\n                                      《백야 흑금 서비스 가이드》",
  str_guide_warn_10111 = "이쪽에 길이 있어. 암귀 옆을 지나가면 공격할 수 있을 거야...",
