  str_guide_warn_50049 = "이건 특수한 시스템이 있는 스테이지야. 도전하기 전에 스테이지 난이도를 직접 결정할 수 있어.",
  str_guide_warn_50050 = "우선 스테이지의 난이도를 선택해야 해. 난이도마다 기본 포인트가 정해져 있어.",
  str_guide_warn_50051 = "그리고 스테이지의 추가 효과를 선택하면 돼. 효과마다 포인트 배율이 추가될 거야.",
  str_guide_warn_50052 = "기본 포인트랑 배율을 곱하면 최종 포인트가 되는 거야.",
