  str_guide_warn_50060 = "「바람에 실려온 편지」 이벤트가 시작됐어! 여기서 새로운 모험 이야기를 시작하자.",
  str_guide_warn_50061 = "메인 스테이지와 자원 정비에서 프리즘을 소모하면 비율에 따라 「길드 간식」을 얻을 수 있어.",
