  str_guide_warn_50063 = "이벤트 메인 스토리와 쿠리어 센터 재건에 참가하면 특별 사건부의 임무를 완료할 수 있어.",
  str_guide_warn_50064 = "매일 출석하면 보상을 수령할 수 있으니까, 매일 로그인하는 것도 잊지 말아줘.",
  str_guide_warn_50065 = "이벤트에 대해 더 궁금한 점이 있다면, 이벤트의 상세 규칙을 확인해 봐.",
  str_guide_warn_50066 = "헤븐즈 밸리의 쿠리어 센터에 도착했네요! 「길드 간식」을 소모하면 쿠리어 센터 재건을 시작할 수 있답니다.",
