  str_guide_warn_50070 = "「밤과 안개의 그림자」 이벤트가 시작됐어! 여기서 움브라톤의 모험을 시작하자.",
  str_guide_warn_50071 = "움브라톤의 격투 대회에 참가해 실력자들에게 도전하면 지하격투장 명성을 얻을 수 있어.",
  str_guide_warn_50072 = "명성을 누적하면 다양한 보상을 개방할 수 있고, 사거리의 신문도 얻을 수 있어!",
  str_guide_warn_50073 = "각종 이벤트 도전에 참가하면 특별 사건부의 임무를 완료할 수 있어.",
  str_guide_warn_50074 = "매일 출석하면 보상을 수령할 수 있으니까, 매일 로그인하는 것도 잊지 말아줘.",
  str_guide_warn_50075 = "이벤트에 대해 더 궁금한 점이 있다면, 이벤트의 상세 규칙을 확인해 봐.",
  str_guide_warn_50076 = "「영원한 백야」 이벤트가 시작됐어! 여기서 백야성의 모험을 시작하자.",
  str_guide_warn_50077 = "「지휘 비록」은 시간에 따라 다양한 모의 전투가 생성될 거야. 전투를 완료하면 명성 수치를 획득할 수 있어.",
  str_guide_warn_50078 = "명성을 모으면 다양한 보상을 얻을 수 있어.",
  str_guide_warn_50079 = "각종 이벤트 도전에 참가하면 특별 사건부의 임무를 완료할 수 있어.",
  str_guide_warn_50080 = "매일 출석하면 보상을 수령할 수 있으니까, 매일 로그인하는 것도 잊지 말아줘.",
  str_guide_warn_50081 = "이벤트에 대해 더 궁금한 점이 있다면, 이벤트의 상세 규칙을 확인해 봐.",
  str_guide_warn_50082 = "데이터 디스크에는 다양한 유형의 모의 전투가 기록되어 있어. 모의 전투를 완료하면 해당하는 데이터 디스크를 소모하게 돼.",
  str_guide_warn_50083 = "지휘 포인트로는 「지휘 레벨」을 높일 수 있고, 레벨 보상도 개방할 수 있어.",
  str_guide_warn_50084 = "자료 조각으로는 데이터베이스에서 서적, 아바타 등을 개방할 수 있어.",
  str_guide_warn_50085 = "데이터 디스크를 제작하려면 시간이 필요해. 가속 기능을 사용해서 데이터 디스크 제작 속도를 높일 수 있어.",
