  str_guide_warn_50093 = "「겨우살이 열매」로는 눈소나무 시장에서 다양한 보상으로 교환할 수 있을 거야.",
  str_guide_warn_50094 = "각종 이벤트 도전에 참가하면 특별 사건부의 임무를 완료할 수 있어.",
  str_guide_warn_50095 = "매일 출석하면 보상을 수령할 수 있으니까, 매일 로그인하는 것도 잊지 말아줘.",
