  str_guide_warn_50112 = "이벤트 스테이지를 완료하거나 다른 콘텐츠에서 프리즘을 소모하면 「고대의 주화」를 얻을 수 있어.",
  str_guide_warn_50113 = "「무인 슈퍼마켓」에서 「고대의 주화」를 가지고 다양한 보상을 교환할 수 있어.",
  str_guide_warn_50114 = "각종 이벤트 도전에 참가하면 특별 사건부의 임무를 완료할 수 있어.",
  str_guide_warn_50115 = "매일 출석하면 보상을 수령할 수 있으니까, 매일 로그인하는 것도 잊지 말아줘.",
  str_guide_warn_50116 = "이벤트에 대해 더 궁금한 점이 있다면, 이벤트의 상세 규칙을 확인해 봐.",
