  str_guide_warn_50119 = "「조사 명성」을 누적하면 「조사 노트」의 모험 이야기와 다양한 보상을 개방할 수 있어.",
  str_guide_warn_50120 = "메인 모험 이야기 외에도 「꿈의 탐색」에 참가해 더 많은 구역을 탐색할 수 있어.",
  str_guide_warn_50130 = "「홍옥에 내려앉은 눈꽃(상)」 이벤트가 시작됐어! 여기서 새로운 모험 이야기를 시작하자.",
