  str_guide_warn_50132 = "「운도 소원종이」를 사용해서 설락원을 장식하면 오로리안들이 나들이를 올 수도 있어!",
  str_guide_warn_50133 = "이벤트 메인 스토리와 설락원 장식에 참가하면 특별 사건부의 임무를 완료할 수 있어.",
  str_guide_warn_50134 = "매일 출석하면 보상을 수령할 수 있으니까, 매일 로그인하는 것도 잊지 말아줘.",
  str_guide_warn_50135 = "이벤트에 대해 더 궁금한 점이 있다면, 이벤트의 상세 규칙을 확인해 봐.",
  str_guide_warn_50140 = "「홍옥에 내려앉은 눈꽃(하)」 이벤트가 시작됐어! 여기서 새로운 모험 이야기를 시작하자.",
  str_guide_warn_50141 = "「겁화의 여파」에서 우리는 어려운 시험과 마주하게 될 거야.",
