  str_guide_warn_50151 = "주문을 완료하면 보너스 보상이 누적돼서 추가 포인트 배율을 얻을 수 있어. 대신 주문 시간을 초과하면 안 돼.",
  str_guide_warn_50152 = "완료한 주문이 쌓이면 에너지를 충전할 수 있고, 에너지가 가득 차면 가속 시간에 진입해서 금붕어의 달인이 될 수 있어!",
  str_guide_warn_50153 = "이제 방법은 잘 알겠지? 그럼 도전을 시작해 보자!",
  str_guide_warn_50160 = "「질주! 세상의 끝을 향해!」 이벤트가 시작됐어! 여기서 새로운 모험 이야기를 시작하자.",
