  str_guide_warn_50164 = "매일 출석하면 보상을 수령할 수 있으니까, 매일 로그인하는 것도 잊지 말아줘.",
  str_guide_warn_50165 = "이벤트에 대해 더 궁금한 점이 있다면, 이벤트의 상세 규칙을 확인해 봐.",
  str_guide_warn_50180 = "「진실 아래-광기의 단편」 이벤트가 시작됐어! 여기서 새로운 모험 이야기를 시작하자.",
  str_guide_warn_50181 = "「연회의 막이 내린 뒤」에서 우리는 어려운 시험과 마주하게 될 거야.",
