  str_guide_warn_50211 = "「바이스의 대발견」 이벤트가 시작됐어!",
  str_guide_warn_50212 = "계획 목록에 따라 메인 스테이지와 자원 정비 스테이지, 헤븐즈 가든에서 퀘스트를 완료하면 이벤트 아이템 「양자화 데이터 칩」를 얻을 수 있어.",
