  str_guide_warn_50214 = "「정밀 국지 탐색」에서는 신비한 생물 츄브와 함께 헤븐즈 가든에서 신호를 조사하고 보물을 찾을 수 있어!",
  str_guide_warn_50215 = "이벤트에 참가하면 특별 사건부의 임무를 완료할 수 있어.",
  str_guide_warn_50216 = "매일 출석하면 보상을 수령할 수 있으니까, 매일 로그인하는 것도 잊지 말아줘.",
  str_guide_warn_50217 = "이벤트에 대해 더 궁금한 점이 있다면, 이벤트의 상세 규칙을 확인해 봐.",
  str_guide_warn_50220 = "조종사~ 블랙박스 모드가 개방됐어. 여길 터치해 봐.",
  str_guide_warn_50221 = "터치해서 스테이지에 입장해 보자.",
  str_guide_warn_50222 = "스테이지마다 여러 하위 스테이지가 있어. 하위 스테이지를 모두 클리어해야 해당 스테이지를 클리어한 것으로 기록돼.",
  str_guide_warn_50223 = "협동 작전을 해야 해서, 하위 스테이지마다 다른 오로리안이 출전해야 해.",
  str_guide_warn_50224 = "모든 하위 스테이지의 트로피 조건을 만족하면 더 많은 보상을 획득할 수 있어.",
  str_guide_warn_500001 = "조종사, 여기를 봐. 새로운 구역이 나타났어. 함께 가보자!",
  str_guide_warn_500002 = "여기를 터치해 봐~",
  str_guide_warn_501001 = "슬라이드하면 주변을 둘러볼 수 있어!",
  str_guide_warn_501002 = "레버를 조작하면 이동할 수 있어. 날 찾아봐~",
  str_guide_warn_501003 = "WASD 버튼을 누르면 이동할 수 있어. 날 찾아봐~",
  str_guide_warn_501004 = "선택지 버튼을 터치해서 나랑 대화해 봐!",
  str_guide_warn_501005 = "진행 중인 퀘스트는 여기서도 볼 수 있어. 힌트대로 나무 옆에 가서 원목을 수집해 봐!",
  str_guide_warn_502001 = "나무에 가까이 다가가면 벌목 버튼이 보일 거야. 길게 누르면 벌목할 수 있어~",
  str_guide_warn_502002 = "광석에 가까이 다가가면 채굴 버튼이 보일 거야. 길게 누르면 채굴할 수 있어!",
  str_guide_warn_503001 = "재료를 다 모으면 돌아와서 건물을 수리할 수 있어!",
  str_guide_warn_503002 = "수리 버튼을 터치해서 수리하자~",
  str_guide_warn_503004 = "확인을 터치해서 재료를 제출해라 츄브!",
  str_guide_warn_504001 = "버튼을 터치하면 나와 교류할 수 있다 츄브!",
  str_guide_warn_504003 = "이제 헤븐즈 가든 숙소를 선택하자!",
  str_guide_warn_504004 = "재료가 충분하니까 바로 건설을 터치해!",
  str_guide_warn_504005 = "제작 중인 건물은 모두 생산 대열에서 확인할 수 있어!",
  str_guide_warn_504006 = "생산 대열에 있는 건물은 일정 시간이 지나야 완성될 거야.",
  str_guide_warn_504007 = "촉진 페로몬으로 제작을 가속할 수 있어. 조금 전 획득한 촉진 페로몬을 사용해 보자!",
  str_guide_warn_504008 = "촉진 페로몬마다 3시간을 가속할 수 있어. 이곳을 터치해서 수량을 늘려봐.",
  str_guide_warn_504009 = "촉진 페로몬마다 3시간을 가속할 수 있어. 이곳을 터치해서 수량을 늘려봐.",
  str_guide_warn_504010 = "촉진 페로몬마다 3시간을 가속할 수 있어. 이곳을 터치해서 수량을 늘려봐.",
  str_guide_warn_504011 = "확인을 터치하면 가속이 진행될 거야.",
  str_guide_warn_504012 = "빨리 완성됐네! 버튼을 터치해서 건물을 획득하자!",
  str_guide_warn_504013 = "그럼 건물을 배치해 보자!",
  str_guide_warn_505001 = "여길 터치해서 배치하자.",
  str_guide_warn_505002 = "이쪽 공터가 좋을 것 같아!",
  str_guide_warn_505003 = "헤븐즈 가든 숙소를 터치해서 공터에 배치하면 돼~",
  str_guide_warn_505004 = "확인을 터치해~",
  str_guide_warn_505005 = "저장하는 것도 잊지 마!",
  str_guide_warn_505006 = "자, 이렇게 성공했어!",
  str_guide_warn_506001 = "그럼 숙소 앞에 와서 상호작용 버튼을 터치해 봐.",
  str_guide_warn_506002 = "여길 터치해서 숙소 정보를 확인해 봐.",
  str_guide_warn_506003 = "첫 번째 위치를 터치해.",
  str_guide_warn_506004 = "블랑 씨를 선택해.",
  str_guide_warn_506005 = "이렇게 하면 입주 완료야. 블랑 씨한테 느낌이 어떤지 물어봐!",
  str_guide_warn_507002 = "이런 방식으로 헤븐즈 가든 경험치를 얻을 수 있어. 레벨업하면 보상과 더 많은 헤븐즈 가든 콘텐츠를 개방할 수 있을 거야.",
  str_guide_warn_507003 = "여기를 터치해서 오늘의 출석 보상을 수령해 봐!",
  str_guide_warn_508002 = "낚시 버튼을 길게 눌러서 낚시를 시작하자. 적당한 타이밍에 손을 떼면 낚싯대를 던질 수 있어!",
  str_guide_warn_508003 = "이제 인내심을 가지고 기다릴 차례야...",
  str_guide_warn_508005 = "이쪽은 파워 게이지야. 가만히 있으면 수치가 서서히 내려갈 거야. 레버를 터치하면 파워 게이지를 높일 수 있어.",
  str_guide_warn_508006 = "파워 게이지를 초록색 범위 안에서 일정 시간 유지하면 물고기를 낚을 수 있을 거야!",
  str_guide_warn_508007 = "만약 시간이 너무 오래 걸리거나, 힘이 너무 적거나 크면 물고기가 도망가 버려.",
  str_guide_warn_508008 = "이제 버튼을 터치해서 직접 낚시를 해 봐!",
  str_guide_warn_509002 = "일단 어떤 주문이 들어왔는지 봐라 츄브!",
  str_guide_warn_509003 = "첫 번째 주문은 이미 완료했다 츄브! 제출을 터치해 봐 츄브!",
  str_guide_warn_509004 = "방금 가든 스톤을 받았어. 그걸로 물건을 살 수 있을 거야.",
  str_guide_warn_509005 = "맞다. 여기는 씨앗 외에도 다양한 상품이 있다 츄브!",
  str_guide_warn_509006 = "돈을 어떻게 쓸 건지 계획을 잘 세워야 해! 여길 터치해서 돌아가자.",
  str_guide_warn_510002 = "재배에는 돌연변이 재배, 지정 재배, 변화 재배의 세 가지 방식이 있다 츄브. 먼저 돌연변이 재배부터 해 보기로 하지 츄브!",
  str_guide_warn_510003 = "여기에는 환상수 씨앗을 본체 씨앗으로 넣을 수 있다 츄브.",
  str_guide_warn_510004 = "여기서는 같은 등급의 씨앗을 돌연변이 인자로 넣을 수 있지 츄브.",
  str_guide_warn_510005 = "다 넣은 뒤에 여길 터치하면 재배를 시작한다 츄브.\n그리고 일정 시간이 지나면 환상수가 성장한다 츄브!",
  str_guide_warn_510006 = "못 기다리겠으면 신비한 촉진제로 가속할 수 있다 츄브.",
  str_guide_warn_510007 = "또 모르는 게 있다면 여길 터치해서 설명을 볼 수 있다 츄브!",
  str_guide_warn_511001 = "비옥한 땅은 [특수 장식] 탭에 있다. 여길 터치해라 츄브!",
  str_guide_warn_511002 = "그리고 [비옥한 땅]을 터치해라 츄브~",
  str_guide_warn_511003 = "이게 바로 비옥한 땅이다 츄브! 이제 환상수를 재배할 수 있다 츄브!",
  str_guide_warn_512001 = "여길 터치해서 배치하자.",
  str_guide_warn_512002 = "비옥한 땅은 [특수 장식]에 있어. 여길 터치해 봐!",
  str_guide_warn_512003 = "그리고 [비옥한 땅]을 터치해~",
  str_guide_warn_512004 = "이게 바로 비옥한 땅이야. 여길 눌러서 배치해 봐~",
  str_guide_warn_5110001 = "조종사! 오로리안 레벨이 한도에 도달했어!\n각성을 통해 레벨 한도를 높여야 계속해서 레벨을 올릴 수 있어!",
  str_guide_warn_5110004 = "여길 눌러서 각성에 필요한 재료를 확인해 봐!",
  str_guide_warn_5110005 = "재료가 부족하면 여러 경로로 재료를 획득할 수 있어. 각 스테이지에서 수집하거나, 제련실이 지정 레벨에 도달하면 재료를 합성할 수도 있어!",
  str_guide_warn_19050101 = "「헤븐즈 가든의 슬로우 라이프」 이벤트가 시작됐어! 여기서 새로운 모험 이야기를 시작하자.",
  str_guide_warn_19050102 = "「여유로운 담소」에서 우리는 어려운 시험과 마주하게 될 거야.",
  str_guide_warn_19050103 = "「정밀 국지 탐색Ⅱ」에서는 계속해서 츄브들과 함께 헤븐즈 가든에서 신호를 조사하고 보물을 찾을 수 있어!",
  str_guide_warn_19050104 = "이벤트 스테이지를 완료하거나 프리즘을 소모해서 획득한 「안데르센 상회 어음」은 「안데르센 상회」에서 각종 보상으로 교환할 수 있어.",
  str_guide_warn_19050105 = "이벤트에 참가하면 특별 사건부의 임무를 완료할 수 있어.",
  str_guide_warn_19050106 = "매일 출석하면 보상을 수령할 수 있으니까, 매일 로그인하는 것도 잊지 말아줘.",
  str_guide_warn_19050107 = "이벤트에 대해 더 궁금한 점이 있다면, 이벤트의 상세 규칙을 확인해 봐.",
  str_guide_warn_11000101 = "「새벽녘의 출정」 이벤트가 시작됐어! 여기서 새로운 모험 이야기를 시작하자.",
  str_guide_warn_11000102 = "우리들의 새로운 친구 「돌무덤쥐」가 뭔가 어려움에 처한 것 같아... 「헤븐즈 가든 방문」에서 녀석들의 문제를 해결해 주자!",
  str_guide_warn_11000103 = "이벤트에 참가하면 특별 사건부의 임무를 완료할 수 있어.",
  str_guide_warn_11000201 = "「달빛 아래의 괴도」 이벤트가 시작됐어! 여기서 괴도단 멤버들과 함께 모험을 시작하자!",
  str_guide_warn_11000202 = "메인 스테이지와 자원 정비에서 프리즘을 소모하면 「잠입 포인트」를 얻을 수 있을 거야.",
  str_guide_warn_11000203 = "여기서부터 미궁에 잠입하자. 「잠입 포인트」를 소모해 적을 물리치면 다양한 보상을 획득할 수 있어~",
  str_guide_warn_11000204 = "여긴 괴도단 멤버들의 시련 스테이지야. 스테이지를 완료하면 보상을 받을 수 있어.",
  str_guide_warn_11000205 = "이벤트에 참가하면 특별 사건부의 임무를 완료할 수 있어.",
  str_guide_warn_11000206 = "매일 출석하면 보상을 수령할 수 있으니까, 매일 로그인하는 것도 잊지 말아줘.",
  str_guide_warn_11000207 = "이벤트에 대해 더 궁금한 점이 있다면, 이벤트의 상세 규칙을 확인해 봐.",
  str_guide_warn_11050101 = "「훈풍과 희망의 항구: 불어오는 바람」 이벤트가 시작됐어! 여기서 새로운 모험 이야기를 시작하자.",
  str_guide_warn_11050102 = "「골목의 그림자」에서 우리는 어려운 시험과 마주하게 될 거야.",
  str_guide_warn_11050103 = "「두근대는 점술」에서는 탐정이 되어 세 명의 히로인과 함께 절도 사건을 조사하게 될 거야!",
  str_guide_warn_11050104 = "이벤트 스테이지를 완료하거나 프리즘을 소모해서 획득한 「하버 페스티벌 코인」은 「축제 상점가」에서 각종 보상으로 교환할 수 있어.",
  str_guide_warn_11050105 = "모험 외에도 「미식 포장마차」에서 요리 실력을 겨루고 다양한 보상을 얻을 수 있어~",
  str_guide_warn_11050106 = "이벤트에 참가하면 특별 사건부의 임무를 완료할 수 있어.",
  str_guide_warn_11050107 = "매일 출석하면 보상을 수령할 수 있으니까, 매일 로그인하는 것도 잊지 말아줘.",
  str_guide_warn_11050108 = "이벤트에 대해 더 궁금한 점이 있다면, 이벤트의 상세 규칙을 확인해 봐.",
  str_guide_warn_11050201 = "손님들이 오고 있어. 얼른 국수를 만들 준비를 하자.",
  str_guide_warn_11050202 = "손님마다 원하는 국수가 달라. 정확한 재료를 선택해서 만들어야 해.",
  str_guide_warn_11050203 = "손님을 오래 기다리게 하면 손님의 기분이 안 좋아질 거야. 손님의 기분이 좋아야 더 높은 평점을 얻을 수 있어.",
  str_guide_warn_11050204 = "국수를 만들 땐 우선 정확한 양을 선택해야 해.",
  str_guide_warn_11050205 = "그다음엔 육수를 선택해.",
  str_guide_warn_11050206 = "이번엔 고명을 선택해! 육수랑 고명 선택의 순서는 상관없어.",
  str_guide_warn_11050207 = "이제 손님을 터치해 국수를 전달하면 주문은 끝이야.",
  str_guide_warn_11050208 = "완료한 주문이 쌓이면 조미료 무쌍 시간에 진입해서 주문을 더 빠르게 완료할 수 있어!",
  str_guide_warn_11050209 = "그리고 주문을 완료하면 보너스가 누적돼서 추가 평점 보상도 얻을 수 있어!",
  str_guide_warn_11050210 = "국수를 만들다가 실수를 해도 걱정할 거 없어. 여길 눌러서 국수를 버리면 돼.",
  str_guide_warn_11050211 = "여길 누르면 제작을 잠시 멈출 수 있어.",
  str_guide_warn_11050212 = "자, 그럼 어떻게 국수를 만드는지 알겠지? 이제 장사를 계속해 보자.",
  str_guide_warn_11100101 = "「훈풍과 희망의 항구: 불어오는 바람」 이벤트가 시작됐어! 여기서 새로운 모험 이야기를 시작하자.",
  str_guide_warn_11100102 = "프리즘을 소모하는 메인 스테이지나 자원 정비 스테이지를 클리어하면 「와일드카드」를 얻을 수 있고, 「마술모자 스탠드」에서 각종 보상 추첨에 사용할 수 있어.",
  str_guide_warn_11100103 = "헤븐즈 가든의 모두가 수영장 건설에 관심이 많은 것 같아! 「수영하고 싶어!」에서 새로운 헤븐즈 가든 소식을 확인할 수 있어~",
  str_guide_warn_11100104 = "「정밀 국지 탐색Ⅲ」에서는 다시 츄브들과 함께 헤븐즈 가든에서 신호를 조사하고 보물을 찾을 수 있어!",
  str_guide_warn_11100105 = "이벤트에 참가하면 특별 사건부의 임무를 완료할 수 있어.",
  str_guide_warn_11100106 = "매일 출석하면 보상을 수령할 수 있으니까, 매일 로그인하는 것도 잊지 말아줘.",
  str_guide_warn_11100107 = "이벤트에 대해 더 궁금한 점이 있다면, 이벤트의 상세 규칙을 확인해 봐.",
  str_guide_warn_11200101 = "「안녕, 나의 낙원」 이벤트가 시작됐어! 여기서 새로운 모험 이야기를 시작하자.",
  str_guide_warn_11200102 = "「위험 구역」에서 우린 어려운 시험과 마주하게 될 거야.",
  str_guide_warn_11200103 = "이벤트 스테이지를 완료하거나 프리즘을 소모해서 획득한 「탄피」는 「물자 보급소」에서 각종 보상으로 교환할 수 있어.",
  str_guide_warn_11200104 = "「거리의 소문」에서 우린 마을을 더 깊게 탐험하고, 거리에서 정보를 수집할 거야.",
  str_guide_warn_11200105 = "이벤트에 참가하면 특별 사건부의 임무를 완료할 수 있어.",
  str_guide_warn_11200106 = "매일 출석하면 보상을 수령할 수 있으니까, 매일 로그인하는 것도 잊지 말아줘.",
  str_guide_warn_11200107 = "이벤트에 대해 더 궁금한 점이 있다면, 이벤트의 상세 규칙을 확인해 봐.",
  str_guide_warn_11200203 = "이건 위험과 이득이 공존하는 임무야. 그럼 어서 출발하자~",
  str_guide_warn_11200204 = "중앙 엘리베이터는 우릴 깊은 곳으로 데려다 줄 수 있어.\n대신 유해한 기체로 가득 차 있어서 지금은 탐사할 수 없어.",
  str_guide_warn_11200205 = "이건 일루미나에서 우리한테 준 보상 목록이야.\n더 깊게 탐색할수록 보수도 더 많아질 거야.",
  str_guide_warn_11200206 = "아무튼 일단 유해 기체를 제거할 방법이 있는지 찾아보자~",
  str_guide_warn_11200207 = "여기 환기 장치는 전부 암귀가 점령하고 있어.\n전부 가동하면 유해 기체를 제거하고 다음 층으로 갈 수 있을 거야.",
  str_guide_warn_11200208 = "각 환기 장치는 오로리안 5명을 배치해야 가동할 수 있어.\n이번 층의 정화가 완료되기 전에 오로리안을 철수시키면\n장치 가동에 실패할 거야.",
  str_guide_warn_11200209 = "서로 다른 오로리안으로 구성된 팀을 파견하고, 모든 환기 장치를\n활성화하면 계속해서 더 깊은 곳을 탐색할 수 있어.",
  str_guide_warn_11200210 = "일루미나에서는 여기 더 자세한 탐색 자료를 제공할 거야.\n한번 확인해 봐.",
  str_guide_warn_11300101 = "「비명을 멈추면 안 돼!」 이벤트가 시작됐어! 여기서 새로운 모험 이야기를 시작하자.",
  str_guide_warn_11300102 = "이벤트 스테이지를 완료하거나 프리즘을 소모해서 획득한 「오래된 주화」는 「먼지 쌓인 밀실」에서 각종 보상 아이템으로 교환할 수 있어.",
  str_guide_warn_11300103 = "헤븐즈 가든의 모두가 영화 스튜디오를 만들고 싶다는 것 같은데? 「현장 준비!」에서 새로운 헤븐즈 가든 소식을 확인할 수 있어~",
  str_guide_warn_11300104 = "영화 스튜디오를 만들고 나면 영화를 찍을 수 있어! 촬영을 마치면 츄브 심사위원들의 풍성한 보상도 받을 수 있다구~",
  str_guide_warn_11300105 = "이벤트에 참가하면 특별 사건부의 임무를 완료할 수 있어.",
  str_guide_warn_11300106 = "매일 출석하면 보상을 수령할 수 있으니까, 매일 로그인하는 것도 잊지 말아줘.",
  str_guide_warn_11300107 = "이벤트에 대해 더 궁금한 점이 있다면, 이벤트의 상세 규칙을 확인해 봐.",
  str_guide_warn_11400102 = "프리즘을 소모하는 메인 스테이지, 자원 정비 스테이지를 완료하면 「부품 폐기물」을 얻을 수 있고, 악셀리아한테 제출하면 조립할 수 있어. 그리고 풍성한 보상도 받을 수 있을 거야~",
  str_guide_warn_11400103 = "헤븐즈 가든의 모두가 낚시 대회를 열려고 한다는데? 「사상 초유의 일격」에서 새로운 헤븐즈 가든 소식을 확인할 수 있어~",
  str_guide_warn_11400104 = "새로운 친구들과 함께 도전하면 루맘버 보상을 얻을 수 있어~",
  str_guide_warn_11400105 = "이벤트에 참가하면 특별 사건부의 임무를 완료할 수 있어.",
  str_guide_warn_11400106 = "매일 출석하면 보상을 수령할 수 있으니까, 매일 로그인하는 것도 잊지 말아줘.",
  str_guide_warn_11400107 = "이벤트에 대해 더 궁금한 점이 있다면, 이벤트의 상세 규칙을 확인해 봐.",
  str_guide_warn_11500101 = "「표류하는 별하늘—창궁을 울리는 악장」 이벤트가 시작됐어! 골디와 함께 지금까진 없었던 멋진 콘서트를 열어보자!",
  str_guide_warn_11500102 = "「꿈의 회상」에서 우리는 어려운 시험과 마주하게 될 거야.",
  str_guide_warn_11500103 = "이벤트 스테이지를 완료하거나 프리즘을 소모해서 획득한 「골디 굿즈」는 「브랜디의 취재 활동」에서 각종 보상 아이템으로 교환할 수 있어.",
  str_guide_warn_11500104 = "비경 주변에 정체불명의 암귀 소굴이 나타났어. 조종사! 이능력 스킬과 성물을 사용해서 스테이지를 클리어하면 루맘버 보상을 얻을 수 있어!",
  str_guide_warn_11500105 = "「스타 엔터테인먼트」에서 골디의 프로듀서가 되어 트레이닝을 진행하고, 골디의 아이돌 능력을 개발해 보자. 아이돌 이벤트를 펼쳐 꾸준히 팬을 모아 골디가 콘서트 무대에 설 수 있도록 도와줘!",
  str_guide_warn_11500106 = "이벤트에 참가하면 특별 사건부의 임무를 완료할 수 있어.",
  str_guide_warn_11500107 = "매일 출석하면 보상을 수령할 수 있으니까, 매일 로그인하는 것도 잊지 말아줘.",
  str_guide_warn_11500108 = "이벤트에 대해 더 궁금한 점이 있다면, 이벤트의 상세 규칙을 확인해 봐.",
  str_guide_warn_11500201 = "조종사! 이제 실전을 시작해 보자! 여기가 바로 스타 엔터테인먼트야. 여기서 아이돌 트레이닝과 아이돌 이벤트를 진행할 수 있고, 마지막엔 콘서트 무대에 설 수 있어~",
  str_guide_warn_11500202 = "기획사에서 우리한테 성과 목표를 지정해 줬어. 목표를 달성하면 보상을 얻을 수 있어! 아이돌 트레이닝 기간의 추억들은 여기 기록될 거야.",
  str_guide_warn_11500203 = "트레이닝이 만족스럽지 못해도 너무 걱정하지 마~ 여기서 타임포인트를 선택해서 다시 결정할 수 있으니까!",
  str_guide_warn_11500204 = "그럼 지금부터 아이돌 트레이닝을 시작해 보자~",
  str_guide_warn_11500301 = "여기 보이는 건 콘서트까지 남은 기간이야. 13일 남았네! 열심히 해 보자!",
  str_guide_warn_11500302 = "그전까지 내 팬이 150,000명이 되어야 콘서트를 열 수 있어.",
  str_guide_warn_11500303 = "아이돌이라면 트레이닝은 필수지! 트레이닝은 세 종류가 있어. 트레이닝 중 갑자기 파파라치 기자가 들이닥칠 수도 있으니까 침착하게 대응해야 해!",
  str_guide_warn_11500304 = "여기선 내 아이돌 능력을 볼 수 있어. 아이돌 트레이닝에 따라 능력치가 증가할 거야.",
  str_guide_warn_11500305 = "아이돌 이벤트를 개최하면 팬이 늘어나. 콘서트에 필요한 팬 수를 향해 힘내보자!",
  str_guide_warn_11500306 = "이건 이번 주에 해야 할 일이야. 스케줄에 참고할 수 있어. 트레이닝 중에 다른 사람들과 이야기를 하면 의외의 수확이 있을지도 몰라.",
  str_guide_warn_11500307 = "다른 자세한 사항들은 프로듀서 수첩에 기록되어 있으니까 언제든지 확인해 봐~",
  str_guide_warn_11500402 = "악의 소굴에 도전하면 루맘버를 얻을 수 있고, 함께 획득하는 「이능력 경험치」로 이능력 레벨을 높여서 「이능력 포인트」로 전투력을 향상시킬 수 있어~",
  str_guide_warn_11500403 = "이건 악의 소굴의 현상금 퀘스트야. 퀘스트를 완료하면 「이능력 포인트」를 보상으로 획득할 수 있어.",
  str_guide_warn_11500404 = "「이능력 포인트」를 사용하면 강력한 효과를 지닌 「이능력 스킬」, 「아이테르 특수 장비」, 「성물」이 개방돼! 전투에 큰 도움이 될 거야~",
  str_guide_warn_11500405 = "「소굴 도전」에서는 매일 무료로 사용할 수 있는 오로리안이 있어.",
  str_guide_warn_11500406 = "이곳에선 악의 소굴에 대한 상세한 정보를 볼 수 있으니 한번 확인해 봐~",
  str_guide_warn_11500601 = "충분한 「이능력 경험치」를 획득하면 이능력 레벨이 상승하고 「이능력 포인트」를 얻을 수 있어.",
  str_guide_warn_11500602 = "「이능력 포인트」를 사용하면 「아이테르 특수 장비」를 포함해서 다양한 「이능력」을 활성화할 수 있고, 파티의 전투력을 높일 수 있어.",
  str_guide_warn_11500603 = "충분한 「이능력 포인트」를 사용하면 강력한 「성물」이 개방될 거야. 소굴 도전 중에 발견할 수 있어.",
  str_guide_warn_11500604 = "여기서는 「아이테르 특수 장비」를 교체할 수 있어. 장비를 휴대하면 전투 중에 강력한 스킬을 시전할 수 있어.",
  str_guide_warn_11500605 = "이능력을 수정하고 싶으면 언제든지 손실 없이 활성화했던 이능력 포인트를 초기화할 수 있어!",
  str_guide_warn_11500701 = "여길 터치하면 파티 내 오로리안을 확인할 수 있어.",
  str_guide_warn_11600101 = "「바다에 새겨진 방주」 이벤트가 시작됐어! 「신풍의 귀향」에서 우린 용주에서 온 새로운 친구들과 함께 잃어버린 보물을 찾고, 그 뒤에 숨겨진 신비한 진실을 밝혀내게 될 거야...",
  str_guide_warn_11600102 = "「배의 무덤」에서 우린 어려운 시험과 마주하게 될 거야.",
  str_guide_warn_11600103 = "이벤트 스테이지를 완료하거나 프리즘을 소모해서 획득한 「린 가문 상회 어음」은 「부둣가 상점」에서 각종 보상 아이템으로 교환할 수 있어.",
  str_guide_warn_11600104 = "춘삭절이 되면 용주 사람들은 아주 풍성한 「제야 만찬」을 만들 거야. 단당 씨를 도와서 요리법을 찾고 요리를 제작하면 루맘버와 다양한 보상을 획득할 수 있어~",
  str_guide_warn_11600105 = "촬영장에서 익명의 방명록이 발견됐어! 시간이 지날수록 방명록 내 익명의 메시지가 하나씩 개방된다고 해. 메시지를 읽으면 새로운 영화 시나리오를 획득할 수 있어!",
  str_guide_warn_11600106 = "이벤트에 참가하면 특별 사건부의 임무를 완료할 수 있어.",
  str_guide_warn_11600107 = "매일 출석하면 보상을 수령할 수 있으니까, 매일 로그인하는 것도 잊지 말아줘.",
  str_guide_warn_11600108 = "이벤트에 대해 더 궁금한 점이 있다면, 이벤트의 상세 규칙을 확인해 봐.",
  str_guide_warn_11700101 = "「한쪽 날개의 맹세」 이벤트가 시작됐어! 「관월의 순례」에서 우린 쿠리어 길드의 새로운 친구들과 새로운 모험을 시작할 거야.",
  str_guide_warn_11700102 = "「깃털 도장의 위기」에서 우린 어려운 시험과 마주하게 될 거야.",
  str_guide_warn_11700103 = "이벤트 스테이지를 완료하거나 프리즘을 소모해서 획득한 「희귀한 오색 깃털」은 「특급 배송」에서 각종 보상 추첨에 사용할 수 있어.",
  str_guide_warn_11700104 = "「두근두근 딜리버리」에서 우린 쿠리어 센터 업무를 체험하면서, 조종사의 “축복 편지\" 대위기를 해결할 거야!",
  str_guide_warn_11700105 = "이벤트에 참가하면 특별 사건부의 임무를 완료할 수 있어.",
  str_guide_warn_11700106 = "매일 출석하면 보상을 수령할 수 있으니까, 매일 로그인하는 것도 잊지 말아줘.",
  str_guide_warn_11700107 = "이벤트에 대해 더 궁금한 점이 있다면, 이벤트의 상세 규칙을 확인해 봐.",
  str_guide_warn_11700201 = "여기서 지금 접수한 주문 정보를 볼 수 있어. 그리고 초상화를 누르면 주문을 전환할 수 있어.",
  str_guide_warn_11700202 = "우선 리리카의 주문을 완료하자. 리리카는 옷, 빵, 레드와인이 필요하대.",
  str_guide_warn_11700203 = "오른쪽에서는 모든 화물 목록을 볼 수 있어.",
  str_guide_warn_11700204 = "빵을 집어서 소포 안으로 넣어보자~",
  str_guide_warn_11700205 = "화물을 길게 누른 상태에서 동시에 키를 입력해서 회전(R키)시키거나 뒤집을(T키) 수도 있어.",
  str_guide_warn_117002051 = "화물을 길게 누른 상태에서 동시에 버튼을 눌러서 회전시키거나 뒤집을 수도 있어.",
  str_guide_warn_11700206 = "모든 주문 내용을 넣은 다음에 포장 버튼을 눌러야 소포를 발송할 수 있어. 다 넣지 않았다면 최종 주문 완성도에 영향을 미치게 될 거야.",
  str_guide_warn_11700207 = "여길 누르면 포장을 잠시 멈출 수 있어.",
  str_guide_warn_11700208 = "업무 프로세스 설명은 이걸로 끝났어. 이제 포장을 계속해 보자~",
  str_guide_warn_11800101 = "「고백은 재판이 끝나기 전에」 이벤트가 시작됐어! 「진심어린 고백」에서 우린 심판소의 새로운 사람들과 새로운 모험을 시작할 거야.",
  str_guide_warn_11800102 = "「꽃이 지기 전에」에서 우린 어려운 시험과 마주하게 될 거야.",
  str_guide_warn_11800103 = "이벤트 스테이지를 완료하거나 프리즘을 소모해서 획득한 「이상한 석고 조각」은 「증거물 현상」에서 각종 보상 아이템으로 교환할 수 있어.",
  str_guide_warn_11800104 = "「러브 저지먼트」에서는 심판관의 조수가 되어 연애 지부의 동료들과 함께 사건을 재판하고, 진상을 조사하게 될 거야~",
  str_guide_warn_11800105 = "이벤트에 참가하면 특별 사건부의 임무를 완료할 수 있어.",
  str_guide_warn_11800106 = "매일 출석하면 보상을 수령할 수 있으니까, 매일 로그인하는 것도 잊지 말아줘.",
  str_guide_warn_11800107 = "이벤트에 대해 더 궁금한 점이 있다면, 이벤트의 상세 규칙을 확인해 봐.",
  str_guide_warn_11800201 = "아무나 백야성 심판소에서 일할 수 있는 건 아니니까, 내가 너라면 이 기회를 꼭 잡을 거야! 여길 눌러서 어떤 사건들이 심판소에서 널 기다리고 있는지 확인해 봐~",
  str_guide_warn_11800202 = "사건의 재판에는 여러 결말이 존재해. 조사가 막히면 언제든지 「사건 기록」을 통해 해당 스토리 분기로 이동해서 다른 선택을 할 수 있어.",
  str_guide_warn_11800203 = "수고에는 대가가 있기 마련이야. 스토리 엔딩을 클리어하고 각종 조건을 달성하면 여기서 훈장과 보상을 받을 수 있어!",
  str_guide_warn_11800204 = "자세한 설명은 여기 적어 두었으니까, 모르는 게 있으면 확인해 봐~",
  str_guide_warn_11800301 = "우와, 벌써 「증거」를 수집하는 방법을 알아낸 거야? 그럼 이제 「증거 제시」의 순간에 이 「증거」들을 사용할 수 있을 거야.",
  str_guide_warn_11800401 = "맞아. 지금이 바로 「증거 제시」의 순간이야! 수집한 증거는 증거 목록에서 확인할 수 있어. 증거의 자세한 내용을 확인해 두는 것도 잊으면 안 돼.",
  str_guide_warn_11800402 = "증거 제시에 실패하면 「적성도」가 감소하고, 재판의 방향에도 영향을 미칠 수 있어! 이제 안젤의 질문에 따라 정확한 증거를 선택해 보자. 여길 눌러서 반격하는 거야!",
  str_guide_warn_11800501 = "심판관의 노트는 심판관 신분의 상징이야. 안에 어떤 내용이 적혀 있을지 궁금하지?",
  str_guide_warn_11800502 = "헤에~ 수집한 증거랑 자세한 정보가 기록되어 있었구나. 살펴보기도 무척 편리하겠는걸.",
  str_guide_warn_11800503 = "동료들과의 「협력도」를 높이는 것도 무척 중요해. 동료들과의 팀워크가 사건 재판의 영향을 미칠 테니까. 그럼 파이팅~",
  str_guide_warn_11800601 = "내가 기본 규칙을 설명해 줄게! 이 게임에서는 캐릭터를 조작해 스테이지를 전부 클리어하고, 최종 보스인 그롱켄슈타인누한테 도전해야 해!",
  str_guide_warn_11800602 = "버튼을 누르면 캐릭터를 변경할 수 있어. 근데 어떤 캐릭터든 스킬은 똑같아. 에잇, 그런 걸로 태클 걸지 마!",
  str_guide_warn_11800603 = "뭔가 모르는 게 있으면 이 설명 파일을 봐.",
  str_guide_warn_11800701 = "스테이지는 시간이 지나면 개방될 거야. 일단 첫 번째 스테이지부터 해 보자!",
  str_guide_warn_11800702 = "각 스테이지의 첫 번째 목표만 달성해도 클리어로 간주될 거야! 물론 모든 목표 달성을 목표로 삼는 게 좋겠지!",
  str_guide_warn_11800703 = "그럼 바로 시작하자!",
  str_guide_warn_11800801 = "자, 시작이야! 캐릭터가 암귀와 부딪히지 않게 주의하면서 앞으로 전진하는 거야! 스테이지 목표를 달성할 수 있게 힘내 봐!",
  str_guide_warn_11800802 = "일반 암귀 한 마리가 앞에 있어! 타이밍을 맞춰서 점프해 머리를 밟으면 쓰러트릴 수 있어!",
  str_guide_warn_11800803 = "지금이야! 「점프」 버튼을 눌러!",
  str_guide_warn_118008031 = "지금이야! 점프 버튼(T키)을 눌러!",
  str_guide_warn_11800804 = "꽤 하잖아~ 이해가 빠른 모양이네!",
  str_guide_warn_11800805 = "다음은 날아다니는 암귀를 상대하는 방법이야. 점프한 뒤에 2단 점프를 하면 높은 곳에 있는 암귀를 공격할 수 있어!",
  str_guide_warn_11800806 = "지금이야! 「점프」를 눌러!",
  str_guide_warn_11800807 = "다시 한번 「점프」를 눌러서 2단 점프로 공격해!",
  str_guide_warn_11800808 = "이걸로 기본 조작은 익혔네! 그럼 이제 직접 이 스테이지를 클리어해 봐!",
  str_guide_warn_11800901 = "조종사, 혹시 지금 첫 스테이지는 너무 쉽다고, 바보 취급하는거 아니냐고 말한 거야~?",
  str_guide_warn_11800902 = "그래서 더 강한 몬스터가 나타났어! 이 투구를 쓴 암귀는 두 번 밟아야 처치할 수 있어!",
  str_guide_warn_11800903 = "「점프」를 눌러서 일단 한 번 공격해!",
  str_guide_warn_11800904 = "그리고 공중에서 「낙하」를 누르면 빠르게 내려와서 아래쪽의 적을 공격할 수 있어!",
  str_guide_warn_118009041 = "그리고 공중에서 「낙하」(R키)를 누르면 빠르게 내려와서 아래쪽의 적을 공격할 수 있어!",
  str_guide_warn_11800905 = "약간의 요령을 알려줄게. 가속해서 낙하하면 적도 공격할 수 있고, 자신도 튕겨서 더 높이 날 수 있거든. 그럼 하늘에 있는 적을 공격하기도 쉬울 거야!",
  str_guide_warn_11800906 = "아, 진짜 진짜 마지막 힌트야! 이 가시가 있는 암귀는 밟아도 처치할 수 없으니까 피하는 게 좋아! 자, 이제 나머지는 너한테 달렸어, 조종사! 그럼 행운을 빌게!",
  str_guide_warn_11801001 = "아하하하하! 드디어 라스트 보스 그롱켄슈타인누가 등장할 차례네!",
  str_guide_warn_11801101 = "이건 라스트 보스인 내가 쏘는 하트 포탄이야! 절대 「가속 낙하」나 「2단 점프」 같은 걸로 포탄을 튕기지 마! 그랬다간 내가 널 공격할 수가 없으니까!",
  str_guide_warn_11801201 = "앗! 어, 어떻게 나한테 이럴 수가 있어! 내 포탄이 튕겨서 이쪽으로 돌아오잖아!",
  str_guide_warn_11801202 = "내 HP는 이것밖에 안 남았어. 이대로 포탄 공격을 계속 받는다면... 에이, 근데 조종사가 그런 대단한 컨트롤 실력이 있을 리가 없잖아? 분명히 괜찮을 거야! 자, 그럼 얼마든지 덤벼보라구!",
  str_guide_warn_11900101 = "「검은 불길의 유령」 이벤트가 시작됐어! 우린 「진상을 쫓는 불꽃」에서 움브라톤의 친구들과 함께 비밀스러운 사건을 조사하고 배후의 진상을 찾게 될 거야~",
  str_guide_warn_11900102 = "「검은 거리의 만남」에서 우린 어려운 시험과 마주하게 될 거야.",
  str_guide_warn_11900103 = "이벤트 스테이지를 완료하거나 프리즘을 소모해서 획득한 「증거 수집 기록」은 「증거 수집」에서 각종 보상 아이템으로 교환할 수 있어.",
  str_guide_warn_11900104 = "「한밤중의 낙서」 추리 이벤트에서는 어린 시절의 하티와 함께 고아원의 비밀을 파헤쳐 볼 수 있어~",
  str_guide_warn_11900105 = "그리고 「난동 대작전」이 다시 돌아왔어! 여기서는 특수한 「모의 전투」를 체험할 수 있어.",
  str_guide_warn_11900106 = "이벤트에 참가하면 특별 사건부의 임무를 완료할 수 있어.",
  str_guide_warn_11900107 = "매일 출석하면 보상을 수령할 수 있으니까, 매일 로그인하는 것도 잊지 말아줘.",
  str_guide_warn_11900108 = "이벤트에 대해 더 궁금한 점이 있다면, 이벤트의 상세 규칙을 확인해 봐.",
  str_guide_warn_11900201 = "「한밤중의 낙서」에 찾아온 걸 환영해! 여기서 우린 옛날에 고아원에 있었던 일들을 함께 알아볼 거야!",
  str_guide_warn_11900202 = "「크레파스 들기」를 누르면 시작할 수 있어!",
  str_guide_warn_11900203 = "이미 보고 있던 기억이 있다면 여길 눌러서 기억 속 여행을 이어갈 수 있어!",
  str_guide_warn_11900204 = "그림책에는 퀘스트와 보상이 표시될 거야. 그리고 달성한 엔딩도 볼 수 있어!",
  str_guide_warn_11900205 = "뭔가 모르는 게 있으면 여기 설명을 보면 돼~",
  str_guide_warn_11900301 = "이건 고아원 지도야. 우린 이곳저곳을 탐험하면서 「영감」을 수집해야 해!",
  str_guide_warn_11900302 = "수집된 영감은 여기 표시될 거야. 그리고 나중에 유용하게 쓰일 거라구!",
  str_guide_warn_11900303 = "먼저 보육교사 선생님한테 인사하러 가자!",
  str_guide_warn_11900304 = "같이 이곳의 일에 대해 물어보는 거야!",
  str_guide_warn_11900401 = "선생님이랑 대화할 준비는 됐어?",
  str_guide_warn_11900402 = "여기 질문할 수 있는 문제를 모아봤어. 어떤 건 바로 질문할 수 있고, 어떤 건 질문 전에 어떤 「영감」을 얻어야 질문할 수 있어!",
  str_guide_warn_11900403 = "이곳에 대해 물어보자!",
  str_guide_warn_11900404 = "이렇게 탐색하면서 상황을 파악하면 「영감」을 얻을 수 있어! 새로운 영감을 얻으면 새로운 질문을 할 수 있게 될 거야!",
  str_guide_warn_11900501 = "여긴 정말 엉망이네. 자세히 좀 조사해봐야 할 것 같아!",
  str_guide_warn_11900502 = "방에 수상한 물건이 얼마나 있는지 여기서 확인할 수 있어!",
  str_guide_warn_11900503 = "단서가 없는 것 같으니까 일단 집중해서 관찰해 보자.",
  str_guide_warn_11900504 = "여기 이상한 장갑이 있는데? 가까이서 확인해 보자!",
  str_guide_warn_11900601 = "그럼 이제 「영감」을 정리하고, 오늘 있었던 일을 되돌아보자!",
  str_guide_warn_11900602 = "이 문제를 해결하려면 3개의 영감을 얻어야 답을 찾을 수 있어.",
  str_guide_warn_11900603 = "이건 지금 얻은 모든 영감이야. 정확한 영감을 선택해 봐!",
  str_guide_warn_11900604 = "어디 보자, 일단 여긴... 왠지 「사랑이 가득한 새로운 집」 같은데?",
  str_guide_warn_11900605 = "그리고 우리랑 같이 지내는 건 당연히 「아이들」이지. 고아원엔 아이들이 많아!",
  str_guide_warn_11900606 = "마지막으로 다들 좋은 사람들일까? 친절한 사람도 있지만, 왠지 불친절한 녀석도 있는 것 같아... 아무래도 앞으로 잘 구분해봐야 할 것 같네.",
  str_guide_warn_11900607 = "그럼 영감을 정리해서 시도해 봐!",
  str_guide_warn_11900608 = "성공했어! 고아원의 상황은 이런 거였구나!",
  str_guide_name1 = "내 닉네임은...?",
  str_guide_name2 = "닉네임을 입력해 주세요.",
  str_guide_name3 = "일지 서명",
  str_guide_name4 = "닉네임은 실명을 사용하지 않아도 됩니다.\n특수문자를 사용할 수 없으며, 최대 7글자까지 가능합니다.",
  str_guide_create_no_name = "먼저 당신의 닉네임을 서명해 주세요.",
  str_guide_ROLE_ERROR_DIRTY_NICK = "금지어가 포함되어 있습니다.",
  str_guide_ROLE_ERROR_CHANGE_NICK_INVALID = "특수문자는 사용할 수 없습니다.",
  str_guide_ROLE_ERROR_CHANGE_NICK_LIMIT = "닉네임은 한글 7글자 또는 반각 문자 14글자까지 사용할 수 있습니다.",
  str_guide_ROLE_ERROR_CHANGE_NICK_REPEAT = "이미 닉네임을 가지고 있습니다.",
  str_guide_ROLE_ERROR_CHANGE_NICK_SPE = "특수문자는 사용할 수 없습니다.",
  str_guide_ROLE_ERROR_DUPLICATE_NICK = "다른 플레이어와 중복된 닉네임입니다.",
  str_guide_ROLE_ERROR_NEWSIGN_THE_SAME_AS_OLD = "이전 서명과 동일합니다.",
  str_guide_ROLE_ERROR_NEWNAME_THE_SAME_AS_OLD = "이전 닉네임과 동일합니다.",
  str_guide_moren_name = "조종사",
  str_guide_team_limit_4001050 = "이번 모험에는 반드시 Ms. 블랑이 등장해야 합니다. 상단의 카드를 터치해 출전 오로리안을 변경해 주세요.",
  str_guide_circle_click = "화면을 터치해 계속 진행",
  str_guide_circle_1_Lt = "오토 디펜스 장치(ADS)는 옛 시대의 유산입니다. 자동으로 운행되며, 큰 위력을 발휘합니다.",
  str_guide_circle_1_LtT = "오토 디펜스 장치(ADS)",
  str_guide_circle_1_Rt = "오토 디펜스 장치는 턴마다 1회씩 자동으로 방향을 바꿉니다. 아마 옛 시대의 설정인 것 같습니다.",
  str_guide_circle_1_RtT = "행동 규칙",
  str_guide_circle_1_Rb = "오토 디펜스 장치는 전방 3칸 내의 모든 대상에게 피해를 입힙니다.",
  str_guide_circle_1_RbT = "피해 범위",
  str_guide_circle_2_Lt = "「아이언 비스트」는 비교적 흔하게 볼 수 있는 대형 암귀로, HP와 공격력이 높은 편입니다.",
  str_guide_circle_2_LtT = "아이언 비스트",
  str_guide_circle_2_Lb = "큰 체형일수록 더 많은 피해를 입습니다. 연결을 통해 최대한 주변 칸으로 접근하세요.",
  str_guide_circle_2_LbT = "중요 알림",
  str_guide_circle_3_Lb = "비교적 높은 피해를 입히며, 짧은 시간 안에 처치하기 어려우니 HP 회복에 유의하세요.",
  str_guide_circle_3_LbT = "중요 알림",
  str_guide_circle_3_Lt = "원거리 공격형 암귀로, 가로열 또는 세로열 위의 단일 유닛에게 피해를 입힐 수 있습니다.",
  str_guide_circle_3_LtT = "프로버",
