  ["str_guide_circle_7-7_Lt"] = "상성 관계 속성의 공격을 받아야만 정상적인 피해를 입힐 수 있는 암귀입니다.",
  ["str_guide_circle_7-7_LtT"] = "강화 속성 암귀",
  ["str_guide_circle_7-7_Lb"] = "상성 관계가 아닌 속성 피해는 감소하며, 불리한 상성일 경우 피해가 대폭 감소합니다.",
  ["str_guide_circle_7-7_LbT"] = "스페셜 팁",
  ["str_guide_circle_1-7BOSS_Lb"] = "고대의 샌드버그 일족으로, 발군의 전투 능력을 지녔습니다.",
  ["str_guide_circle_1-7BOSS_LbT"] = "카라켄",
  ["str_guide_circle_1-7BOSS_Rb"] = "전방 범위 내 대상을 공격하고, 땅 밑으로 파고 들어간 뒤 다시 나타나 주변 대상에게 피해를 입힙니다.",
  ["str_guide_circle_1-7BOSS_RbT"] = "주요 스킬",
  ["str_guide_circle_1-13BOSS_Lb"] = "특별한 고위 암귀 중 하나로, 뛰어난 전투 능력을 지녔으며, 다른 암귀들을 지휘합니다.",
  ["str_guide_circle_1-13BOSS_LbT"] = "맥거핀",
  ["str_guide_circle_1-13BOSS_Rb"] = "거대한 발톱으로 눈앞의 다수 유닛을 공격하며, 공중으로 날아올라 지면에 범위 폭격을 가합니다.",
  ["str_guide_circle_1-13BOSS_RbT"] = "주요 스킬",
  ["str_guide_circle_2-6BOSS_Lt"] = "거대한 암귀로, 엄청난 고통을 받아 이렇게 변했다고 합니다.",
  ["str_guide_circle_2-6BOSS_LtT"] = "아비시어",
  ["str_guide_circle_2-6BOSS_Lb"] = "공격으로 발생한 여파는 밀쳐내기 효과가 있으며, 암석을 소환할 수 있습니다.",
  ["str_guide_circle_2-6BOSS_LbT"] = "주요 스킬",
  ["str_guide_circle_2-6BOSS_Rb"] = "아비시어가 소환해낸 암석들을 한 덩어리의 「운석」으로 만들어 적을 공격합니다.",
  ["str_guide_circle_2-6BOSS_RbT"] = "궁극 스킬",
  ["str_guide_circle_2-12BOSS_Lt"] = "맥거핀이 다시 돌아왔습니다. 부활한 맥거핀은 전투에 대한 욕망이 더 강렬해졌습니다.",
  ["str_guide_circle_2-12BOSS_LtT"] = "맥거핀",
  ["str_guide_circle_2-12BOSS_Lb"] = "지금의 맥거핀은 대량의 범위 피해를 입힐 수 있습니다. 조심해서 상대하세요.",
  ["str_guide_circle_2-12BOSS_LbT"] = "주요 스킬",
