  ["str_guide_circle_3-6BOSS_LbT"] = "필릭스",
  ["str_guide_circle_3-6BOSS_Rb"] = "근거리 공격으로 대상을 밀쳐낼 수 있으며, 스킬로 대상을 기절시킬 수 있습니다.",
  ["str_guide_circle_3-6BOSS_RbT"] = "공격 특성",
  ["str_guide_circle_3-6BOSS2_Lb"] = "멘델슨을 지키는 생물이었지만, 알 수 없는 이유로 큰 적대감을 드러내고 있습니다.",
  ["str_guide_circle_3-6BOSS2_LbT"] = "피니",
