  ["str_guide_circle_3-6BOSS2_RbT"] = "공격 특성",
  ["str_guide_circle_3-12BOSS_Lt"] = "고위 암귀로, 전투 구역에 소이탄을 투척하며, 대상에게 돌격하여 기절시킬 수 있습니다.",
  ["str_guide_circle_3-12BOSS_LtT"] = "타바드",
