  ["str_guide_circle_4-6BOSS_LbT"] = "스예트",
  ["str_guide_circle_4-6BOSS_Rb"] = "자신 주변 1서클에 범위 피해를 입히고 스턴시키며, 샤를이 처치되면 광폭 상태가 됩니다.",
  ["str_guide_circle_4-6BOSS_RbT"] = "공격 범위",
  ["str_guide_circle_4-12BOSS_Lt"] = "암귀 자매의 융합체로, 격렬한 고통 속에 몸부림치고 있습니다.",
  ["str_guide_circle_4-12BOSS_LtT"] = "보레돔",
  ["str_guide_circle_4-12BOSS_Lb"] = "구역 속성을 자신의 에너지로 바꿔서 큰 범위 공격을 시전할 수 있습니다.",
  ["str_guide_circle_4-12BOSS_LbT"] = "공격 범위",
  ["str_guide_circle_4-12BOSS_Rb"] = "일반 공격에 밀쳐내기 효과가 있으며, 속성마다 피해 범위가 다릅니다.",
  ["str_guide_circle_4-12BOSS_RbT"] = "스페셜 팁",
  ["str_guide_circle_4-6BOSS2_Lt"] = "신비한 고위 암귀로, 포악한 성격입니다.",
  ["str_guide_circle_4-6BOSS2_LtT"] = "샤를",
