  ["str_guide_circle_5-6BOSS2_Rt"] = "넓은 범위의 마법을 사용할 수 있습니다. 낙뢰 룬을 소환해 낙뢰로 크로스 공격을 가합니다.",
  ["str_guide_circle_5-6BOSS2_RtT"] = "공격 범위",
  ["str_guide_circle_5-12BOSS_Lb"] = "고대에서 온 공포의 콜로서스를 타고 있으며, 일반공격 저항 효과를 지녀 일반공격으로 받는 피해가 감소합니다.",
  ["str_guide_circle_5-12BOSS_LbT"] = "슈모르(디바우러)",
  ["str_guide_circle_5-12BOSS_Rb"] = "남은 HP가 30%가 되면 광폭 모드에 진입하며, 연속으로 대규모 범위 피해를 입힙니다.",
  ["str_guide_circle_5-12BOSS_RbT"] = "공격 범위",
