  ["str_guide_circle_8-9_Lt"] = "공격 시 오로리안의 에너지를 없애며, 액티브 스킬의 쿨다운 턴 수를 증가시킵니다.",
  ["str_guide_circle_8-9_LtT"] = "스펜드",
  ["str_guide_circle_8-9_Lb"] = "액티브 스킬을 시전할 수 없게 될 수 있으므로, 최대한 빨리 처치해야 합니다.",
