  ["str_guide_circle_8-14_Lb"] = "공격 시 오로리안의 에너지를 없애며, 액티브 스킬의 쿨다운 턴 수를 증가시킵니다.",
  ["str_guide_circle_8-14_LbT"] = "공격 특성",
  ["str_guide_circle_9-2_Lt"] = "자신의 주변 칸을 잠그는 암귀입니다. 공격 대상 주변 1서클의 칸도 잠글 수 있습니다.",
