  ["str_guide_circle_10-9_LtT"] = "커스",
  ["str_guide_circle_10-9_Lb"] = "커스를 처치하면 해당 커스와 동일한 속성의 오로리안에게 걸린 저주를 제거할 수 있습니다.",
  ["str_guide_circle_10-9_LbT"] = "상대 전략",
  ["str_guide_circle_9-7BOSS_Lt"] = "자신 주변의 비교적 넓은 범위의 칸을 잠그는 강력한 암귀입니다.",
  ["str_guide_circle_9-7BOSS_LtT"] = "레체",
  ["str_guide_circle_9-14BOSS_Lb"] = "타바드의 유전자를 주입해 만든 강력한 암귀로, 강력한 힘을 가지고 있지만, 주인에게 절대적으로 복종합니다.",
  ["str_guide_circle_9-14BOSS_LbT"] = "매드혼",
  ["str_guide_circle_9-14BOSS_Rb"] = "매드혼의 거리가 대상과 멀수록 매드혼이 입히는 피해가 증가합니다.",
  ["str_guide_circle_9-14BOSS_RbT"] = "주의",
  ["str_guide_circle_10-7BOSS_Lt"] = "노라의 새로운 장난감이 더욱 강력해졌습니다. 필드의 칸을 부술 수 있습니다.",
  ["str_guide_circle_10-7BOSS_LtT"] = "보레돔·소브라스",
  ["str_guide_circle_10-7BOSS_Rt"] = "오로리안이 액티브 스킬 시전 시 소브라스가 랜덤으로 필드의 칸을 부숩니다.",
  ["str_guide_circle_10-7BOSS_RtT"] = "주의",
  ["str_guide_circle_10-14BOSS_Lt"] = "몸속의 씨앗이 성장한 후 막대한 에너지를 흡수했습니다. 이전과는 비교가 되지 않을 정도의 강력한 힘을 가지고 있습니다.",
  ["str_guide_circle_10-14BOSS_LtT"] = "백색의 슈모르",
  ["str_guide_circle_10-14BOSS_Rt"] = "필드에 4마리의 악령이 존재합니다. 턴마다 순서대로 악령 1마리를 활성화하며, 동일 속성의 오로리안에게 저주를 겁니다.",
  ["str_guide_circle_10-14BOSS_RtT"] = "슈모르의 악령",
