  ["str_guide_circle_10-14BOSS_LbT"] = "루미나의 멸화",
  ["str_guide_circle_10-14BOSS_Rb"] = "오로라 타임을 발동시키면 슈모르의 악령이 건 저주 상태를 초기화할 수 있습니다!",
  ["str_guide_circle_10-14BOSS_RbT"] = "스페셜 팁",
  ["str_guide_circle_9-14Trap_Lb"] = "강력해 보이는 상대입니다. 은밀한 힘으로 턴마다 대상을 넉백시킵니다.",
  ["str_guide_circle_9-14Trap_LbT"] = "노라",
  ["str_guide_circle_10s-2_LtT"] = "웨일",
  ["str_guide_circle_10s-2_Lt"] = "그림자 속에서 움직이는 암귀로, 주로 밤에 활동합니다. 낮에는 땅에 엎드려 움직일 수 없습니다.",
  ["str_guide_circle_10s-2_RtT"] = "특성",
  ["str_guide_circle_10s-2_Rt"] = "낮에는 땅에 엎드려 방어 상태가 되며, 범위 피해 유형의 공격만 받습니다. 밤이 되면 전투 시작 시의 상태를 회복하며, 행동을 시작합니다.",
  ["str_guide_circle_10s-4_LtT"] = "공포의 암귀",
  ["str_guide_circle_10s-4_Lt"] = "폐허에서 오랜 시간 홀로 생존해 온 강력한 암귀입니다. 이성을 잃고 모든 외부인을 공격합니다.",
  ["str_guide_circle_10s-4_RtT"] = "주의",
  ["str_guide_circle_10s-4_Rt"] = "낮에 피해를 입으면 피해량에 따라 적혈 수치를 누적합니다. 오로리안이 액티브 스킬을 시전할 때마다 누적된 적혈 수치를 HP로 전환합니다.",
  ["str_guide_circle_10s-9_LtT"] = "헬리오스",
  ["str_guide_circle_10s-9_Lt"] = "한때 일루미나의 군인이었으나 다크매터에 침식당해 암귀가 되었습니다. 이미 증오로 인해 이성을 잃고 과거의 영광을 잊어버렸습니다.",
  ["str_guide_circle_10s-9_RtT"] = "주의",
  ["str_guide_circle_10s-9_Rt"] = "헬리오스는 밤에 더욱 강력해지며, 턴마다 최대 3회 행동할 수 있습니다. 또한 오로리안의 위치에 따라 다른 스킬을 시전합니다.",
  ["str_guide_circle_12-6_LtT"] = "어둠의 영역",
  ["str_guide_circle_12-6_Lt"] = "강력한 암귀가 생성한 비밀의 영역입니다. 종종 넓게 나타나며, 오로리안은 발을 들일 수 없습니다.",
  ["str_guide_circle_jianta-5-BOSS_Lb"] = "암석 속성의 강화 블랙혼을 소환할 수 있어 상대하기 매우 성가십니다.",
  ["str_guide_circle_jianta-5-BOSS_LbT"] = "블랙혼(강화)",
  ["str_guide_circle_jianta-5-BOSS_Rb"] = "블랙혼은 몇 턴마다 필드의 자갈을 수집해 극도로 큰 피해를 줍니다.",
  ["str_guide_circle_jianta-5-BOSS_RbT"] = "스페셜 팁",
  ["str_guide_circle_jianta-10-BOSS_Lt"] = "자신을 거울 안에 감추는 특수한 암귀입니다.",
  ["str_guide_circle_jianta-10-BOSS_LtT"] = "스페큘러",
  ["str_guide_circle_jianta-10-BOSS_Lb"] = "본체가 들어 있는 거울만 공격할 수 있습니다. 충돌 공격을 조심해야 합니다.",
  ["str_guide_circle_jianta-10-BOSS_LbT"] = "스페셜 팁",
  ["str_guide_circle_jianta-15-BOSS_Lb"] = "한때는 백야성의 오로리안이었습니다. 그의 포효를 조심해야 합니다.",
  ["str_guide_circle_jianta-15-BOSS_LbT"] = "거츠더",
  ["str_guide_circle_jianta-15-BOSS_Rb"] = "적의 공격을 감소시키고, 적이 지닌 디버프 효과를 기폭제로 삼아 피해를 입힙니다.",
  ["str_guide_circle_jianta-15-BOSS_RbT"] = "스페셜 팁",
  ["str_guide_circle_jianta-20-BOSS_Lb"] = "실러가 변이하여 탄생한 것으로, 오로리안을 극도로 증오합니다.",
  ["str_guide_circle_jianta-20-BOSS_LbT"] = "솔모프",
  ["str_guide_circle_jianta-20-BOSS_Rb"] = "원거리 공격이 가능하며, 적을 자기 쪽으로 끌어당길 수 있므로 조심히 상대하세요.",
  ["str_guide_circle_jianta-20-BOSS_RbT"] = "공격 범위",
  ["str_guide_circle_11-7BOSS_Lb"] = "낮에 피해를 입으면 적혈 수치가 누적되며, 밤에는 적혈 수치가 HP로 전환됩니다. 또한 더욱 강력한 암귀가 되어 전체화면 범위의 적에게 피해를 입힐 수 있습니다.",
  ["str_guide_circle_11-7BOSS_LbT"] = "글룸",
  ["str_guide_circle_11-7BOSS_Rb"] = "대응 전략",
  ["str_guide_circle_11-7BOSS_RbT"] = "밤에 전력을 다해 공격하고, 일정한 제어 능력을 가지고 있으면 효과적으로 대응할 수 있습니다.",
  ["str_guide_circle_air1-1_Lt"] = "컬렉터는 매우 중요한 시설이므로 철저히 보호해야 합니다.",
  ["str_guide_circle_air1-1_LtT"] = "컬렉터",
  ["str_guide_circle_air1-1_Lb"] = "컬렉터는 3개의 스킬을 가지고 있으며, 적의 공격을 막아낼 수 있습니다.",
  ["str_guide_circle_air1-1_LbT"] = "추가 스킬",
  ["str_guide_circle_air1-1_Rb"] = "컬렉터를 지키고, 암귀를 전부 처치해 코어의 안전을 지켜내세요.",
  ["str_guide_circle_air1-1_RbT"] = "컬렉터 수호",
  ["str_guide_circle_air1-2_Lb"] = "컬렉터의 에너지는 스킬을 시전하는 데 사용됩니다. 과부하되지 않게 조심해야 합니다.",
  ["str_guide_circle_air1-2_LbT"] = "컬렉터의 에너지",
  ["str_guide_circle_ex2-1_Lt"] = "아주 가벼운 폭탄으로, 넉백류 스킬에 넉백될 수 있습니다.",
  ["str_guide_circle_ex2-1_LtT"] = "유압 폭탄",
  ["str_guide_circle_ex2-1_Lb"] = "유압 폭탄은 넉백 후 첫 번째 대상에 닿을 시 폭발하여 큰 피해를 입힙니다.",
  ["str_guide_circle_ex2-1_LbT"] = "폭발 피해",
  ["str_guide_circle_N1_1-1_Lb"] = "싸울 수는 없지만, 다른 암귀의 몸에 붙어 암귀를 보호하고 속성을 증가시킵니다.",
  ["str_guide_circle_N1_1-1_LbT"] = "허거",
  ["str_guide_circle_N1_1-1_Rb"] = "암귀에게 붙기 전에 먼저 처치해야 합니다.",
  ["str_guide_circle_N1_1-1_RbT"] = "대응 전략",
  ["str_guide_circle_N1_1-8_Lb"] = "넓은 범위 피해를 가할 수 있습니다.",
  ["str_guide_circle_N1_1-8_LbT"] = "도엔",
  ["str_guide_circle_N1_1-8_Rb"] = "새벽의 정령을 소환하며, 새벽의 정령이 도엔에게 가까이 가면 도엔의 HP를 회복시킵니다.",
  ["str_guide_circle_N1_1-8_RbT"] = "중요 알림",
  ["str_guide_circle_N1_2-1_Lb"] = "넓은 범위 피해를 가할 수 있습니다.",
  ["str_guide_circle_N1_2-1_LbT"] = "이브",
  ["str_guide_circle_N1_2-1_Rb"] = "이브가 자신에게 실드를 추가해 피해를 막습니다.",
  ["str_guide_circle_N1_2-1_RbT"] = "중요 알림",
  ["str_guide_circle_N1_2-2_Lb"] = "이브는 병으로 인해 일시적으로 행동 능력을 잃은 상태입니다.",
  ["str_guide_circle_N1_2-2_LbT"] = "이브",
  ["str_guide_circle_N1_2-2_Rb"] = "이브를 보호하면서 암귀의 습격을 막아냅니다.",
  ["str_guide_circle_N1_2-2_RbT"] = "대응 전략",
  ["str_guide_circle_N1_2-3_Lb"] = "이브는 암귀에게 공격당하지 않으며, 주변 아군의 HP를 회복시킵니다.",
  ["str_guide_circle_N1_2-3_LbT"] = "이브",
  ["str_guide_circle_N1_2-3_Rb"] = "이브의 도움을 받아 암귀의 습격을 막아내면 승리할 수 있습니다.",
  ["str_guide_circle_N1_2-3_RbT"] = "대응 전략",
  ["str_guide_circle_N3_1-1_LbT"] = "시해의 기사",
  ["str_guide_circle_N3_1-1_Lb"] = "체스 기물 「나이트」의 행마법에 따라 공격을 진행합니다.",
  ["str_guide_circle_N3_1-1_RbT"] = "중요 알림",
  ["str_guide_circle_N3_1-1_Rb"] = "시해의 기사가 떨어지는 위치에 머물지 마세요. 스턴 효과를 받을 수 있습니다.",
  ["str_guide_circle_N3_1-3_LbT"] = "고통의 성채",
  ["str_guide_circle_N3_1-3_Lb"] = "체스 기물 「룩」의 행마법에 따라 가로 또는 세로로 공격을 진행합니다.",
  ["str_guide_circle_N3_1-3_RbT"] = "상대 전략",
  ["str_guide_circle_N3_1-3_Rb"] = "장애물을 활용해 고통의 성채를 우회 공격해야 합니다.",
  ["str_guide_circle_N3_1-5_LbT"] = "악몽의 주교",
  ["str_guide_circle_N3_1-5_Lb"] = "체스 기물 「비숍」의 행마법에 따라 대각선으로 이동한 후, 가로 또는 세로로 공격을 진행합니다.",
