  ["str_guide_circle_N3_1-7_LtT"] = "기만의 왕비",
  ["str_guide_circle_N3_1-7_Lt"] = "체스 기물 「퀸」의 행마법 범위 내 대상에게 대량의 피해를 입힙니다. 대상이 범위 내에 없을 경우 조용히 기회를 기다립니다.",
  ["str_guide_circle_N3_1-7_RtT"] = "중요 알림",
  ["str_guide_circle_N3_1-7_Rt"] = "기만의 왕비의 경고 범위 내에 머물지 마세요. 대량의 피해를 입을 수 있습니다.",
  ["str_guide_circle_N3_1-9_LtT"] = "미혹의 병사",
  ["str_guide_circle_N3_1-9_Lt"] = "턴마다 앞으로 도약하며, 지도의 좌측 하단 가장자리에 도달하면 순서대로 룩-나이트-비숍-퀸의 순서로 승급합니다.",
  ["str_guide_circle_N3_1-9_RtT"] = "상대 전략",
  ["str_guide_circle_N3_1-9_Rt"] = "공격을 피하고, 미혹의 병사가 승급하기 전에 처치해야 합니다.",
  ["str_guide_circle_N3_1-20_LbT"] = "적막의 군주",
  ["str_guide_circle_N3_1-20_Lb"] = "체스말 괴물들을 조종하는 뛰어난 전략가로, 적들을 손바닥 안에서 가지고 노는 것을 즐깁니다.",
  ["str_guide_circle_N3_1-20_RbT"] = "상대 전략",
  ["str_guide_circle_N3_1-20_Rb"] = "턴마다 보드를 아래로 한 칸씩 이동시켜 미혹의 병사의 변신을 유도합니다. 최대한 빠르게 미혹의 병사를 처치하고, 매 턴 위치에 주의해야 합니다.",
