  ["str_guide_circle_N5_1-3_Lt"] = "일정 턴 이후 체내의 에너지를 발산, 자신을 폭발시켜 지형을 파괴합니다.",
  ["str_guide_circle_N5_1-3_RtT"] = "칸 파괴",
  ["str_guide_circle_N5_1-3_Rt"] = "블라스터가 파괴한 칸은 오로리안이 사용할 수 없습니다.",
  ["str_guide_circle_N5_1-3_RbT"] = "대응 전략",
  ["str_guide_circle_N5_1-3_Rb"] = "블라스터가 폭발하기 전에 처치하세요!",
  ["str_guide_circle_N5_1-10_LbT"] = "하이롱거",
  ["str_guide_circle_N5_1-10_Lb"] = "거대한 몸집을 지닌 교활한 암귀입니다. 범위 내 대상에게 대량의 피해를 입히며, 대상의 위치를 기록하는 능력이 있습니다.",
  ["str_guide_circle_N5_1-10_RbT"] = "대응 전략",
  ["str_guide_circle_N5_1-10_Rb"] = "둔한 편이니 동선에 주의하면 큰 피해를 막을 수 있습니다.",
  ["str_guide_circle_N6_1-10_LtT"] = "밀렌 고티에",
  ["str_guide_circle_N6_1-10_Lt"] = "타락한 귀족입니다. 백야성에 대한 끝없는 증오가 그를 더욱 강하게 만들고 있습니다...",
