  ["str_guide_circle_N6_1-1_LtT"] = "어비스 스토커",
  ["str_guide_circle_N6_1-1_Lt"] = "원래 비경 깊은 곳에 살던 암귀였으며, 땅속에서의 습격에 능숙합니다. 다른 암귀를 위해 땅굴을 파기도 한다고 전해집니다.",
