  ["str_guide_circle_N6_1-1_Rt"] = "부서진 칸 위를 거닐며, 부서진 칸 주변의 대상에게 대량의 피해를 입힌다.",
  ["str_guide_circle_N6_1-1_RbT"] = "대응 전략",
  ["str_guide_circle_N6_1-1_Rb"] = "부서진 칸의 수를 제어하고, 공격 동선에 주의하세요!",
  ["str_guide_circle_N7_1-10_LtT"] = "마우트 소로스",
  ["str_guide_circle_N7_1-10_Lt"] = "야심을 실현하기 위해 위험한 개조를 선택했고, 새로운 힘을 얻었습니다.",
  ["str_guide_circle_N7_1-10_RtT"] = "소로스의 인형",
