  ["str_guide_circle_N7_1-10_LbT"] = "대응 전략",
  ["str_guide_circle_N7_1-10_Lb"] = "마우트가 소환한 암귀들을 피해 마우트를 직접 공격하세요!",
  ["str_guide_circle_N7_1-4_LbT"] = "경고!",
  ["str_guide_circle_N7_1-4_Lb"] = "「인핸서」를 복용해 돌변한 암귀입니다. 전과는 뭔가 다르니 조심하세요!",
