  ["str_guide_circle_N9_1-10_Lb"] = "먼지가 가라앉자, 익숙하면서도 낯선 적의 정체도 드러났습니다. 이제 당신의 의지를 증명할 때가 되었습니다.",
  ["str_guide_circle_N9_1-10_RbT"] = "특성",
