  ["str_guide_circle_N9_1-10_LtT"] = "대응 전략",
  ["str_guide_circle_N9_1-10_Lt"] = "오로라 타임에 진입해 시종을 물리치고 공격하세요!",
  ["str_guide_circle_N11_1-3_LtT"] = "재머-Ⅰ타입",
  ["str_guide_circle_N11_1-3_Lt"] = "「잃어버린 도시」에서 온 신비한 장치입니다. 재머 중에서도 비교적 초기 모델로 보입니다.",
  ["str_guide_circle_N11_1-3_RtT"] = "장치 특성",
  ["str_guide_circle_N11_1-3_Rt"] = "주변 지역을 교란할 수 있으며, 오로리안이 재머 주변을 이동하면 피해를 입습니다.",
  ["str_guide_circle_N11_1-3_LbT"] = "대응 전략",
  ["str_guide_circle_N11_1-3_Lb"] = "이동 시 가까이 가지 않는 것이 좋습니다!",
