  ["str_guide_circle_N11_1-12_Lb"] = "「잃어버린 도시」의 주민으로, 일루미나의 탐험가 시모스의 딸입니다.",
  ["str_guide_circle_N11_1-12_RbT"] = "조심하세요!",
  ["str_guide_circle_N11_1-12_Rb"] = "발렌시아는 강력한 장치를 소환해 전투를 진행합니다. 필드의 장치를 주의해서 관찰하세요!",
  ["str_guide_circle_N12_1-1_LbT"] = "키티푸스",
  ["str_guide_circle_N12_1-1_Lb"] = "그레텔의 「동료」입니다. 고양이 같기도 하면서 다리가 많은 괴물처럼 생겼습니다. 귀여운 것 같으면서도 이상하게 보입니다.",
  ["str_guide_circle_N12_1-1_RbT"] = "대응 전략",
  ["str_guide_circle_N12_1-1_Rb"] = "텐타클로는 입은 피해를 본체에 전달합니다. 이 점을 활용해 몬스터를 제압하세요.",
  ["str_guide_circle_N12_1-2_LbT"] = "아이언스톰프",
  ["str_guide_circle_N12_1-2_Lb"] = "그레텔의 「동료」입니다. 매우 강력한 두 다리가 있어 모든 적을 밀어낼 수 있습니다.",
  ["str_guide_circle_N12_1-2_RbT"] = "대응 전략",
  ["str_guide_circle_N12_1-2_Rb"] = "아이언스톰프는 칸을 부수는 능력이 있으므로, 체인저 오로리안을 활용하는 것이 좋습니다.",
  ["str_guide_circle_N12_1-3_LbT"] = "바실리스크",
  ["str_guide_circle_N12_1-3_Lb"] = "그레텔의 「동료」입니다. 활동적인 장난꾸러기입니다. 가장 좋아하는 것은 혼자서 적들과 싸우는 것입니다.",
  ["str_guide_circle_N12_1-3_RbT"] = "대응 전략",
  ["str_guide_circle_N12_1-3_Rb"] = "바실리스크의 피부는 단단하지만 마음은 연약합니다. 제어 스킬을 활용하면 좋은 효과가 있을 것입니다.",
  ["str_guide_circle_N12_1-4_LbT"] = "스파이키호그",
  ["str_guide_circle_N12_1-4_Lb"] = "그레텔의 「동료」입니다. 평소에는 조용하지만 전투 시에는 매우 난폭하므로 주의해야 합니다.",
  ["str_guide_circle_N12_1-4_RbT"] = "대응 전략",
  ["str_guide_circle_N12_1-4_Rb"] = "스파이키호그는 온몸이 가시로 뒤덮여 있으므로, 적당한 거리를 유지하며 전투를 진행하는 것이 좋습니다.",
  ["str_guide_circle_N13_1-1_LbT"] = "명토의 유검",
  ["str_guide_circle_N13_1-1_Lb"] = "촉유군의 전임 대장으로, 운도에 침입한 일부 외지인들에게 맞서고 있습니다.",
  ["str_guide_circle_N13_1-1_RbT"] = "대응 전략",
  ["str_guide_circle_N13_1-1_Rb"] = "명토의 유검은 적과 아군의 거리에 따라 능숙하게 다른 전술을 사용합니다. 거리에 신경 쓰면서 일정한 회복 능력을 준비하면 더 쉽게 상대할 수 있습니다.",
  ["str_guide_circle_N14_1-1_LbT"] = "나기·광도",
  ["str_guide_circle_N14_1-1_Lb"] = "자신의 집념에 사로잡혀 광기에 빠진 나기는 자신이 침입자라고 여기는 모든 사람을 공격할 것입니다.",
  ["str_guide_circle_N14_1-1_RbT"] = "대응 전략",
  ["str_guide_circle_N14_1-1_Rb"] = "「나기·광도」의 공격 순서에 주의해 치명적인 피해를 피하고 제때 반격하세요.",
  ["str_guide_circle_N13_1-12_LbT"] = "후지쿠모 노부토라",
  ["str_guide_circle_N13_1-12_Lb"] = "극동의 다른 섬에서 온 운도의 「통치자」로, 이 땅을 완전히 지배하기 위해 어떤 수단도 가리지 않습니다.",
  ["str_guide_circle_N13_1-12_RbT"] = "조심하세요!",
  ["str_guide_circle_N13_1-12_Rb"] = "후지쿠모 노부토라는 수많은 「오니」를 소환할 수 있습니다.",
  ["str_guide_circle_N13_1-12_LtT"] = "대응 전략",
  ["str_guide_circle_N13_1-12_Lt"] = "필드의 「오니」를 제때 처치하세요.",
  ["str_guide_circle_N14_1-12_LbT"] = "노부토라의 악령",
  ["str_guide_circle_N14_1-12_Lb"] = "자신의 집념으로 인해 흉측한 모습이 된 존재로, 저항하는 모든 자를 죽이기로 맹세했습니다.",
  ["str_guide_circle_N14_1-12_RbT"] = "주의",
  ["str_guide_circle_N14_1-12_Rb"] = "노부토라의 악령은 오로리안의 위치에 따라 다른 스킬을 시전합니다.",
  ["str_guide_circle_N14_1-12_LtT"] = "대응 전략",
  ["str_guide_circle_N14_1-12_Lt"] = "전투 시 신중하게 이동하고 적절하게 반격하세요.",
  ["str_guide_circle_N13_1-2_LbT"] = "오니",
  ["str_guide_circle_N13_1-2_Lb"] = "극동의 특수한 괴물로, 「생과 사의 경계에 있는 존재」라고 불리며, 살아있는 자에 대해 강렬한 적의를 드러냅니다.",
  ["str_guide_circle_N13_1-2_RbT"] = "특성",
  ["str_guide_circle_N13_1-2_Rb"] = "전투력은 그다지 강하지 않을지도 모르지만, 그 수는 놀랄 만큼 많습니다.",
  str_guide_fail_1 = "오로리안 육성",
  str_guide_fail_2 = "오로리안 레벨업 및 각성은 오로리안의 능력을 대폭 올려줍니다.",
  str_guide_fail_3 = "레벨업 가능 오로리안:",
  str_guide_fail_4 = "육성 소재 획득",
  str_guide_fail_5 = "다음 방식으로 오로리안의 경험치 재료와 돌파 재료를 획득할 수 있습니다.",
  str_guide_fail_6 = "자원 획득: 망각의 눈 자원 스테이지, 메인 스테이지",
  str_guide_fail_7 = "화면을 터치해 계속 진행",
  str_guide_warn_level_speed = "WARNING! 레벨이 부족합니다!",
  str_guide_fail_8 = "스테이지 실패",
  str_guide_warn_40096 = "이곳을 터치하십시오.",
  str_guide_fail_9 = "체스말의 스킬 이해",
  str_guide_fail_10 = "각 체스말의 특성을 이해하면 저들이 더 강한 전투력을 발휘하게 할 수 있습니다.",
  str_guide_fail_11 = "전투 전략 조정",
  str_guide_fail_12 = "모든 적은 일정한 행동 규칙이 있으므로, 적의 특징에 맞춰 전투 전략을 조정해야 합니다.",
  ["str_guide_circle_N17_1-14_LtT"] = "클라우디아",
  ["str_guide_circle_N17_1-14_Lt"] = "헤븐즈 밸리 지하 기지에 있는 인공지능입니다. 수백 년간 줄곧 기지를 지키며 침입한 적을 모두 제거했습니다.",
  ["str_guide_circle_N17_1-14_RbT"] = "특성",
  ["str_guide_circle_N17_1-14_Rb"] = "제단석 또는 아시르 위에 서 있을 시 모든 일반공격을 막아냅니다. 발 아래 제단석이 파괴되는 순간 2서클 범위 내의 다른 제단석 위로 이동합니다.",
  ["str_guide_circle_N17_1-14_LbT"] = "대응 전략",
  ["str_guide_circle_N17_1-14_Lb"] = "스나이퍼의 공격으로 클라우디아를 명중시킬 수 있지만, 필드의 제단석 파괴에도 신경 써야 합니다.",
  ["str_guide_circle_N17_2-14_LtT"] = "아시르",
  ["str_guide_circle_N17_2-14_Lt"] = "헤븐즈 밸리 지하 기지에 있는 인공지능입니다. 클라우디아의 동료이며, 크고 육중한 외형을 가지고 있습니다.",
  ["str_guide_circle_N17_2-14_RbT"] = "특성",
  ["str_guide_circle_N17_2-14_Rb"] = "불사의 특성을 지니고 있으며, 쓰러진 후 빠르게 다시 일어섭니다. 하지만 다시 일어설 때마다 회복하는 HP가 점차 감소합니다.",
  ["str_guide_circle_N17_2-14_LbT"] = "대응 전략",
  ["str_guide_circle_N17_2-14_Lb"] = "방패 역할을 하는 아시르를 피해 최대한 빠르게 클라우디아를 쓰러트려야 합니다.",
  ["str_guide_circle_N18_1-12_LtT"] = "미노스",
  ["str_guide_circle_N18_1-12_Lt"] = "안데르센 가문의 에이스 집사입니다. 그 어떤 얼룩, 쓰레기, 해충조차 남기지 않습니다.",
  ["str_guide_circle_N18_1-12_RtT"] = "특성",
  ["str_guide_circle_N18_1-12_Rt"] = "미노스는 자신의 인장 개수에 따라 「객중」 상태 및 「뿔그림자」 상태로 전환하며, 각 상태에서 자신이 지나는 모든 칸을 강화 칸 또는 약화 칸으로 전환합니다.",
  ["str_guide_circle_N18_1-12_RbT"] = "주의",
  ["str_guide_circle_N18_1-12_Rb"] = "미노스의 공격은 대부분 자신의 인장 개수에 따라 강화됩니다. 미노스의 인장 개수가 많을수록, 그리고 필드의 강화 칸 수가 많을수록 미노스의 공격이 더 위험해집니다.",
  ["str_guide_circle_N18_1-1_LtT"] = "약화 칸",
  ["str_guide_circle_N18_1-1_Lt"] = "강화 칸과 상대되는 특수 칸으로, 플레이어의 연결 피해를 감소시킵니다.",
  ["str_guide_circle_N18_1-1_RbT"] = "특성",
  ["str_guide_circle_N18_1-1_Rb"] = "오로리안이 지나갈 때 일반 칸 1개에 해당하는 연결 피해 배율이 감소합니다.",
  ["str_guide_circle_N20_1-12_LtT"] = "코어 가디언",
  ["str_guide_circle_N20_1-12_Lt"] = "거대한 체격의 가디언입니다. 함선 전체의 에너지 코어를 지키며, 코어가 위협을 받으면 소생해 전투를 수행합니다.",
  ["str_guide_circle_N20_1-12_LbT"] = "필드 특성",
  ["str_guide_circle_N20_1-12_Lb"] = "코어 가디언이 깨어나면 턴이 종료될 때마다 유저와 먼 큐브의 한 면을 움직여 필드의 적 분포를 바꿉니다.",
  ["str_guide_circle_N20_1-12_RbT"] = "적 약점",
  ["str_guide_circle_N20_1-12_Rb"] = "프리징 모듈은 가디언의 약점입니다. 프리징 모듈을 파괴하면 코어 가디언을 1턴간 마비시키고, 더 쉽게 피해를 입도록 합니다.",
  str_guide_warn_5193011 = "P5R 콜라보 오로리안은 전투에 진입할 때 특수기를 가지게 돼.",
  str_guide_warn_5193012 = "여기서 특수기 설명을 확인할 수 있어.",
  str_guide_warn_5193013 = "특수기를 시전해서 단숨에 적들을 쓰러트려 보자!",
  ["str_guide_circle_N22_1-10_LtT"] = "카스타",
  ["str_guide_circle_N22_1-10_Lt"] = "겉보기엔 냉정하지만, 사실은 무척 믿음직합니다. 교회의 아이들을 지키기 위해 폴룩스와 함께 「레이븐즈 블러드」라는 코드네임의 자유 용병 일을 하고 있습니다.",
  ["str_guide_circle_N22_1-10_RbT"] = "특성",
  ["str_guide_circle_N22_1-10_Rb"] = "아군의 위치에 따라 다른 스킬을 시전해 공격하며, 아군의 액티브 스킬에 반격합니다.",
  ["str_guide_circle_N22_1-10_LbT"] = "대응 전략",
  ["str_guide_circle_N22_1-10_Lb"] = "적과 아군의 위치에 항상 주의하고, 아군의 액티브 스킬의 시전 빈도를 적절하게 제어하세요.",
  ["str_guide_circle_sailing_1-1_LtT"] = "다크웜 게이트",
  ["str_guide_circle_sailing_1-1_Lt"] = "원리는 알 수 없지만, 이 게이트를 통해 암귀들이 끊임없이 나타납니다. 서둘러 제압하지 않으면 전황이 매우 불리해질 것입니다.",
  ["str_guide_circle_sailing_1-1_RbT"] = "특성",
  ["str_guide_circle_sailing_1-1_Rb"] = "다크웜 게이트를 열면 다음 턴이 시작될 때부터 암귀를 소환합니다.",
  ["str_guide_circle_sailing_1-1_RtT"] = "주의",
  ["str_guide_circle_sailing_1-1_Rt"] = "만약 턴이 시작됐을 때 암귀가 다크웜 게이트 위에 위치해 있다면, 해당 턴에는 새로운 암귀가 소환되지 않습니다.",
  ["str_guide_circle_sailing_2-1_LtT"] = "헤일로 스톤",
  ["str_guide_circle_sailing_2-1_Lt"] = "신비한 루미나가 담긴 돌로, 고대 유적에서 흔히 발견되며, 주변의 루미나를 변화시킬 수 있다고 한다.",
  ["str_guide_circle_sailing_2-1_RbT"] = "특성",
  ["str_guide_circle_sailing_2-1_Rb"] = "플레이어의 턴이 시작될 때 헤일로 스톤이 주변 일정 범위 내 여러 다른 속성의 칸을 자신과 동일한 속성의 칸으로 전환합니다.",
  ["str_guide_circle_sailing_2-1_RtT"] = "전략",
  ["str_guide_circle_sailing_2-1_Rt"] = "헤일로 스톤의 속성은 항상 위치한 칸의 속성과 일치하므로, 이를 이용하면 전투에서 유리하게 활용할 수 있습니다.",
  ["str_guide_circle_sailing_2-2_RbT"] = "주의",
  ["str_guide_circle_sailing_2-2_Rb"] = "헤일로 스톤이 위치한 칸이 만색 칸이 될 경우, 헤일로 스톤이 파괴됩니다.",
  ["str_guide_circle_sailing_2-3_LtT"] = "금제의 비석",
  ["str_guide_circle_sailing_2-3_Lt"] = "어떤 유적에서 발견된 신비한 작은 비석입니다. 표면에 새겨진 룬은 공격자에게 일정한 제한 작용을 발휘합니다.",
  ["str_guide_circle_sailing_2-3_RbT"] = "특성",
  ["str_guide_circle_sailing_2-3_Rb"] = "일정 범위 내의 오로리안을 침묵시켜 액티브 스킬을 시전할 수 없게 만듭니다.",
  ["str_guide_circle_sailing_2-4_LtT"] = "전략",
  ["str_guide_circle_sailing_2-4_Lt"] = "범위 피해가 있는 연쇄 스킬 또는 액티브 스킬을 사용하면 금제의 비석에 피해를 입힐 수 있으며, 일정 횟수의 피해를 입은 후 금제의 비석은 파괴됩니다.",
  ["str_guide_circle_N22_2-1_LtT"] = "특성",
  ["str_guide_circle_N22_2-1_Lt"] = "포탑을 사용해 적에게 지속적인 피해를 입힐 수 있고, 자신과 가까이 있는 적을 몰아낼 수 있습니다. 큰 위협을 느끼면 스스로를 강화합니다.",
  ["str_guide_circle_N22_2-1_RtT"] = "대응 전략",
  ["str_guide_circle_N22_2-1_Rt"] = "자주식 전투포는 동일 턴 내에 적에게 여러 차례 피해를 입힐 수 있습니다. 하지만 단일 피해는 강하지 않으므로, 모두 피할 필요는 없습니다.",
  ["str_guide_circle_N22_2-1_RbT"] = "자주식 전투포",
  ["str_guide_circle_N22_2-1_Rb"] = "자율 순찰이 가능한 강력한 방어 수단으로, 주포와 보조포 모두 막강한 위력을 자랑합니다. 한 대만 있어도 엄청난 피해를 입힐 수 있습니다.",
  ["str_guide_circle_N23_1-14_LtT"] = "에스더",
  ["str_guide_circle_N23_1-14_Lt"] = "주인이 없이 방황하는 여성의 영혼으로, 사악한 의식에 의해 다크매터와 결합하여 실체를 얻게 되었습니다. 사고 능력이 없고, 살아 있는 것에 대한 본능적인 증오만이 남아 있습니다.",
  ["str_guide_circle_N23_1-14_RtT"] = "특성",
  ["str_guide_circle_N23_1-14_Rt"] = "제한된 지역에서 날뛰면서 혼의 양초의 에너지를 흡수해 자신을 강화합니다.",
  ["str_guide_circle_N23_1-14_RbT"] = "대응 전략",
  ["str_guide_circle_N23_1-14_Rb"] = "혼의 양초를 끄면서 에스더와의 거리를 조절하세요.",
  ["str_guide_circle_13-14_LtT"] = "디아볼라",
  ["str_guide_circle_13-14_Lt"] = "꽃의 바깥쪽은 단단한 잎으로 싸여 있고 저항력이 강합니다. 스나이퍼 스킬은 꽃에 치명적인 피해를 입히고, 약점을 드러낼 수 있습니다.",
  ["str_guide_circle_13-14_RtT"] = "특성",
  ["str_guide_circle_13-14_Rt"] = "각성 상태에서 디아볼라는 오로리안의 일반공격에 반격하며, 맹독 상태를 1단계 추가합니다.",
  ["str_guide_circle_13-14_RbT"] = "대응 전략",
  ["str_guide_circle_13-14_Rb"] = "디아볼라의 꽃잎을 우선적으로 처리하고, 마비 상태에서 안정적인 공격을 가할 수 있습니다. 또한 디아볼라가 소환하는 새벽의 정령에 주의하세요.",
  ["str_guide_circle_13-7-1_Lt"] = "종말이라는 극한의 조건에서 탄생한 암귀입니다. 계속해서 형태가 왜곡되며, 이성도 완전히 상실해 그저 끝없이 전진하고 삼키려는 욕망만 남게 되었습니다.",
  ["str_guide_circle_13-7-1_LtT"] = "요르문간드",
  ["str_guide_circle_13-7-1_Rt"] = "요르문간드의 머리는 공격 발동의 핵심으로, 머리와 가까운 적에게 큰 피해를 입힙니다. 머리의 HP가 바닥나면 사망 판정됩니다.",
  ["str_guide_circle_13-7-1_RtT"] = "요르문간드의 머리 특성",
  ["str_guide_circle_13-7-1_Rb"] = "플레이어는 요르문간드의 머리와 거리를 유지하며 공격해야 합니다. 만약 요르문간드의 머리가 장애물에 의해 막힐 경우, 요르문간드가 즉시 사망합니다.",
  ["str_guide_circle_13-7-1_RbT"] = "대응 전략",
  ["str_guide_circle_13-7-2_Lt"] = "요르문간드의 몸은 시간이 지나면서 자가복제를 진행해 턴마다 길어집니다. 요르문간드의 몸은 모든 피해에 면역됩니다.",
  ["str_guide_circle_13-7-2_LtT"] = "요르문간드의 몸 특성",
  ["str_guide_circle_13-7-3_Lt"] = "요르문간드의 꼬리는 녀석의 약점입니다. 꼬리가 받는 피해는 머리에 모두 전이되며, 받는 피해도 더 높습니다.",
  ["str_guide_circle_13-7-3_LtT"] = "요르문간드의 꼬리 특성",
  ["str_guide_circle_14-9-1_LtT"] = "랜턴 스피릿",
  ["str_guide_circle_14-9-1_Lt"] = "아스모데우스에 의해 개조된 암귀입니다. 자신의 욕망을 제어당해 아스모데우스의 말에 복종합니다.",
  ["str_guide_circle_14-9-1_RtT"] = "몬스터 특성Ⅰ",
  ["str_guide_circle_14-9-1_Rt"] = "랜턴 스피릿이 공격할 때 오로리안을 통과할 수 있는 경우, 공격 후 사슬을 창조하며, 사슬로 연결된 양측은 받는 피해나 회복되는 HP를 서로에게 전이합니다.",
  ["str_guide_circle_14-9-1_RbT"] = "통과",
  ["str_guide_circle_14-9-1_Rb"] = "랜턴 스피릿이 해당 오로리안이 위치한 칸을 지나 맞은편 칸으로 이동할 경우 통과를 발동합니다.",
  ["str_guide_circle_14-9-2_LtT"] = "사슬",
  ["str_guide_circle_14-9-2_Lt"] = "사슬로 연결된 양쪽 중 한쪽이 피해를 입거나 HP를 회복하면 다른 한쪽도 일정 비율만큼 피해를 입거나 HP를 회복합니다.",
  ["str_guide_circle_14-9-2_RtT"] = "대응 전략",
  ["str_guide_circle_14-9-2_Rt"] = "랜턴 스피릿으로부터 일정 거리를 벗어나면 사슬이 끊어집니다.",
  ["str_guide_circle_14-9-2_RbT"] = "넉백 또는 끌어당김",
  ["str_guide_circle_14-9-2_Rb"] = "랜턴 스피릿을 넉백시키거나 끌어당겨도 랜턴 스피릿과의 사슬을 끊을 수 있습니다.",
  ["str_guide_circle_14-14-1_LtT"] = "아스모데우스",
  ["str_guide_circle_14-14-1_Lt"] = "강력한 힘을 지닌 팬텀입니다. 상대의 모든 욕망을 꿰뚫어 보는 무서운 능력이 있으며, 적을 조종하는 것을 즐깁니다.",
  ["str_guide_circle_14-14-1_RtT"] = "암귀 특성",
  ["str_guide_circle_14-14-1_Rt"] = "출전 시 두 개의 분신으로 나뉘며, 각각 스킬 피해와 일반공격 피해에 면역됩니다. 욕망의 사슬로 서로를 연결합니다.",
  ["str_guide_circle_14-14-1_RbT"] = "욕망의 사슬",
  ["str_guide_circle_14-14-1_Rb"] = "두 아스모데우스는 사슬로 연결되며, 양쪽 중 한쪽이 피해를 입거나 HP를 회복하면 다른 한쪽도 동일하게 피해를 입거나 HP를 회복합니다. 아스모데우스의 행동이 종료되면 욕망의 사슬 하단에 어둠의 영역이 생성됩니다.",
  ["str_guide_circle_14-14-2_LtT"] = "아스모데우스",
  ["str_guide_circle_14-14-2_Lt"] = "아스모데우스의 분신 중 하나로, 일반공격 피해에 면역됩니다. 강력한 원거리 공격 능력을 가지고 있습니다.",
  ["str_guide_circle_14-14-3_RtT"] = "아스모데우스",
  ["str_guide_circle_14-14-3_Rt"] = "아스모데우스의 분신 중 하나로, 스킬 피해에 면역됩니다. 공격이 오로리안에게 명중되면 자신과 오로리안 사이에 악몽의 사슬을 생성합니다.",
  ["str_guide_circle_14-14-3_RbT"] = "악몽의 사슬",
  ["str_guide_circle_14-14-3_Rb"] = "악몽의 사슬에 연결된 오로리안은 1칸을 이동할 때마다 피해를 1회 입으며, 악몽의 사슬 유효 범위를 벗어나면 악몽의 사슬이 끊어집니다.",
  ["str_guide_circle_14-7_LtT"] = "래비드후프",
  ["str_guide_circle_14-7_Lt"] = "탐색 중에 조우한 새로운 암귀로, 어떤 강력한 암귀의 변종으로 보입니다. 다만 더 광폭하고, 행동 역시 더 파괴적으로 변했습니다.",
  ["str_guide_circle_14-7_RtT"] = "특성",
  ["str_guide_circle_14-7_Rt"] = "오로리안에게 돌진해 공격하며, 암석을 소환하고 지형을 바꾸는 강력한 능력이 있습니다. 치명적이지 못한 공격은 녀석을 더 강하게 만들 뿐입니다! 일정 턴마다 포효와 함께 광폭 상태가 됩니다.",
  ["str_guide_circle_14-7_RbT"] = "대응 전략",
  ["str_guide_circle_14-7_Rb"] = "적과의 거리에 주의하고 스킬 시전 타이밍을 조절해 최대한 빠르게 전투를 끝내세요.",
  str_guide_circle_N24_petTry_LtT = "큐어 볼",
  str_guide_circle_N24_petTry_Lt = "악셀리아의 소환물입니다. 액티브 스킬을 사용해 흡수하거나 파티가 지나가면 치료 효과를 획득합니다. 필드에 2턴 이상 존재한 큐어 볼은 본 형태로 전환되며, 추가 치료 효과를 제공합니다.",
  str_guide_circle_N24_petTry_Lt_1 = "악셀리아의 소환물입니다. 액티브 스킬을 사용해 흡수하거나 파티가 지나가면 치료 효과를 획득합니다.",
  ["str_guide_circle_N25_1-4_LtT"] = "베놈",
  ["str_guide_circle_N25_1-4_Lt"] = "스스로 폭발할 수 있는 일부 암귀의 「먼 친척」이라고 합니다. 맹독 점액 구체를 발사해 생물에 큰 영향을 미치는 점에서 차이가 있습니다.",
  ["str_guide_circle_N25_1-4_LbT"] = "특성",
  ["str_guide_circle_N25_1-4_Lb"] = "직선 방향 또는 오로리안의 위치를 향해 독액을 분사하며, 독액 범위 내 적과 아군에게 중독 상태를 추가합니다.",
  ["str_guide_circle_N25_1-4_RtT"] = "전략",
  ["str_guide_circle_N25_1-4_Rt"] = "녀석의 독을 사용해서 다른 적에게 피해를 줄 수 있을지도 모릅니다.",
  ["str_guide_circle_N25_1-16_RtT"] = "글룸",
  ["str_guide_circle_N25_1-16_Rt"] = "영원한 밤의 땅에 서식하는 고스트의 「형제」라고 합니다. 낮과 밤에 따라 전술이 달라져서 상대하기 까다롭습니다.",
  ["str_guide_circle_N25_1-16_LtT"] = "특성",
  ["str_guide_circle_N25_1-16_Lt"] = "원거리 및 필드 전체공격 능력을 지니고 있으며, 공격 능력이 없는 고스트를 소환해 오로리안을 포위합니다.",
  ["str_guide_circle_N25_1-16_LbT"] = "전략",
  ["str_guide_circle_N25_1-16_Lb"] = "민첩하게 이동해 환영의 포위를 피해야 합니다.",
  ["str_guide_circle_N25_2-4_LtT"] = "그레이홀트",
  ["str_guide_circle_N25_2-4_Lt"] = "위장 능력이 강력하며, 때로는 평범한 함정처럼 보이지만, 터지기만 하면 무서운 살상 효과를 일으킵니다.",
  ["str_guide_circle_N25_2-4_LbT"] = "특성",
  ["str_guide_circle_N25_2-4_Lb"] = "평소에는 그림자늪에 숨어 있다가 대기 시간이 끝나면 나타나 오로리안을 공격합니다.",
  ["str_guide_circle_N25_2-4_RtT"] = "대응 전략",
  ["str_guide_circle_N25_2-4_Rt"] = "그림자늪이 위치한 칸을 초기화하면 그림자늪이 제거되고 그레이홀트가 등장합니다.",
  ["str_guide_circle_N26_1-12_RtT"] = "우룡",
  ["str_guide_circle_N26_1-12_Rt"] = "한때 교룡어의 우두머리였으나, 오로리안에게 붙잡혀 항해의 도구로 부려졌습니다. 오랜 세월 쌓아온 증오는 녀석을 강력한 수요령으로 만들었습니다.",
  ["str_guide_circle_N26_1-12_LtT"] = "특성",
  ["str_guide_circle_N26_1-12_Lt"] = "강력한 환술 능력을 가지고 있으며, 탄환을 제어해 적에게 피해를 입힐 수 있습니다.",
  ["str_guide_circle_N26_1-12_LbT"] = "대응 전략",
  ["str_guide_circle_N26_1-12_Lb"] = "최대한 빠르게 필드의 \"자\"와 분신을 제거하면 강력한 공격을 피할 수 있습니다.",
  ["str_guide_circle_N27_1-1_RtT"] = "아포닉",
  ["str_guide_circle_N27_1-1_Rt"] = "일부 암귀의 「선생님」인 듯하며, 다른 암귀를 회복시켜 줄 수 있습니다. 이 암귀는 더 커다란 개체 근처에서 저들이 싸울수록 더 강해지게 만드는 특성이 있습니다.",
  ["str_guide_circle_N27_1-1_LtT"] = "특성",
  ["str_guide_circle_N27_1-1_Lt"] = "다른 암귀의 HP를 회복시키며, 다른 암귀가 아포닉의 스킬 범위 내에서 차지하는 칸이 클수록 아포닉이 대상을 치료하는 효과가 강해집니다.",
  ["str_guide_circle_N27_1-1_LbT"] = "대응 전략",
  ["str_guide_circle_N27_1-1_Lb"] = "다른 암귀을 치료하지 못하도록 아포닉을 가장 먼저 처리해야 합니다!",
  ["str_guide_circle_N27_1-12_LtT"] = "분홍색 샌드버그",
  ["str_guide_circle_N27_1-12_Lt"] = "레디젤 사막에 서식하는 희귀한 샌드버그로, 특별한 돌연변이로 인해 비늘이 분홍색이며, 다른 모래벌레보다 더 강하고 흉포합니다.",
  ["str_guide_circle_N27_1-12_RtT"] = "특성",
  ["str_guide_circle_N27_1-12_Rt"] = "지면을 뚫고 목표물의 위치를 찾아 땅을 부수며, 검은 모래를 뿜어내 전방 범위 내의 목표물을 공격합니다.",
  ["str_guide_circle_N27_1-12_RbT"] = "대응 전략",
  ["str_guide_circle_N27_1-12_Rb"] = "분홍색 샌드버그의 공격은 피하기 어렵습니다. 항상 자신의 상태에 주의하고 빠르게 전투를 끝내야 합니다.",
  ["str_guide_circle_N27_2-4-1_RbT"] = "종이학",
  ["str_guide_circle_N27_2-4-1_Rb"] = "종이학은 심연 칸 위에 놓을 수 있으며, 해당 칸은 만색 칸이 됩니다. 파티가 종이학을 지날 경우 종이학은 사라집니다.",
  ["str_guide_circle_N27_2-4-2_RbT"] = "오로리안 지원",
  ["str_guide_circle_N27_2-4-2_Rb"] = "파솔로는 칸에 종이학을 배치해 팀을 도울 수 있습니다. 턴마다 파솔로의 스킬 지원을 사용하는 것을 잊지 마세요!",
  str_guide_circle_N27_2_1_RtT = "백야성의 지원군입니다!",
  str_guide_circle_N27_2_1_Rt = "백야성의 일부 지원 부대가 전장에 도착했습니다. 아군 장창병은 턴마다 암귀 다음에 행동합니다. 플레이어가 연속으로 액티브 스킬 3회 시전 시 포티파이어가 장창병 1명을 전장에 소환합니다.",
  str_guide_circle_N27_2_1_RbT = "주의하세요!",
  str_guide_circle_N27_2_1_Rb = "아군 포티파이어를 우선적으로 보호하세요! 포티파이어가 쓰러지면 아군 백야성 장창병이 퇴각하며, 필드에 있는 오로리안의 방어력이 대폭 하락합니다.",
  str_guide_circle_N27_2_2_RbT = "공격 표적",
  str_guide_circle_N27_2_2_Rb = "적 암귀 부대는 아군의 백야성 지원군을 우선적으로 공격합니다. 필드의 모든 백야성 지원군이 쓰러지면, 암귀는 목표를 전환해 플레이어를 공격합니다.",
  str_guide_circle_N27_2_2_LbT = "진영 대항",
  str_guide_circle_N27_2_2_Lb = "적 데몬아이는 지속적으로 암귀를 전장으로 소환합니다. 플레이어는 아군 포티파이어를 보호하고 적 하이브를 제거해 승리를 거머쥐어야 합니다.",
  str_guide_circle_N28_3_4_RtT = "텔레포트 웜홀",
  ["str_guide_circle_N28_3-4_Rt"] = "암귀는 웜홀을 통해 다른 곳으로 탈출합니다.",
  ["str_guide_circle_N28_3-4_RbT"] = "대응 전략",
  ["str_guide_circle_N28_3-4_Rb"] = "처치하거나 강제이동 스킬로 탈출을 방지할 수 있습니다.",
  str_guide_circle_N28_1_12_LtT = "4기사",
  str_guide_circle_N28_1_12_Lt = "평범한 배심원처럼 보이지만, 그 석고 가면은 무척 의심스럽습니다. 역시나 그 아래에 숨어 있던 진짜 실체는... 암귀였습니다! 더욱 의아한 것은 그들이 마치 누군가의 지시에 따라 행동하는 것 같다는 점입니다...",
  str_guide_circle_N28_1_12_LbT = "특성",
  str_guide_circle_N28_1_12_Lb = "네 기사 중 한 명이 공격을 받거나 HP를 회복할 때마다 나머지 기사들도 동일하게 피해를 입거나 HP를 회복합니다.",
  str_guide_circle_N28_1_12_RbT = "대응 전략",
  str_guide_circle_N28_1_12_Rb = "네 기사의 위치를 자세히 살펴보고 신중하게 상대하세요!",
  str_guide_circle_N29_zhanqi_1_LtT = "텔레포트 웜홀",
  str_guide_circle_N29_zhanqi_1_Lt = "암귀가 전장 사이를 더 빠르게 이동하도록 돕습니다.",
  str_guide_circle_N29_zhanqi_1_LbT = "대응 전략",
  str_guide_circle_N29_zhanqi_1_Lb = "오로리안과의 충돌을 피하려면 최대한 빨리 전송 장치를 통과하는 것이 좋습니다.",
  str_guide_circle_N29_1_8_LbT = "마견 하티",
  str_guide_circle_N29_1_8_Lb = "과거의 기억이 그녀의 마음에 넘쳐, 증오가 그녀의 마음을 사로잡았고, 그 속에서 공포의 「마견」이 탄생했습니다....",
  str_guide_circle_N29_1_8_RbT = "특성",
  str_guide_circle_N29_1_8_Rb = "마견 하티는 현재 HP의 일부를 소모해 공격하며, 오로리안에게 명중 시 자신이 잃은 HP의 일부를 회복합니다. 마견 하티의 HP가 낮을수록 마견 하티가 입히는 피해가 강력해집니다.",
  str_guide_circle_N29_1_14_LbT = "마견 하티",
  str_guide_circle_N29_1_14_Lb = "과거의 기억이 그녀의 마음에 넘쳐, 증오가 그녀의 마음을 사로잡았고, 그 속에서 공포의 「마견」이 탄생했습니다....",
  str_guide_circle_N29_1_14_RbT = "특성",
  str_guide_circle_N29_1_14_Rb = "마견 하티는 현재 HP의 일부를 소모해 공격하며, 오로리안에게 명중 시 자신이 잃은 HP의 일부를 회복합니다. 마견 하티의 HP가 낮을수록 마견 하티가 입히는 피해가 강력해집니다.",
  str_guide_circle_N29_1_14_LbT_2 = "조심하세요!",
  str_guide_circle_N29_1_14_Lb_2 = "마견 하티가 빈사 상태에 진입하면 재생 에너지를 소모해 HP를 완전히 회복하며, 이번 턴에 강력한 스킬을 시전하고 자신을 강화합니다!",
  str_guide_circle_N29_ex3_1_LbT = "마견 하티",
  str_guide_circle_N29_ex3_1_Lb = "과거의 기억이 그녀의 마음에 넘쳐, 증오가 그녀의 마음을 사로잡았고, 그 속에서 공포의 「마견」이 탄생했습니다....",
  str_guide_circle_N29_ex3_1_RbT = "특성",
  str_guide_circle_N29_ex3_1_Rb = "마견 하티는 현재 HP의 일부를 소모해 공격하며, 오로리안에게 명중 시 자신이 잃은 HP의 일부를 회복합니다. 마견 하티의 HP가 낮을수록 마견 하티가 입히는 피해가 강력해집니다.",
  str_guide_circle_N29_ex3_1_LbT_2 = "조심하세요!",
  str_guide_circle_N29_ex3_1_Lb_2 = "마견 하티가 빈사 상태에 진입하면 재생 에너지를 소모해 HP를 완전히 회복하며, 이번 턴에 강력한 스킬을 시전하고 자신을 강화합니다!",
  str_guide_circle_N29_ex3_1_RbT_2 = "주의",
  str_guide_circle_N29_ex3_1_Rb_2 = "만약 오로리안이 마견 하티 앞에서 액티브 스킬을 시전할 경우, 마견 하티도 반격합니다.",
  str_guide_warn_11900702 = "이건 지금 장비의 정련 레벨이야. 장비는 3번 정련할 수 있어.",
  str_guide_warn_11900703 = "여기서 장비를 정련했을 때 얻는 효과를 볼 수 있어. 기본 속성도 증가하고, 오로리안의 스킬도 강화될 거야~",
  str_guide_warn_11900704 = "정련을 하려면 오로리안이 기본 개방 조건을 충족하고, 정련에 필요한 재료를 소모해야 해.",
  str_guide_warn_11900802 = "이건 지금 장비의 정련 레벨이야. 장비는 3번 정련할 수 있어.",
  str_guide_warn_11900803 = "여기서 장비를 정련했을 때 얻는 효과를 볼 수 있어. 기본 속성도 증가하고, 오로리안의 스킬도 강화될 거야~",
  str_guide_warn_11900804 = "정련을 하려면 오로리안이 기본 개방 조건을 충족하고, 정련에 필요한 재료를 소모해야 해.",
  str_guide_warn_11900805 = "그리고 「엘레멘툼」은 주간 활약 보상과 다른 방법을 통해 얻을 수 있어. 아이콘을 누르면 자세한 획득 방법을 확인할 수 있을 거야.",
  ["str_guide_circle_N30_15-2_RtT"] = "일루미나 전투병",
  ["str_guide_circle_N30_15-2_Rt"] = "일루미나군의 평범한 전투병입니다. 소총과 단검을 능숙하게 다루며, 끈기와 근면성, 적극적인 투지, 희생을 두려워하지 않는 정신으로 유명합니다.",
  ["str_guide_circle_N30_15-2_LbT"] = "특성",
  ["str_guide_circle_N30_15-2_Lb"] = "주로 원거리 공격을 가하며, 전투가 치열할 때는 돌진해 근접전을 펼쳐 최대한 빠르게 상대를 처치합니다.",
  ["str_guide_circle_N30_15-2_RbT"] = "조심하세요!",
  ["str_guide_circle_N30_15-2_Rb"] = "HP가 50% 미만일 시 무기를 전투 단검으로 전환해 근접 공격을 진행하며, 누적된 적혈이 모두 HP로 회복되고, 공격력과 방어력이 증가합니다.",
  ["str_guide_circle_N30_15-9_Lt"] = "일루미나에서 개발한 작전 로봇입니다. 내부 테스트에서 훌륭한 모습을 보였으나, 아직 실전에 투입되지는 않았습니다.",
  ["str_guide_circle_N30_15-9_LtT"] = "드릴러",
  ["str_guide_circle_N30_15-9_Lb"] = "드릴러는 두 개의 형태를 가지고 있습니다. 일반 형태일 때는 주변을 돌아다니며 턴마다 일정 수량의 체인 존과 어시스트 존을 발굴합니다. 필드의 체인 존이 일정 수량이 되면 흡수해서 드릴러 플랫폼을 조립합니다.",
  ["str_guide_circle_N30_15-9_LbT"] = "적 특성",
  ["str_guide_circle_N30_15-9_Rb"] = "필드의 어시스트 존 수량이 적을 시 드릴러가 발굴하는 어시스트 존 수량이 증가합니다.",
  ["str_guide_circle_N30_15-9_RbT"] = "주의",
  ["str_guide_circle_N30_15-9-2_Lt"] = "체인 존은 완벽하게 실체화된 에너지 블록입니다. 드릴러 플랫폼 조립에 사용할 수 있으며, 필드에 있으면 지상 유닛이 통과하지 못하도록 막을 수 있습니다.",
  ["str_guide_circle_N30_15-9-2_LtT"] = "체인 존",
  ["str_guide_circle_N30_15-9-2_Rb"] = "적의 턴일 때 필드의 체인 존 수량이 6개에 도달했을 경우 드릴러가 특수 스킬을 발동해 드릴러 플랫폼을 조립합니다.",
  ["str_guide_circle_N30_15-9-2_RbT"] = "조립에 필요한 부품",
  ["str_guide_circle_N30_16-14_Lt"] = "최강의 「팬텀」 중 한 명으로, 자신의 자리가 위협당하자 망설이지 않고 전력을 다해 싸우는 것을 선택했습니다.",
  ["str_guide_circle_N30_16-14_LtT"] = "피제로",
  ["str_guide_circle_N30_16-14_Lb"] = "오로리안이 이동한 칸이 모두 붕괴합니다. 칸이 부족할 경우, 피제로가 강력한 마법을 시전해 공간을 재창조하고 피해를 입힙니다.",
  ["str_guide_circle_N30_16-14_LbT"] = "적 특성",
  ["str_guide_circle_N30_16-14_Rt"] = "이동할 노선을 잘 계획해 피제로의 공간 재창조로 인한 피해를 최대한 덜 받아야 합니다.",
  ["str_guide_circle_N30_16-14_RtT"] = "대응 전략",
  str_guide_circle_N30_tower10_LtT = "기계 사냥꾼",
  str_guide_circle_N30_tower10_LbT = "적 특성",
  str_guide_circle_N30_tower10_RbT = "주의",
  str_guide_circle_N30_tower10_Lt = "이곳의 비밀을 지키기 위해 특별히 만들어진 고대의 호위병입니다. 녀석의 공격과 추격은 벗어나기 어렵고, 오랜 세월에 대처하기 위해 강력한 자기 회복 능력도 지니고 있어 그 누구도 홀로 맞서길 원치 않습니다.",
  str_guide_circle_N30_tower10_Lb = "턴마다 자신의 주변 2서클 범위에 가드 에어리어를 소환하며, 오로리안은 가드 에어리어 내에서 공격하거나 이동 시 추가 피해를 입습니다. 기계 사냥꾼이 행동을 시작할 때 HP 자물쇠 상태에 진입할 경우 재생 에너지를 소모해 HP를 최대치로 회복합니다.",
  str_guide_circle_N30_tower10_Rb = "기계 사냥꾼이 HP 자물쇠까지 피해를 입을 시 다음 턴에 매우 위험한 공격을 시전하며, 가드 에어리어 범위 내의 적 HP를 강제로 1까지 떨어트립니다.",
  str_guide_circle_N30_tower10_3_LtT = "벤누 가디언",
  str_guide_circle_N30_tower10_3_Lt = "비경 깊은 곳에 숨은 고대의 수호자로, 잦은 침입자들의 소란에 깨어나게 되었습니다. 그 강력한 능력은 암귀조차 두려워하며, 녀석이 사방을 떠돌게 놔두는 수밖에 없었습니다.",
  str_guide_circle_N30_tower10_3_LbT = "적 특성",
  str_guide_circle_N30_tower10_3_Lb = "강력한 힘을 가지고 있으며, 공격을 받으면 분노 수치를 축적합니다. 분노 수치가 일정 수준에 도달하면 분노 상태에 진입하며, 받는 피해가 감소하고 추가로 강력한 스킬을 시전합니다. 벤누 가디언이 행동을 시작할 때 HP 자물쇠 상태에 진입할 경우 재생 에너지를 소모해 HP를 최대치로 회복합니다.",
  str_guide_circle_N30_tower10_3_RbT = "주의",
  str_guide_circle_N30_tower10_3_Rb = "항상 벤누 가디언의 분노 수치에 주의하고 조심해서 행동하세요!",
  ["str_guide_circle_15-14_LtT"] = "실험체 헬리오스",
  ["str_guide_circle_15-14_Lt"] = "10여 년간 어둠의 밑바닥에서 생존한 일루미나 병사입니다. 모든 것을 잊어버리고 오직 싸우는 법만을 기억하고 있습니다. 더욱 무서운 것은 누군가에 의해 개조된 후 전투 능력이 더 강해졌다는 점입니다...",
  ["str_guide_circle_15-14_RtT"] = "적 특성",
  ["str_guide_circle_15-14_Rt"] = "강한 전투 능력을 가진 개체로, 피해를 입을 시 적혈 수치를 누적합니다. 공격이 대상에게 명중하지 못할 경우 공포의 인장을 시전합니다. 필드에 인장이 많을수록 헬리오스의 스킬이 더욱 강력해집니다.",
  ["str_guide_circle_15-14_RbT"] = "대응 전략",
  ["str_guide_circle_15-14_Rb"] = "각인의 위치에 주목하고 헬리오스의 추격을 피하세요!",
  str_guide_circle_621_RtT = "십자 프리즘 칸",
  str_guide_circle_621_Rt = "연결 이동 시 주변 십자형 4칸을 동일 색상으로 바꿉니다.",
  ["str_guide_circle_N30_16-9_Lt"] = "거미를 닮은 특정 암귀 개체로, 진화 과정에서 거미 무리의 행동을 학습했습니다. 때문에 햇빛이 닿지 않는 어둠 속에서 은둔 생활을 합니다.",
  ["str_guide_circle_N30_16-9_LtT"] = "거미 여왕",
  ["str_guide_circle_N30_16-9_Lb"] = "번식력이 매우 강하며, 거미줄을 잘 짜서 사냥 환경을 만듭니다.",
  ["str_guide_circle_N30_16-9_LbT"] = "특성",
  ["str_guide_circle_N30_16-9_Rt"] = "거미줄 청소에 주의하세요. 거미 여왕이 소환하는 거미 알과 새끼 거미를 제때 처리해야 합니다.",
  ["str_guide_circle_N30_16-9_RtT"] = "대응 전략",
  ["str_guide_circle_N30_16-3_Lt"] = "일루미나의 베테랑 군인으로, 잘 드러나진 않지만 근접전의 고수입니다. 격렬한 전투 중 적의 공격 의도를 예리하게 감지하고 반격합니다.",
  ["str_guide_circle_N30_16-3_LtT"] = "일루미나 정예 전투병",
  ["str_guide_circle_N30_16-3_Lb"] = "적이 액티브 스킬을 시전할 때마다 즉시 적을 향해 1칸을 이동하고 공격합니다.",
  ["str_guide_circle_N30_16-3_LbT"] = "반격 능력",
  ["str_guide_circle_N30_16-3_Rt"] = "피해를 입으면 적혈 수치가 누적되며, 플레이어가 이번 턴에 피해를 입히지 않을 시 누적된 모든 적혈 수치가 즉시 HP로 회복됩니다.",
  ["str_guide_circle_N30_16-3_RtT"] = "강인-강화",
  str_guide_warn_12000101 = "「떨어지는 여명의 빛」 이벤트가 시작됐어! 이벤트 기간에는 「연방 보급센터」가 계속 열려 있을 거야.",
  str_guide_warn_12000102 = "프리즘을 소모해서 획득한 「물자 분배권」은 「연방 보급센터」에서 각종 보상 아이템으로 교환할 수 있어.",
  str_guide_warn_12000103 = "그로누 선배가 새로 개발한 군사 훈련용 「협력 모의전」 시스템에서는 오로리안들과 함께 종합 훈련을 해볼 수도 있어~",
  str_guide_warn_12000104 = "이벤트에 참가하면 특별 사건부의 임무를 완료할 수 있어.",
  str_guide_warn_12000105 = "매일 출석하면 보상을 수령할 수 있으니까, 매일 로그인하는 것도 잊지 말아줘.",
  str_guide_warn_12000106 = "이벤트에 대해 더 궁금한 점이 있다면, 이벤트의 상세 규칙을 확인해 봐.",
  str_guide_warn_12100101 = "「지난날의 재현」 이벤트가 시작됐어! 「가족의 날」에서 우린 미아와 함께 과거의 이야기를 다시 경험하고 조사할 거야~",
  str_guide_warn_12100102 = "「과거의 그림자」에서 우린 어려운 시험과 마주하게 될 거야.",
  str_guide_warn_12100103 = "이벤트 스테이지를 완료하거나 프리즘을 소모해서 획득한 「물의 수정」은 「점술의 방」에서 각종 보상 아이템으로 교환할 수 있어.",
  str_guide_warn_12100104 = "매일 출석하면 [가족의 기억] 내 보상을 수령할 수 있으니까, 매일 로그인하는 것도 잊지 말아줘.",
  str_guide_warn_12100105 = "이벤트에 참가하면 특별 사건부의 임무를 완료할 수 있어.",
  str_guide_warn_12100106 = "이벤트에 대해 더 궁금한 점이 있다면, 이벤트의 상세 규칙을 확인해 봐.",
  ["str_guide_circle_N31_1-14_Lt"] = "마임 카르티마가 방패를 들면 정면에서 받는 피해가 감소합니다. 해당 효과는 스턴, 공포 또는 마비 등의 제어 효과를 받으면 사라집니다.",
  ["str_guide_circle_N31_1-14_LtT"] = "카르티마-방패의 가호",
  ["str_guide_circle_N31_1-14_Lb"] = "마임 카르티마는 출전 후 첫 2턴간 제어 효과에 면역됩니다.",
  ["str_guide_circle_N31_1-14_LbT"] = "카르티마-불굴",
  ["str_guide_circle_N31_1-14_Rt"] = "마임 카르티마는 대상의 위치에 따라 사슬철퇴로 자신의 우측 전방 영역을 공격하고, 방패로 자신의 좌측 전방의 대상을 넉백시킵니다.",
  ["str_guide_circle_N31_1-14_RtT"] = "전투 기교",
  ["str_guide_circle_N31_1-16_Lt"] = "환경을 제어하는 강력한 능력을 지니고 있으며, 환영의 수정의 영향으로 일부 일반공격 또는 스킬 피해에 면역됩니다.",
  ["str_guide_circle_N31_1-16_LtT"] = "더럽혀진 마음의 「조슈아」",
  ["str_guide_circle_N31_1-16_Lb"] = "환영의 수정 효과에 따라 이번 턴에 일반공격 또는 스킬 사용 여부를 선택하고, 각기 다른 전략을 취해 더럽혀진 마음의 「조슈아」를 상대해야 합니다.",
  ["str_guide_circle_N31_1-16_LbT"] = "전투 기교",
  str_guide_popstar_fail_tip = "제거 전략",
  str_guide_popstar_fail_desc = "적절하게 오로리안 스킬을 사용해 최대한 많은 칸을 제거하세요. 제거 후의 상황을 미리 고려해서 제거를 진행하면 더 많은 칸을 제거할 수 있습니다.",
  str_guide_circle_N31_star1_Rt = "칸과 함께 제거할 수 있습니다. 제거하지 않을 경우 남은 시간이 종료되면 파괴된 칸으로 전환됩니다.",
  str_guide_circle_N31_star1_RtT = "룬 칸",
  str_guide_circle_N31_star2_Rt = "강화 칸을 제거하면 추가로 1칸 더 제거된 것으로 집계됩니다.",
  str_guide_circle_N31_star2_RtT = "강화 칸",
  str_guide_circle_N31_star3_Rt = "잠긴 칸은 색을 변경할 수 없습니다. 잠긴 칸을 제거하면 일반 칸으로 전환됩니다.",
  str_guide_circle_N31_star3_RtT = "잠긴 칸",
  str_guide_warn_6012102 = "여길 터치해서 랭크 정보를 확인해 봐.",
  str_guide_warn_6012104 = "여기를 터치하면 「랭킹」을 확인할 수 있어.",
  str_guide_warn_6012106 = "여기를 터치해 계속 확인해 봐.",
  str_guide_warn_6012107 = "「수렵 의뢰」를 완료해도 「종말의 파편」과 「종말의 말씀」을 얻을 수 있어.",
  str_guide_warn_6012108 = "「추격자의 쉼터」에서는 「종말의 파편」과 「종말의 말씀」으로 솔람버, 오로리안과 스타 마커를 교환할 수 있어.",
  str_guide_warn_6012202 = "여러 파티를 결성해서 보스에게 도전할 수 있어. 모든 파티가 입힌 피해량 합산이 최종 성적이 될 거야.",
  str_guide_warn_6012203 = "도전에 참여하지 않으면 랭크와 휘장을 얻을 수 없어.",
  str_guide_warn_6012204 = "여길 터치해서 랭크 정보를 확인해 봐.",
  str_guide_warn_6012206 = "여기를 터치하면 「현재 순위」를 확인할 수 있어.",
  str_guide_warn_6012208 = "여기를 터치해 계속 확인해 봐.",
  str_guide_warn_6012209 = "「수렵 의뢰」를 완료해도 「종말의 파편」과 「종말의 말씀」을 얻을 수 있어.",
  str_guide_warn_6012210 = "「추격자의 쉼터」에서는 「종말의 파편」과 「종말의 말씀」으로 솔람버, 오로리안과 스타 마커를 교환할 수 있어.",
  str_guide_warn_12200201 = "으앗, 여긴 어디지? 앞에는... 「영원한 기억의 수정」이 또 있잖아?",
  str_guide_warn_12200202 = "결국 여전히 못 나간 모양이네요... 그래도 괜찮아요!\n시간 회귀 주문을 큰 소리로 외치고 여길 눌러 보는 거예요!",
  str_guide_warn_12200301 = "쉿...근처에서 누가 뭔가 말하고 있는 것 같은데요?\n크흠, 훔쳐 듣는 거 아니거든요! 이건... 정보 수집이라구요!",
  str_guide_warn_12200401 = "헤에, 제 말 맞죠? 역시나 엄청난 정보를 수집했어요!\n네? 못 외우겠다구요? 그럼 수집한 정보를 여기 두세요~",
  str_guide_warn_12200402 = "어때요? 이렇게 해 두면 안 잊어버리겠죠?\n앞으로도 많이 듣고 보고 정보를 가득 채워 보세요~",
  str_guide_warn_12200101 = "「붕괴의 끝자락」 이벤트가 시작됐어! 우린 「뒤바뀐 시간」에서 영원한 기억의 수정 속 수수께끼를 조사하게 될 거야~",
  str_guide_warn_12200102 = "「영역 붕괴」에서 우린 그 세계 속 일련의 어려운 도전에 직면하게 돼.",
  str_guide_warn_12200103 = "이벤트 스테이지를 완료하거나 프리즘을 소모해서 획득한 「마음의 이슬」은 「추억의 방」에서 각종 보상 추첨에 사용할 수 있어.",
  str_guide_warn_12200104 = "매일 출석하면 「그리움의 나날」에서 보상을 수령할 수 있으니까, 매일 로그인하는 것도 잊지 말아줘.",
  str_guide_warn_12200105 = "이벤트에 참가하면 특별 사건부의 임무를 완료할 수 있어.",
  str_guide_warn_12200106 = "이벤트에 대해 더 궁금한 점이 있다면, 이벤트의 상세 규칙을 확인해 봐.",
  str_guide_circle_N33_15_Lt = "데누오 협곡 부근에서만 출몰하는 매우 희귀한 나비로, 좀처럼 모습을 드러내지 않으며, 무척 민감한 감지 능력을 지니고 있습니다. 성체가 된 나비의 전투력은 결코 무시할 수 없습니다.",
  str_guide_circle_N33_15_LtT = "여신나비",
  str_guide_circle_N33_15_Lb = "꽃가루를 전파해 식물의 성장을 촉진시키며, 이를 통해 자신을 지키고 적을 공격합니다.",
  str_guide_circle_N33_15_LbT = "적 특성",
  str_guide_circle_N33_15_Rt = "위치를 이동해 여신나비가 악마의 풀에게 꽃가루를 전하지 못하게 하면, 악마의 풀이 공격성을 지니는 것을 방지할 수 있습니다.",
  str_guide_circle_N33_15_RtT = "대응 전략",
  str_guide_circle_chapter18_14_Rb = "집중 공격으로 오염된 엔진 7호를 마비 상태에 빠트리면 일루미나 요새 관문에 대한 공격을 지연시킬 수 있습니다.",
  str_guide_circle_chapter18_14_RbT = "대응 전략",
  str_guide_circle_chapter18_14_Rt = "일루미나에서 제작한 거대 전투 기계였지만, 탑승자가 「늪」에 오염돼 이성을 잃은 뒤에는 오히려 가장 두려운 위협으로 변모했습니다.",
  str_guide_circle_chapter18_14_RtT = "오염된 엔진 7호",
  str_guide_warn_80010102 = "이브의 꿈속에 들어갈 수 있는 건 너뿐이야...",
  str_guide_warn_80010103 = "「기억의 조각」이 제시하는 퀘스트를 완료하면 루맘버 보상을 얻을 수 있고, 이브와 관련된 숨겨진 이야기도 개방할 수 있어.",
  str_guide_warn_80010104 = "여기서는 꿈의 세계에서 얻은 「탈바꿈의 꽃술」과 「가라앉은 의식 조각」을 가지고 이브의 코스튬이나 다양한 보상으로 교환할 수 있어.",
  str_guide_warn_80010105 = "꿈의 세계에서 수집한 건 모두 이브가 이 안에 소중하게 보관할 거야.",
  str_guide_warn_80010106 = "꿈의 세계에서 다양한 퀘스트를 완료하면 「동행 세트」를 얻을 수 있어.",
  str_guide_warn_80010107 = "여길 터치하면 자세한 설명을 볼 수 있어.",
  str_guide_warn_80010202 = "이건... 왠지 소중한 사람이 나한테 준 물병이었던 것 같아.",
  str_guide_warn_80010203 = "기억나. 이 물병은... 나한테 특별한 힘을 줄 수 있어!",
  str_guide_warn_80010204 = "어? 안은 텅 비어 있잖아... 그럼 힘내서 「미소의 물」을 물병에 가득 모아야지! 「미소의 물」이 많을수록 이브도 더 큰 힘을 얻을 수 있을 거야~",
  str_guide_warn_80010205 = "근데 그것보다... 집 앞에 누가 있는 것 같은데?",
  str_guide_circle_80010206 = "저, 저게 뭐지?!",
  str_guide_circle_80010207 = "괜찮아... 무섭지 않아! 여길 눌러서 무슨 일이 있는지 확인해 봐야겠어!",
  str_guide_warn_80010208 = "대체 누구지...? 날 찾아온 건가?",
  str_guide_circle_80010304 = "앗! 찾았다! 저건... 아까 봤던 그 검은 그림자인가?",
  str_guide_warn_80010305 = "검은 그림자가 암귀를 소환하고 있잖아?! 그럼 그냥 내버려 둘 순 없어!",
  str_guide_warn_80010306 = "선생님이 그러셨어. 적이 너무 강할 땐 너무 집착하지 말고 난이도를 바꾸면 된다고 말이야~",
  str_guide_warn_80010307 = "「꿈」의 난이도는 「의식」보다 높아. 하지만 「꿈」을 3성으로 클리어하면 「미소의 물」을 얻어서 「행복을 인도하는 미소」의 레벨을 높일 수 있어.",
  str_guide_warn_80010308 = "「악몽의 기운」을 처리할 때마다 내 「마음」은 영향을 받게 될 거야...",
  str_guide_warn_80010309 = "그래도 괜찮아! 이브는 열심히 단련해 왔으니까, 매일 아침 5시가 되면 「마음」이 3개 회복될 거야~ 대신 마음이 가득 차면 더 늘어나진 않아...",
  str_guide_circle_80010402 = "찾았어!",
  str_guide_warn_80010403 = "아무튼 일단 챙겨보자.",
  str_guide_warn_80010404 = "물건을 많이 수집하고 나면, 혹시 물건들끼리 뭔가 신기한 효과를 내거나 하진 않을까?",
  str_guide_warn_80010405 = "아... 깜빡할 뻔했잖아. 저 검은 그림자를 마저 쫓아가야지!",
  str_guide_warn_80010406 = "화면을 슬라이드해서 주변을 잘 살펴야 해!",
  str_guide_warn_80010407 = "여길 터치하면 시점을 제자리로 돌아오게 만들 수 있어.",
  str_guide_warn_80010408 = "해야 할 일이 많으니까, 방금 그 정보들은 여기 기록해 두는 게 좋겠어.",
  str_guide_circle_80010501 = "어른들은 다들 이브한테 이 문을 나가면 안 된다고 했어... 나가려면 문을 부수는 수밖에 없는 걸까?",
  str_guide_circle_80010502 = "그럼... 한번 해보는 수밖에!",
  str_guide_circle_80011101 = "저, 저게 뭐지?! 녀석들... 세상을 파괴하고 있는 거야? ...흥, 이브는 하나도 안 무섭거든! 여길 누르면 내가 직접 녀석들을 쫓아낼 거야!",
  str_guide_warn_80010601 = "나... 강해진 걸까? 그럼 앞으로의 싸움도 조금은 쉬워지지 않을까?",
  str_guide_warn_80010701 = "이건... 나한테 새로운 능력이 생긴 건가? 나중에 한번 사용해 보자!",
  str_guide_warn_80010121 = "어라? 이건 뭐지?",
  str_guide_warn_80010122 = "우와! 나 왠지 특별한 힘을 얻은 것 같은데? 후후~ 그럼 어디 한번 활용해 보자! 아무래도 2턴마다 한 번 쓸 수 있는 모양이네~",
  str_guide_warn_80010521 = "어라, 내 힘이... 뭔가 변한 것 같은데?",
  str_guide_warn_80010522 = "원하는 위치를 고르면 되나? 어렵진 않은 것 같아. 자, 한번 해볼게~",
  str_guide_warn_80010931 = "새로운 힘을... 손에 넣었나?",
  str_guide_warn_80010932 = "그럼... 한번 써 볼래.",
  str_guide_warn_80011331 = "내 힘이 또 달라졌어...",
  str_guide_warn_80011332 = "이제 한번 쉴 필요 없이 이 힘을 쓸 수 있게 된 것 같아...",
  str_guide_warn_80011631 = "또 새로운 힘을 얻었어!",
  str_guide_warn_80011632 = "이 힘이 있으면... 나... 이제 더는 망설이지 않을 거야!",
  str_guide_warn_12300101 = "리조트가 마음에 드는 모양이네? 그럼 잠깐 얘기 좀 나눌 수 있을까?",
  str_guide_warn_12300201 = "시설에서 새로운 패스 토큰이 생성됐어. 수집해서 잘 활용해야 사업의 「선순환」을 이룰 수 있어.",
  str_guide_warn_12300202 = "호텔 구역의 패스 토큰도 수집할 수 있겠네. 어떻게 효율적으로 활용할지 고민하는 것도 매니저의 업무야.",
  str_guide_warn_12300203 = "패스 토큰은 어떻게 쓰는 거냐고? 시설 레벨업에 사용하면 돼. 레벨업한 시설은 더 빠르게 패스 토큰을 생산할 수 있는데, 이게 바로 돈이 돈을 벌게 만드는 방법이야.",
  str_guide_warn_12300204 = "왜 한 번에 모든 패스 토큰을 수집할 수 없냐고...? 당연히 안전을 위해서지. 그리고 패스 토큰은 하나하나씩 손으로 집어야 안심이 되잖아!",
  str_guide_warn_12300205 = "방금 얘기했던 시설 레벨업하는 법 아직 기억하지? 지금 바로 해보자!",
  str_guide_warn_12300301 = "시설 레벨업은 패스 토큰 외에도 일정한 조건을 만족해야 돼. 어디 보자... 좋아! 지금 레벨업할 수 있겠어.",
  str_guide_warn_12300302 = "레벨업하면 시설이 더 인기를 끌게 될 거야. 다시 말해서 더 효율적으로 패스 토큰을 생산할 수 있게 되는 거지. 게다가 다른 오로리안과의 만남과 레벨업 보상까지 개방될 거야.",
  str_guide_warn_12300303 = "여기를 터치해서 레벨업 계획에 사인하면 레벨업을 완료할 수 있어.",
  str_guide_warn_12300401 = "이렇게 하면 레벨업이 완료된 거야. 깜빡하고 안 챙긴 패스 토큰은 내가 대신 잘 모아뒀어. 고맙단 말은 안 해도 돼.",
  str_guide_warn_12300501 = "다른 오로리안과의 만남이 개방된 거 같은데? 어서 확인해 보자.",
  str_guide_warn_12300601 = "왠지 무척 아름답고 지적이면서 상냥한 소녀가 널 기다리고 있는 거 같네.",
  str_guide_warn_12300701 = "어떻게 오로리안과의 만남을 개방하는지는... 내가 안 알려 줘도 되겠지?",
  str_guide_warn_12300801 = "만남 수첩에서는 개방된 만남을 확인하거나, 지난 만남을 회상할 수 있어.",
  str_guide_warn_12300802 = "리조트 경영에 대해 궁금한 게 더 있다면, 내가 특별히 널 위해 준비해 둔 수첩을 확인해 봐.",
  str_guide_warn_12400101 = "「밸리 파라다이스」 이벤트가 시작됐어! 「주간 공연」에서는 놀이공원의 다양한 시설들을 둘러볼 수 있어~",
  str_guide_warn_12400102 = "「야간 행사」에서는 밤이 된 놀이공원에서 더 어려운 도전에 직면하게 될 거야.",
  str_guide_warn_12400103 = "「에이스 매니저」에서는 놀이공원 운영을 맡게 될 거야. 잘 관리해 줘~",
  str_guide_warn_12400104 = "이벤트 스테이지를 완료하거나 프리즘을 소모해서 획득한 「플레이 코인」은 「토이 크레인」에서 각종 보상을 뽑는 데 쓸 수 있어~",
  str_guide_warn_12400105 = "매일 출석하면 「체크인 카운터」에서 보상을 수령할 수 있으니까, 매일 로그인하는 것도 잊지 말아줘.",
  str_guide_warn_12400106 = "이벤트에 참가하면 특별 사건부의 임무를 완료할 수 있어.",
  str_guide_warn_12400107 = "이벤트에 대해 더 궁금한 점이 있다면, 이벤트의 상세 규칙을 확인해 봐.",
  str_guide_warn_12500101 = "「지평선의 교향시」가 이벤트가 시작됐다! 「황혼의 전략」에서 일루미나 동료들의 의뢰를 완료하고 더스크 타운을 재건하자!",
  str_guide_warn_12500102 = "「어둠 속으로」에서는 선발대를 파견해 낯과 밤의 경계선을 조사하고 암귀의 동향을 파악할 것이다!",
  str_guide_warn_12500103 = "매일 출석하면 「신병 출석」 보상을 수령할 수 있으니까, 잊지 않도록 해.",
  str_guide_warn_12500104 = "이벤트에 참가하면 특별 사건부의 임무를 완료할 수 있어.",
  str_guide_warn_12500105 = "이벤트에 대해 더 궁금한 점이 있다면, 이벤트의 상세 규칙을 확인해 보도록 해.",
  str_guide_warn_10181401 = "이곳에서 일루미나 요새 관문의 내구도를 확인할 수 있습니다.\n오염된 엔진 7호가 관문에 접근했을 때 방어 로켓포로 적을 공격하세요.",
  str_guide_circle_80010521_Lb = "「인형」을 들고 있는 녀석입니다. 처치 시 모든 암귀에게 피해를 입히고, 「인형」을 랜덤으로 전달합니다. 만약 다른 암귀가 먼저 사망할 경우, 소유자가 실드를 획득합니다.",
  str_guide_circle_80010521_LbT = "「즐거운 마음」",
  str_guide_circle_80010521_Rb = "「인형」과, 함께, 환상을, 깨트려!",
  str_guide_circle_80010521_RbT = "부서진 인형",
  str_guide_circle_80010621_Lt = "숲 속성 데몬아이는 필드 등장 시 3턴간 잠들며, 잠든 동안 다른 속성 데몬아이의 방어력이 대폭 감소합니다. 데몬아이는 피해를 입으면 즉시 깨어납니다.",
  str_guide_circle_80010621_LtT = "임무 수행",
  str_guide_circle_80010621_Lb = "떠나기... 전에... 조금... 쉬어...",
  str_guide_circle_80010621_LbT = "부서진 인형",
  str_guide_circle_80010721_Lt = "턴 종료 시 암귀가 실드를 지니고 있을 경우 오로리안에게 고정피해를 1회 입힙니다.",
  str_guide_circle_80010721_LtT = "부끄러운 분노",
  str_guide_circle_80010721_Rt = "...이렇게까지 해야... 너한테... 주목을 받을 수... 있는 건가...",
  str_guide_circle_80010721_RtT = "부서진 인형",
  str_guide_circle_80010821_Lt = "보스가 3턴마다 에너지를 축적하며, 에너지 인장 개당 보스에게 3%의 공격력 보너스를 제공합니다. 턴 종료 시 모든 인장을 제거하지 못할 경우 보스가 실드를 8단계 획득합니다.",
  str_guide_circle_80010821_LtT = "감옥 속",
  str_guide_circle_80010821_Rt = "감옥을... 부순 건... 널... 깨우기 위해서야...",
  str_guide_circle_80010821_RtT = "부서진 인형",
  str_guide_circle_80010821_Rb = "보스가 공격을 받을 때마다 인장이 1개 제거됩니다. 에너지 인장은 보스의 공격력과 생존력을 대폭 증가시키므로, 최대한 빠르게 제거해야 합니다!",
  str_guide_circle_80010821_RbT = "대응 전략",
  str_guide_circle_80011021_Rt = "적 전체의 공격력이 대폭 증가합니다. 오로리안은 적에게 피해를 입혀 HP를 회복할 수 있습니다.",
  str_guide_circle_80011021_RtT = "치명적인 반격",
  str_guide_circle_80011021_Rb = "「발걸음을 멈추는」 거랑 「포기 선언」이랑 무슨 차이가 있는데?",
  str_guide_circle_80011021_RbT = "「이브」",
  str_guide_circle_80011121_Rt = "파티는 전송 소용돌이를 통해 원하는 위치로 이동해 연쇄 스킬을 시전할 수 있으며, 연쇄 스킬의 피해가 증가합니다.",
  str_guide_circle_80011121_RtT = "자유 연쇄",
  str_guide_circle_80011121_Rb = "날 따라 와. 넌 할 수 있어. 네가 가고 싶은 곳은 어디든지 가는 거야.",
  str_guide_circle_80011121_RbT = "「이브」",
  str_guide_circle_80011421_Rt = "룬 생성 효율이 너무 낮다고 생각한 섀도는 섀도고스트를 직접 소환하기로 결정했습니다.",
  str_guide_circle_80011421_RtT = "적 특성",
  str_guide_circle_80011421_Rb = "연결 기간 동안 오로리안이 입히는 피해가 대폭 증가하며, 일반공격 및 부가 피해 효과를 포함합니다.",
  str_guide_circle_80011421_RbT = "파티 특성",
  str_guide_circle_80011521_Rt = "블레이저를 처치하면 스테이지에서 승리합니다. 블레이저 처치 전까지 스펠하운드가 계속해서 부활합니다.",
  str_guide_circle_80011521_RtT = "적 특성",
  str_guide_circle_80010921_Lb = "필드 내 모든 암귀가 1회 부활합니다. 암귀 사망 시 필드 내 다른 암귀의 공격력이 증가합니다.",
  str_guide_circle_80010921_LbT = "적 특성",
  str_guide_circle_80010921_Rb = "발악할수록 더 고통스러워.",
  str_guide_circle_80010921_RbT = "「이브」",
  str_guide_circle_80011321_Lb = "적의 스킬이 오로리안에게 추가하는 파열의 인장 수량이 대폭 증가하나, 오로리안이 공격할 때마다 파열의 인장을 1개 감소시킵니다.",
  str_guide_circle_80011321_LbT = "적 특성",
  str_guide_circle_80011321_Rb = "파열의 인장이 주는 디버프 효과가 대폭 증가합니다. 적을 공격해 최대한 빠르게 파열의 인장의 수를 줄여야 합니다!",
  str_guide_circle_80011321_RbT = "대응 전략",
  str_guide_circle_80011621_Lb = "본 스테이지부터 파티가 특수한 특성을 획득합니다. 파티가 연결 전 적에게 피해를 1회 입힐 때마다 이번 턴에 파티 내 모든 오로리안의 공격력이 1% 증가합니다!",
  str_guide_circle_80011621_LbT = "최후의 성장",
  ["str_guide_circle_CN2-18_Lt"] = "고립의 아픔과 단절의 공포, 참을 수 없는 과거의 기억은 눈앞의 「이브」를 분리해 내고 말았습니다.",
  ["str_guide_circle_CN2-18_LtT"] = "슬픔의 사념체 「이브」",
  ["str_guide_circle_CN2-18_Rt"] = "턴이 시작될 때마다 새벽꽃을 소환하고 HP를 회복하며, 각 새벽꽃은 추가 회복 보너스를 제공합니다.",
  ["str_guide_circle_CN2-18_RtT"] = "적 특성",
  ["str_guide_circle_CN2-18_Rb"] = "특정 턴에는 자신에게 대량의 피해면역 단계를 추가하므로, 여러 차례의 피해를 통해 단계를 제거해야 합니다. 그렇지 않으면 다음 턴에 단계 수에 따라 대량의 HP를 회복합니다.",
  ["str_guide_circle_CN2-18_RbT"] = "스킬 설명",
  str_guide_circle_N34_18_1_RtT = "일루미나 의무병",
  str_guide_circle_N34_18_1_Rt = "의무병이 있는 곳이라면 사기가 항상 높아지는데, 이는 전우들이 부상을 입었을 때 누군가 자신을 구하러 온다는 것을 알게 되기 때문입니다. 일루미나 연방도 이를 잘 알고 있으며, 때문에 의무병에게 조금 더 좋은 장비를 제공해 생존력을 대폭 높였습니다.",
  str_guide_circle_N34_18_1_LbT = "특성",
  str_guide_circle_N34_18_1_Lb = "전투 능력이 없는 일루미나 병사입니다. 근처에 있는 일루미나 병사의 HP를 회복하고, 자신의 일부 적혈 수치를 회복합니다.",
  str_guide_circle_N34_18_1_RbT = "조심하세요!",
  str_guide_circle_N34__18_1_Rb = "일루미나 의무병이 피해를 입을 시 해당 피해 수치의 50%에 해당하는 적혈 수치를 누적하며, 일루미나 의무병의 현재 HP가 낮을수록 방어력이 증가합니다.",
  str_guide_circle_N34_18_2_RtT = "일루미나 무전병",
  str_guide_circle_N34_18_2_Rt = "소형 통신장치를 휴대하는 병사입니다. 장치가 너무 무겁기 때문에 일루미나 연방에서는 보조 장치를 개발해 내야만 했고, 이를 통해 「이동 중 통신」이 가능해졌습니다.",
  str_guide_circle_N34_18_2_LbT = "특성",
  str_guide_circle_N34_18_2_Lb = "전투 능력이 없는 일루미나 병사입니다. 일루미나 지원군을 전장에 소환할 수 있습니다.",
  str_guide_circle_10170901_RtT = "드레드위버",
  str_guide_circle_10170901_Rt = "모든 것을 파괴하겠다는 집념으로, 자신의 에너지 소모를 무시한 채 목적을 달성하려 하며, 이를 위해 자신의 수명이 줄어드는 것도 개의치 않습니다.",
  str_guide_circle_10170901_LbT = "패시브 효과",
  str_guide_circle_10170901_Lb = "파티의 이동이 끝날 때마다 드레드위버가 즉시 파티의 위치를 변화시켜, 파티의 연쇄 스킬 시전에 영향을 줍니다.",
  str_guide_circle_10170901_RbT = "공격 특성",
  str_guide_circle_10170901_Rb = "드레드위버의 HP가 50% 미만이 되면 희생제를 진행해 다음 턴에 자신의 HP 대부분을 불태우고 플레이어에게 대량의 고정피해를 입힙니다. 본 효과는 1회만 발동합니다.",
  str_guide_circle_2002901_RtT = "일루미나 L5형 탱크",
  str_guide_circle_2002901_Rt = "트럭을 개조한 일루미나의 탱크입니다. 장갑이 두꺼운 편은 아니며, 대량생산에 적합합니다. 충돌 능력과 연발포는 적의 경무장 부대를 섬멸하기에 충분합니다.",
  str_guide_circle_2002901_LbT = "적 특성",
  str_guide_circle_2002901_Lb = "적의 위치에 따라 연발포 또는 돌진을 사용해 적을 공격합니다.",
  str_guide_circle_2003001_RtT = "일루미나 화염방사병",
  str_guide_circle_2003001_Rt = "「모든 상대를 잿더미로 만든다」 ── 그들은 일루미나군의 효율성과 무자비함을 상징하며, 화염 앞에서 모든 존재는 평등합니다.",
  str_guide_circle_2003001_LbT = "적 특성",
  str_guide_circle_2003001_Lb = "피해를 입을 시 적혈 수치가 누적됩니다. 공격 시 범위 내 모든 대상에게 피해를 입히며, 동시에 작열 효과를 추가하고 화염을 생성합니다.",
  str_guide_circle_2003401_RtT = "오염된 일루미나 전투병",
  str_guide_circle_2003401_Rt = "적이 되어버린 옛 전우들, 이것이 바로 「이클립스」의 무서운 점입니다. 저들에게 자유를 줄 방법은 오직 지금 이 자리에서 쓰러트리는 것뿐입니다.",
  str_guide_circle_2003401_LbT = "적 특성",
  str_guide_circle_2003401_Lb = "턴 시작 시 HP가 40% 미만일 경우 행동력과 방어력이 증가하며, 공격 방식이 변경됩니다.",
  str_guide_circle_2003101_RtT = "일루미나 장교",
  str_guide_circle_2003101_Rt = "일루미나군의 하급 장교로, 전장에서 일반 병사를 지휘하는 책임을 맡고 있습니다. 대부분의 장교는 사관학교 출신이나, 진급해서 장교가 된 고참 병사도 소수 존재합니다.",
  str_guide_circle_2003101_LbT = "적 특성",
  str_guide_circle_2003101_Lb = "주변 일루미나 병사의 능력을 향상시키고, 대상의 일부 적혈 수치를 회복시킵니다. 다른 일루미나 병사가 없거나 적과 가까울 경우 직접 싸우며, 적을 베고 발로 차서 피해를 입힙니다.",
  str_guide_circle_2003101_RbT = "대응 전략",
  str_guide_circle_2003101_Rb = "적의 지휘관부터 먼저 처치하세요!",
  str_guide_circle_2905701_RtT = "머드번들",
  str_guide_circle_2905701_Rt = "이클립스의 일원 중 누군가가 만든 「작품」이라고 합니다. 여러 생물의 특징을 조합해 만든 암귀로, 공포의 늪으로 모든 것을 집어삼킬 수 있고, 시야에 들어 온 모든 것을 오염시킬 수 있습니다.",
  str_guide_circle_2905701_LbT = "적 특성",
  str_guide_circle_2905701_Lb = "늪을 만들고 그 속에 몸을 숨길 수 있으며, 늪에 위치한 오로리안의 행동을 방해하고 교란해 전장의 환경에 영향을 줍니다.",
  str_guide_circle_2905701_RbT = "대응 전략",
  str_guide_circle_2905701_Rb = "최대한 늪을 피하고, 스킬을 활용해 필드 위의 늪을 없애야 합니다!",
  str_guide_circle_29057011_RtT = "늪",
  str_guide_circle_29057011_Rt = "시야 안의 모든 생명과 물체가 오염되고 있습니다...",
  str_guide_circle_29057011_LbT = "특성",
  str_guide_circle_29057011_Lb = "오로리안이 일정 수량의 늪을 지나면 모든 아군 오로리안의 액티브 스킬 쿨다운 턴 수가 증가합니다.",
  str_guide_circle_29057011_RbT = "대응 전략",
  str_guide_circle_29057011_Rb = "늪은 오로리안의 범위 피해 스킬을 통해 없앨 수 있습니다.",
  str_guide_warn_815000101 = "어째서 꿈에서 벗어날 수 없는 거죠...? 설마 파로마 때문일까요...? 파로마는 아직도 꿈속에 갇혀 있는 걸까요?\n전환 버튼을 누르면 「유람 모드」로 전환됩니다. 조종사 씨, 절 도와준 것처럼 파로마도 도와주실 수 있을까요?",
  str_guide_warn_815000102 = "다시 버튼을 누르면 「추적 모드」로 돌아올 수 있답니다. 조종사 씨, 아무래도 우린 언제든지 제 꿈으로 돌아갈 수 있는 모양이네요.",
  str_guide_circle_80020201 = "이 저울을 누르면 제가 더 깊이 생각하고 추론할 수 있어요. 추론을 끝내야만 제가 대심판관님께서 주신 임무를 완수할 수 있을 거예요.",
  str_guide_circle_80020202 = "하지만 추론을 시작하기 전에 충분한 증거와 증언을 수집해야 해요... 주의 깊게 살펴보세요. 핵심 단서는 분명히 근처에 있을 테니까요!",
  ["str_guide_circle_CN5-15_Lt"] = "아버지의 간곡한 가르침을 이어받고, 모든 기대에 부응하는 가장 완벽한 「이리돈」이자, 가장 위대한 「대심판관」입니다.",
  ["str_guide_circle_CN5-15_LtT"] = "완전무결한 「이리돈」",
  ["str_guide_circle_CN5-15_Rt"] = "오로리안이 연쇄 스킬을 시전할 때마다 [빛의 방패]를 생성해 최대 HP의 일정 비율만큼 피해를 막아냅니다.",
  ["str_guide_circle_CN5-15_RtT"] = "빛의 방패",
  ["str_guide_circle_CN5-15_Lb"] = "꼭두각시를 조종하고 타인을 미혹하는 행위, 이러한 속임수도 그녀의 눈에는 그리 나쁜 것이 아닌 듯합니다. 이는 그녀가 가장 위대한 「대심판관」으로서 모든 것을 해석할 최종 권한을 가지고 있기 때문입니다.",
  ["str_guide_circle_CN5-15_LbT"] = "완전무결한 「이리돈」의 분신",
  ["str_guide_circle_CN5-15_Rb"] = "분신이 받은 피해는 실시간으로 완전무결한 「이리돈」에게 전달됩니다.",
  ["str_guide_circle_CN5-15_RbT"] = "피해 전이",
  ["str_guide_circle_CN5-18_Lb"] = "필드 밖에 있어 일반공격으로는 공격할 수 없으며, 타깃형 스킬로만 공격할 수 있습니다.",
  ["str_guide_circle_CN5-18_LbT"] = "완전무결한 「이리돈」의 분신",
  ["str_guide_circle_CN5-diaoxiang_Lt"] = "오만한 귀족 조각상입니다. 등장 시 아군에게 「편견」 상태를 1회 추가합니다. 접촉 시 붕괴하며, 소멸 시 해당 위치는 만색 칸으로 변하고, 「편견」 상태가 1개 감소합니다.",
  ["str_guide_circle_CN5-diaoxiang_LtT"] = "배심원 조각상",
  ["str_guide_circle_CN5-4_Rb"] = "특정 적은 빛의 방패 효과를 지니고 있습니다. 오로리안이 연쇄 스킬을 시전할 때마다 적은 「빛의 방패」를 생성해 최대 HP의 일정 비율만큼 피해를 막아냅니다.",
  ["str_guide_circle_CN5-4_RbT"] = "빛의 방패",
  ["str_guide_circle_CN5-8_Lt"] = "오만, 편견, 부패한 사상... 이 모든 것이 응축되어 백야성을 떠도는 악령이 되었고, 이 불락의 성의 구석구석까지 스며들었습니다.",
  ["str_guide_circle_CN5-8_LtT"] = "진홍의 악령",
  ["str_guide_circle_CN5-8_Lb"] = "플레이어와 가장 가까운 위치로 순간이동해 플레이어에게 여러 차례의 피해를 입히고 넉백시킵니다. 순간이동 거리가 멀수록 공격 횟수가 감소합니다.",
  ["str_guide_circle_CN5-8_LbT"] = "적 특성",
  ["str_guide_circle_CN5-8_Rb"] = "진홍의 악령은 플레이어의 위치를 방해하므로, 서둘러 처치하거나 멀리 떨어지는 것이 좋습니다.",
  ["str_guide_circle_CN5-8_RbT"] = "대응 전략",
  ["str_guide_circle_n35-7_LtT"] = "라임비스트",
  ["str_guide_circle_n35-7_Lt"] = "이 암귀의 머리카락과 날카로운 발톱은 언뜻 보면 맹수처럼 보입니다. 따라서 여러 변방 지역에 몰래 잠입해 추적, 수색, 사냥을 하는 데 매우 적합합니다.",
  ["str_guide_circle_n35-7_Lb"] = "오로리안의 위치에 따라 공격할 스킬을 선택하며, 오로리안을 공격할 수 없을 경우 자신의 HP를 회복합니다.",
  ["str_guide_circle_n35-7_LbT"] = "적 특성",
  ["str_guide_circle_n35-7_Rb"] = "암귀의 공격 범위에 주의하면서 항상 아군의 위치를 확인하세요!",
  ["str_guide_circle_n35-7_RbT"] = "대응 전략",
  ["str_guide_circle_n35-9_LtT"] = "33호",
  ["str_guide_circle_n35-9_Lt"] = "북방의 지하 유적을 지키고 있는 고대 오로리안입니다. 파손된 데다가 비정상적인 기동을 한 탓에 의식 모듈에 오류가 발생한 것 같습니다.",
  ["str_guide_circle_n35-9_Lb"] = "순간이동과 칸의 배열을 흩트리는 능력을 가지고 있으며, 칸의 에너지를 흡수해 오로리안을 공격합니다. 흡수한 칸이 많을수록 피해가 증가합니다.",
  ["str_guide_circle_n35-9_LbT"] = "적 특성",
  ["str_guide_circle_n35-9_Rb"] = "필드의 칸 분포와 적의 스킬 시전에 주의하세요!",
  ["str_guide_circle_n35-9_RbT"] = "대응 전략",
  str_guide_circle_n35_trap5352031_RtT = "치명적인 폭탄",
  str_guide_circle_n35_trap5352031_Rt = "일정 시간마다 폭발해 필드 내 모든 대상에게 피해를 입힙니다.",
  str_guide_circle_n35_trap5352031_RbT = "대응 전략",
  str_guide_circle_n35_trap5352031_Rb = "오로리안을 조종해 서둘러 적을 처치하세요. 그렇지 않으면 계속 피해를 입게 됩니다.",
  str_guide_warn_53540034 = "영역 카운트다운이 이곳에 표시됩니다.",
  str_guide_warn_16000101 = "「얼음 속 수수께끼」 이벤트가 시작됐어!\n우린 「눈 속의 추적」에서 새로운 동료들과 함께 모험을 시작할 거야!",
  str_guide_warn_16000102 = "「산맥의 모험」에서 우린 더 어려운 시험과 마주하게 될 거야.",
  str_guide_warn_16000103 = "「유적 캠프」에서는 「유적 파편」을 사용해 5성 오로리안과 솔람버 등의 보상을 교환할 수 있어. 이벤트 스테이지를 완료하거나 프리즘을 소모하면 「유적 파편」을 획득할 수 있어.",
  str_guide_warn_16000104 = "신규 콘텐츠 『자리야의 옷장』이 곧 개방될 거야. 각 버튼을 터치해서 신규 콘텐츠에 대해 확인해 봐!",
  str_guide_warn_16000105 = "이벤트에 참가하면 특별 사건부의 임무를 완료할 수 있어.",
  str_guide_warn_16000106 = "매일 출석하면 보상을 수령할 수 있으니까, 매일 로그인하는 것도 잊지 말아줘.",
  str_guide_warn_16000107 = "이벤트에 대해 더 궁금한 점이 있다면, 이벤트의 상세 규칙을 확인해 봐.",
  str_guide_warn_9700101 = "이번 소집에는 기간 한정으로 위시리스트 시스템이 적용될 거야. 버튼을 눌러서 위시리스트 메뉴를 열어 봐.",
  str_guide_warn_9700106 = "위시리스트 시스템은 해당 위시리스트가 속하는 소환에만 적용돼.",
  str_guide_warn_9700107 = "이번 기간의 확률 UP 오로리안은 위시리스트의 첫 번째 자리에 고정되고, 6성 오로리안 확률의 50%를 차지해.",
  str_guide_warn_9700108 = "위시리스트에서는 4개 속성에서 각 1명씩 6성 오로리안을 선택할 수 있어. 4개 속성의 오로리안은 각각 6성 오로리안 확률의 12.5%를 차지해.",
  ["str_guide_circle_n36-9_LtT"] = "종언제",
  ["str_guide_circle_n36-9_Lt"] = "혼돈 세력의 리더이자 토르의 아버지입니다. 그는 과거에 수많은 전쟁에 참여했으며, 언제라도 절대적인 강자입니다.",
  ["str_guide_circle_n36-9_Lb"] = "강력한 힘을 지닌 그는 다양한 스킬을 사용해 플레이어를 고정하거나 넓은 범위의 공격을 가하고, 동시에 넉백 효과를 발동할 수 있습니다.",
  ["str_guide_circle_n36-9_LbT"] = "적 특성",
  ["str_guide_circle_n36-9_Rb"] = "종언제는 플레이어의 넉백 및 위치이동 스킬의 영향을 받습니다. 적절한 타이밍에 이를 활용해 종언제의 공격 스킬을 피하거나 저지할 수 있습니다.",
  ["str_guide_circle_n36-9_RbT"] = "대응 전략",
  str_guide_warn_17000101 = "「메이드래곤의 휴일 ~이세계 여행~」 이벤트가 시작됐어! 우린 「집으로 가는 길」에서 새로운 동료들과 함께 모험을 시작할 거야!",
  str_guide_warn_17000102 = "메인 스테이지와 자원 정비에서 프리즘을 소모하면 이벤트 아이템 「접시」를 얻을 수 있어.",
  str_guide_warn_17000103 = "「접시」를 가지고 「토르의 주방」에서 다양한 보상을 받을 수 있어.",
  str_guide_warn_17000104 = "이벤트 기간에 아이테르네 티파티에 참가해 오로리안들과 함께 친밀도를 테스트해 봐!",
  str_guide_warn_17000105 = "매일 출석하면 보상을 수령할 수 있으니까, 매일 로그인하는 것도 잊지 말아줘.",
  str_guide_warn_17000106 = "각종 이벤트 도전에 참가하면 특별 사건부의 임무를 완료할 수 있어.",
  str_guide_warn_17000107 = "이벤트에 대해 더 궁금한 점이 있다면, 이벤트의 상세 규칙을 확인해 봐.",
  str_guide_warn_18000101 = "「흐르는 맹독과 더럽혀진 마음」 이벤트가 시작됐어! 우린 「지하 진료소」에서 새로운 동료들과 함께 모험을 시작할 거야!",
  str_guide_warn_18000102 = "「지난날의 먹구름」에서 우린 더 어려운 시험과 마주하게 될 거야.",
  str_guide_warn_18000103 = "이벤트 스테이지를 완료하거나 프리즘을 소모해서 획득한 「수납병」은 「밀실의 약속」에서 각종 보상 아이템으로 교환할 수 있어.",
  str_guide_warn_18000104 = "이벤트에 참가하면 특별 사건부의 임무를 완료할 수 있어.",
  str_guide_warn_18000105 = "매일 출석하면 보상을 수령할 수 있으니까, 매일 로그인하는 것도 잊지 말아줘.",
  str_guide_warn_18000106 = "이벤트에 대해 더 궁금한 점이 있다면, 이벤트의 상세 규칙을 확인해 봐.",
  ["str_guide_circle_CN7-15_Lt"] = "위쪽 세계에서 해저 마을로 내려와 제멋대로 구는 나쁜 귀족입니다.",
  ["str_guide_circle_CN7-15_LtT"] = "어인 국왕",
  ["str_guide_circle_CN7-15_Rt"] = "공격에 넉백 효과가 있으며, 필드 가장자리에 예포를 소환할 수 있습니다.",
  ["str_guide_circle_CN7-15_RtT"] = "적 특성",
  ["str_guide_circle_CN7-15_Lb"] = "필드 주변 예포의 공격 범위에 주의하고, 예포를 제때 처치해서 빠르게 전투를 끝내야 합니다.",
  ["str_guide_circle_CN7-15_LbT"] = "대응 전략",
  ["str_guide_circle_CN7-5_Lt"] = "포신처럼 생긴 암귀입니다. 동료를 엄호하고 아군에게 포격을 가합니다!",
  ["str_guide_circle_CN7-5_LtT"] = "예포",
  ["str_guide_circle_CN7-5_Rt"] = "공격 범위 내 적에게 포격을 가합니다. 대상이 없는 경우 자신의 공격을 강화하고 어인 국왕을 회복시킵니다.",
  ["str_guide_circle_CN7-5_RtT"] = "포격 출동",
  ["str_guide_circle_CN7-7_Lt"] = "아군은 연결로 통과할 수 없고, 적의 지상 유닛도 통과할 수 없지만, 스킬 시전에는 영향을 주지 않습니다.",
  ["str_guide_circle_CN7-7_LtT"] = "금제의 벽",
  str_guide_circle_80030101 = "「망원경」으로 먼곳의 거대한 성... 물의 주인의 신전을 볼 수 있어요.",
  str_guide_warn_80030102 = "「신전 건설」 버튼을 누르면 신전을 바라볼 수 있는 위치로 이동해서, 물의 촉수와 함께 신전을 복구할 수 있어요.",
  str_guide_warn_80030301 = "조종사 씨, 이건 융합 의식이에요! 중앙에 있는 융합 구역에 물의 조각을 배치해 주시고, 의식을 완수해서 안톤들의 힘을 회복할 수 있게 도와주세요!",
  str_guide_warn_80030302 = "물의 조각에는 안톤의 힘이 담겨 있고, 조각마다 융합력이 달라요. 그리고 어떤 조각은 특수 조건을 충족하면 더 많은 힘을 낼 수 있어요.",
  str_guide_warn_80030303 = "물의 조각을 융합 영역의 배치 가능한 위치로 가져와 배치하면 의식을 통해 그 안에 담긴 융합력을 끌어낼 수 있어요.",
  str_guide_warn_80030304 = "물의 조각을 배치한 뒤에 누르면 조각을 선택해서 이동하거나 조정할 수 있어요. 다양한 배치 방법을 통해 융합력을 강화해 보세요.",
  str_guide_warn_80030305 = "선택 상태에서는 버튼을 눌러서 조각을 시계 반대 방향으로 90° 회전시킬 수 있어요.",
  str_guide_warn_80030306 = "선택한 상태에서 취소 버튼을 누르면 조각을 회수할 수 있어요.",
  str_guide_warn_80030307 = "여긴 지금 놓인 물의 조각에 담긴 모든 융합력과, 이번 융합 의식 완료에 필요한 융합력을 볼 수 있어요!",
  str_guide_warn_80030308 = "클리어 버튼을 누르면 배치된 물의 조각이 모두 제거되니 신중하게 선택해 주세요!",
  str_guide_warn_80030309 = "융합력이 융합 의식에 필요한 조건에 도달하면 완료 버튼을 눌러 융합 의식을 완료하고, 안톤의 힘을 회복할 수 있어요!",
  str_guide_warn_18100101 = "어떻게 된 일인지 함께 가서 확인해 보자!",
  str_guide_warn_18100102 = "이곳에서 훈련을 시작할 수 있습니다. 훈련 스테이지를 완료하면 포인트와 스테이지 보상을 획득할 수 있습니다.",
  str_guide_warn_18100103 = "훈련 모듈에서는 일부 오로리안 사이에 인연 관계가 존재합니다. 인연 관계인 오로리안이 동시에 출전하면 더 많은 출전 기회를 얻을 수 있습니다.",
  str_guide_warn_18100104 = "지정 진영의 오로리안이 3명 이상 출전한 경우, 훈련에서 한 번에 여러 개의 칸을 제거하면 진영 지원 스킬을 발동할 수 있습니다.",
  str_guide_warn_18100105 = "훈련을 완료하면 포인트를 획득하며, 회차별 포인트가 지정 수량에 도달하면 포인트 보상을 수령할 수 있습니다.",
  str_guide_warn_18100106 = "훈련 스테이지를 완료하면 스테이지 보상을 획득할 수 있으며, 회차별 획득할 수 있는 스테이지 보상 한도가 이곳에 표시됩니다.",
  str_guide_warn_18100107 = "더 궁금한 점이 있다면 이곳에서 상세 규칙을 확인해 주세요.",
  str_guide_warn_18100108 = "훈련은 턴 수의 제한이 있으며, 파티의 HP는 스테이지 간 계승됩니다.",
  str_guide_circle_N37boss_Lt = "붉은 독액은 그녀의 체내로 스며들었고, 그녀는 가족을 위해 자신을 포함한 모든 위협을 제거하려고 합니다.",
  str_guide_circle_N37boss_LtT = "독에 잠식된 레베카",
  str_guide_circle_N37boss_Rt = "「신체 융해」 효과를 부여하며, 해당 효과가 적용된 대상은 턴 시작 시 HP를 잃습니다.",
  str_guide_circle_N37boss_RtT = "적 특성",
  str_guide_circle_N37boss_Lb = "「독의 흔적」으로 전환된 짙은 칸을 이용해서 타이밍을 잡아 공격하세요.",
  str_guide_circle_N37boss_LbT = "대응 전략",
  str_guide_circle_N37cap_Lt = "괴이한 생김새를 가진 클랜의 리더로, 총기 사용에 능숙합니다. 움브라톤에 있어 그는 백해무익한 존재일 뿐입니다.",
  str_guide_circle_N37cap_LtT = "클랜 리더",
  str_guide_circle_N37cap_Rt = "대상으로부터 멀어진 후 공격하여 피해를 2회 입히고, 대상의 속성 수치를 훔칩니다.",
  str_guide_circle_N37cap_RtT = "적 특성",
  str_guide_circle_N37cap_Lb = "거리에 주의하면서 제시간에 적을 처치하세요.",
  str_guide_circle_N37cap_LbT = "대응 전략",
  str_guide_circle_N37ranger_Lt = "정확성과 안전성, 은밀함과 강력함 덕에 석궁은 클랜이 선호하는 무기가 되었고, 실력이 뛰어난 자는 전장에서 위험한 존재가 되었습니다.",
  str_guide_circle_N37ranger_LtT = "클랜 석궁병",
  str_guide_circle_N37ranger_Rt = "십자형 최대 범위 내의 대상을 공격할 수 있으며, 공격 명중 시 대상이 받는 치료 효과가 감소합니다.",
  str_guide_circle_N37ranger_RtT = "적 특성",
  str_guide_circle_N37ranger_Lb = "빠르게 접근해서 먼저 처치하세요.",
  str_guide_circle_N37ranger_LbT = "대응 전략",
  str_guide_circle_N37light_Lt = "거대한 체형의 클랜 멤버입니다. 엄청난 힘을 가지고 있어 자신의 기계 팔로 공격하는 데 능숙합니다. 또한 전장에 함께 있는 움브라톤 적 세력에게 상응하는 지원을 제공합니다.",
  str_guide_circle_N37light_LtT = "클랜 지원병",
  str_guide_circle_N37light_Rt = "주변 1서클 내의 움브라톤 멤버에게 공격력 보너스를 제공하며, 자신의 HP가 일정 비율 미만으로 떨어지면 자신을 회복합니다.",
  str_guide_circle_N37light_RtT = "적 특성",
  str_guide_circle_N37light_Lb = "단숨에 처치해 회복하지 못하도록 하세요.",
  str_guide_circle_N37light_LbT = "대응 전략",
  str_guide_circle_n37_trap2803501_RtT = "짙은 칸",
  str_guide_circle_n37_trap2803501_Rt = "해당 위치에 갱신되는 다음 칸은 반드시 현재와 동일한 속성이 됩니다.",
  str_guide_circle_n37_trap2803501_RbT = "대응 전략",
  str_guide_circle_n37_trap2803501_Rb = "색 변경 스킬을 사용해 칸 속성을 변경하고 더 높은 성과를 발휘하세요.",
  str_guide_circle_N37cike_LtT = "클랜 암살자",
  str_guide_circle_N37cike_Lt = "적에게 빠른 2연타를 가하고 대상의 속성을 훔칠 수 있습니다.",
  str_guide_circle_N37cike_Lb = "지속 공격을 받지 않도록 최대한 빠르게 처치하세요.",
  str_guide_circle_N37cike_LbT = "대응 전략",
  str_guide_warn_551105 = "여길 터치해 봐!",
  str_guide_warn_551106 = "계몽 시스템이 개방됐어! 이 시스템을 통해 오로리안의 전체 속성을 높일 수 있어. 물의 모듈을 터치해 진입해 봐.",
  str_guide_warn_551107 = "왼쪽 목록에서 각 속성의 모듈을 빠르게 전환할 수 있어.",
  str_guide_warn_551108 = "이곳에선 현재 속성 모듈의 등급과 레벨을 확인할 수 있어.",
  str_guide_warn_551109 = "모듈 속성 정보는 이곳에서 확인할 수 있어.",
  str_guide_warn_551110 = "더 궁금한 점이 있다면 이곳에서 상세 규칙을 확인해 봐.",
  str_guide_warn_19000101 = "이곳에서는 보물 인양 작업을 진행하게 될 게다. 오랜 세월 선체에 잠들어 있던 진귀한 유물들을 하나씩 물 위로 건져 올리는 게지.",
  str_guide_warn_19000102 = "발견된 유물은 이 문물지에 기록되고, 관련 기록을 열람할 수 있게 된다.",
  str_guide_warn_19000103 = "공자가 아직 궁금한 점이 있다면, 이곳에서 설명을 확인해 보거라.",
  str_guide_warn_19000104 = "유물을 누르면 아래의 인양 구역으로 이동하게 될 거야.",
  str_guide_warn_19000105 = "인양 구역에 동일한 유물이 3개가 되면 인양에 성공해 없앨 수 있어.",
  str_guide_warn_19000106 = "여기서는 유물을 임시로 보관해, 인양 구역의 유물을 옮기고, 구역이 가득 차서 실패하는 걸 막을 수 있어.",
  str_guide_cage_Rt = "오로리안의 범위 피해 스킬을 통해 파괴할 수 있습니다. 파괴 시 새로운 적이 나타날지도 모릅니다!",
  str_guide_cage_RtT = "특수 트랩-감옥",
  str_guide_circle_N38boss_Lt = "수많은 기관술 피조물의 치명적인 특성을 결합해 만들어진 위험한 무기입니다. 안에는 심지어 아스트라의 기술까지 접목했다고 합니다. 그러나 이 거대한 녀석은 일반적인 에너지원으로는 가동할 수 없습니다.",
  str_guide_circle_N38boss_LtT = "비채·백가집성",
  str_guide_circle_N38boss_Rt = "신체 부위를 구성하는 각각의 기관수는 독특한 공격 수단을 가지고 있으며, 녀석의 꼬리는 에너지를 모아 대상에게 피해를 입힐 수 있지만, 상대적으로 취약합니다.",
  str_guide_circle_N38boss_RtT = "적 특성",
  str_guide_circle_N38boss_Lb = "스나이퍼 오로리안으로 꼬리를 먼저 공격해 행동 능력을 일시적으로 무력화시키고, 그 기회를 노려 공격하는 것이 좋습니다.",
  str_guide_circle_N38boss_LbT = "대응 전략",
  str_guide_warn_13800101 = "「바다에 새겨진 방주 ~작화행·상~」 이벤트가 시작됐어! 우린 「신풍의 귀향」에서 새로운 동료들과 함께 모험을 시작할 거야!",
  str_guide_warn_13800102 = "메인 스테이지와 자원 정비에서 프리즘을 소모하면 이벤트 아이템 「린 가문 상회 어음」을 얻을 수 있어.",
  str_guide_warn_13800103 = "「배의 무덤」에서 우린 더 어려운 시험과 마주하게 될 거야.",
  str_guide_warn_13800104 = "획득한 「린 가문 상회 어음」은 「부둣가 상점」에서 각종 보상으로 교환할 수 있어.",
  str_guide_warn_13800105 = "매일 출석하면 보상을 수령할 수 있으니까, 매일 로그인하는 것도 잊지 말아줘.",
  str_guide_warn_13800106 = "이벤트에 참가하면 특별 사건부의 임무를 완료할 수 있어.",
  str_guide_warn_13800107 = "이벤트에 대해 더 궁금한 점이 있다면, 이벤트의 상세 규칙을 확인해 봐.",
  str_guide_crab_Rt = "장인이 정교한 물건을 만들 때 보조하는 공구형 기관술 피조물입니다. 이후 뱃속에 화능술을 보존할 수 있는 유형이 탄생했는데, 원래는 무기로 사용하면 안 된다고 합니다.",
  str_guide_crab_RtT = "화로 게",
  str_guide_crab_Lt = "가로로 이동하면서 화염을 내뿜어 전방의 대상을 공격합니다.",
  str_guide_crab_LtT = "적 특성",
  str_guide_crab_Lb = "화로 게의 행동 방식은 고정되어 회전할 수 없습니다. 등 뒤로 돌아가 공격하세요.",
  str_guide_crab_LbT = "대응 전략",
  str_guide_warn_13900101 = "「그늘 속 검은 그림자」 이벤트가 시작됐어! 우린 「그림자 아래」에서 새로운 동료들과 함께 모험을 시작할 거야!",
  str_guide_warn_13900102 = "메인 스테이지와 자원 정비에서 프리즘을 소모하면 이벤트 아이템 「공중상회 토큰」을 얻을 수 있어.",
  str_guide_warn_13900103 = "「생사의 싸움판」에서 우린 더 어려운 시험과 마주하게 될 거야.",
  str_guide_warn_13900104 = "획득한 「공중상회 토큰」은 「부유 비공정」에서 각종 보상으로 교환할 수 있어.",
  str_guide_warn_13900105 = "매일 출석하면 보상을 수령할 수 있으니까, 매일 로그인하는 것도 잊지 말아줘.",
  str_guide_warn_13900106 = "이벤트에 참가하면 특별 사건부의 임무를 완료할 수 있어.",
  str_guide_warn_13900107 = "이벤트에 대해 더 궁금한 점이 있다면, 이벤트의 상세 규칙을 확인해 봐.",
  str_guide_circle_S4boss_Lt = "용주 업나라의 기관술로 만들어진 기관검입니다. 검을 휘두를 수 없는 사람들이 자신을 지킬 수 있게 돕는 용도였으나, 지금은 악인의 손에 들어가 저주받은 사검이 되었습니다.",
  str_guide_circle_S4boss_LtT = "사검·저주의 기교",
  str_guide_circle_S4boss_Rt = "「사검」이 된 후 능력이 크게 증가해 하늘을 날거나 땅으로 숨을 수 있고, 사악한 힘을 응축하여 검의 진열을 이룰 수 있습니다.",
  str_guide_circle_S4boss_RtT = "적 특성",
  str_guide_circle_S4boss_Lb = "사검은 공간을 절단하고 금제의 벽을 생성하는 능력을 가지고 있습니다. 위치이동 능력을 지닌 오로리안을 이용해 퇴마 기관을 밟고 금제의 벽을 제거하면 쉽게 공격할 수 있습니다.",
  str_guide_circle_S4boss_LbT = "대응 전략",
  str_guide_warn_16021911 = "이스타반 더 스칼드 피스의 액티브 스킬은 팀원 1명 또는 그림자 기물을 선택해 시전해야 합니다.",
  str_guide_warn_16021912 = "이곳에는 현재 팀원에게 시전 시 소모하는 [그림자의 선물] 포인트가 표시됩니다. 포인트가 부족할 경우 해당 팀원에게 시전할 수 없습니다.",
  str_guide_warn_16021913 = "아이리나에게 스킬을 시전하세요",
  str_guide_warn_16021914 = "이번 전투에서 해당 팀원에게 액티브 스킬을 시전할 때마다 다음 소모량이 1 증가합니다.",
  str_guide_warn_80040111 = "조종사, 여기 좀 봐! 꿈의 세계에서 새로운 능력을 얻었어!",
  str_guide_warn_80040112 = "꿈의 세계에 더 깊이 들어갈수록 능력이 더 강해질 테니까, 잊지 말고 꼭 활용해 봐!",
  str_guide_circle_shenghuaboss_Lt = "암귀를 기반으로 개조된 강화 병사입니다. 기계 장치로 온몸을 덮어 더 단단하고, 더 흉포하며, 더 압도적입니다.",
  str_guide_circle_shenghuaboss_LtT = "강화 병사-브로거움",
  str_guide_circle_shenghuaboss_Rt = "적을 압도하는 강화 병사입니다. 주변의 적들을 깔아뭉개는 공격에 능숙합니다.",
  str_guide_circle_shenghuaboss_RtT = "적 특성",
  str_guide_circle_shenghuaboss_Lb = "브로거움은 일반공격 피해에 대한 저항력이 높으므로, 연쇄 또는 액티브 스킬을 사용해 공격하세요.",
  str_guide_circle_shenghuaboss_LbT = "대응 전략",
  str_guide_circle_ylxs_Lt = "자신의 극단적인 이상을 실현하기 위해 율리시스는 자신의 몸에 대대적인 개조를 진행했습니다. 이제 그는 오로리안이 아니게 되었습니다.",
  str_guide_circle_ylxs_LtT = "개조된 율리시스",
  str_guide_circle_ylxs_Rt = "율리시스는 오로리안의 능력 변화에 따라 다양한 공격 전략을 선택합니다.",
  str_guide_circle_ylxs_RtT = "적 특성",
  str_guide_circle_ylxs_Lb = "현재 파티 상황에 따라 공격 방식을 합리적으로 선택하고, 율리시스의 공격을 피해야만 승률을 높일 수 있습니다.",
  str_guide_circle_ylxs_LbT = "대응 전략",
  str_guide_warn_shzyx_01 = "조심해! 가디언 프로토타입이 가동됐어!",
  str_guide_warn_shzyx_02 = "이건 엔지니어가 만든 고대의 기계야. 왠지 어느 정도의 자의식을 가지고 있는 것 같아.",
  str_guide_warn_shzyx_03 = "오로리안의 일반공격, 액티브 스킬 또는 연쇄 스킬을 제한하는 능력이 있고, 상대에게 피해를 입히고 자기 편을 보호할 거야.",
  str_guide_warn_shzyx_04 = "지금 파티 상황에 따라 공격 방식을 합리적으로 선택해야 녀석을 상대할 수 있어. 절대 방심해선 안 돼!",
  str_guide_circle_soilder1_Rt = "암귀와 오로리안을 결합해 만든 전쟁 병기입니다. 이 기체는 오로리안의 특징을 최대한 유지하고 있으며, 기계화가 눈에 띄지는 않지만, 여전히 매우 위험합니다.",
  str_guide_circle_soilder1_RtT = "병사-버크로",
  str_guide_circle_soilder1_Rb = "기계화 생명체로, 적을 베어 공격할 수 있습니다.",
  str_guide_circle_soilder1_RbT = "적 특성",
  str_guide_circle_soilder1_Lb = "병사-버크로는 오로리안의 일반공격 피해를 반사할 수 있습니다. 거리를 유지하면서 연쇄 또는 액티브 스킬을 사용해 공격하세요.",
  str_guide_circle_soilder1_LbT = "대응 전략",
  str_guide_circle_soilder2_Rt = "암귀와 오로리안을 결합해 만든 강화 병기입니다. 두꺼운 갑주가 전신을 덮고 있으며, 힘이 대폭 강화되었습니다.",
  str_guide_circle_soilder2_RtT = "병사-우룰리트",
  str_guide_circle_soilder2_Rb = "개조된 기계 생명체입니다. 힘과 방어력이 크게 향상되었으며, 폭파 등의 공격 방식에 능숙합니다.",
  str_guide_circle_soilder2_RbT = "적 특성",
  str_guide_circle_soilder2_Lb = "병사-우룰리트는 오로리안의 일반공격 피해를 반사할 수 있습니다. 공격 범위에 주의하면서 연쇄 또는 액티브 스킬을 사용해 공격하세요.",
  str_guide_circle_soilder2_LbT = "대응 전략",
  str_guide_circle_soilder3_Rt = "암귀와 오로리안을 결합해 만든 강화 병기입니다. 이 기체는 더는 그 어떤 오로리안의 특징도 보이지 않으며, 완전히 기계로 변해버렸습니다.",
  str_guide_circle_soilder3_RtT = "강화 병사-메이옴",
  str_guide_circle_soilder3_Rb = "개조된 기계 생명체입니다. 자신의 두꺼운 갑주를 무기로 사용하며, 상대하기 매우 어렵습니다.",
  str_guide_circle_soilder3_RbT = "적 특성",
  str_guide_circle_soilder3_Lb = "강화 병사-메이옴은 오로리안의 일반공격 피해를 반사할 수 있고, 자신의 HP를 회복합니다. 신속하게 전투를 끝내는 것이 좋습니다.",
  str_guide_circle_soilder3_LbT = "대응 전략",
  str_guide_warn_14000101 = "「안개 너머 과거의 메아리」 이벤트가 시작됐어! 우린 이제 「제2부」의 새로운 이야기를 열게 될 거야!",
  str_guide_warn_14000102 = "이쪽에서 이번 이벤트에 개방된 스토리 챕터와 지금까지 탐색한 챕터를 확인할 수 있어.",
  str_guide_warn_14000103 = "「탐색하기」를 누르면 탐색 맵으로 바로 이동하고, 메인 스테이지와 자원 정비 스테이지에서 프리즘을 소모하면 이벤트 아이템 「아이테르의 깃털」을 얻을 수 있어.",
  str_guide_warn_14000104 = "획득한 「아이테르의 깃털」은 「오로라 교환」에서 각종 보상으로 교환할 수 있어.",
  str_guide_warn_14000105 = "이벤트에 참가하면 특별 사건부의 임무를 완료할 수 있어.",
  str_guide_warn_14000106 = "매일 출석하면 조종 출석 보상을 수령할 수 있으니까, 매일 로그인하는 것도 잊지 말아줘.",
  str_guide_warn_14000107 = "이벤트에 대해 더 궁금한 점이 있다면, 이벤트의 상세 규칙을 확인해 봐.",
  str_guide_warn_14100101 = "「요마를 쫓는 봄날의 금린 ~작화행·중~」 이벤트가 시작됐어! 우린 「용녀진해」에서 새로운 동료들과 함께 모험을 시작할 거야!",
  str_guide_warn_14100102 = "메인 스테이지와 자원 정비 스테이지에서 프리즘을 소모하면 이벤트 아이템 「기원향」을 얻을 수 있어.",
  str_guide_warn_14100103 = "「파사영춘」에서 우린 더 어려운 시험과 마주하게 될 거야.",
  str_guide_warn_14100104 = "획득한 「기원향」은 「복의 사당」에서 각종 보상으로 교환할 수 있어.",
  str_guide_warn_14100105 = "매일 출석하면 보상을 수령할 수 있으니까, 매일 로그인하는 것도 잊지 말아줘.",
  str_guide_warn_14100106 = "이벤트에 참가하면 특별 사건부의 임무를 완료할 수 있어.",
  str_guide_warn_14100107 = "이벤트에 대해 더 궁금한 점이 있다면, 이벤트의 상세 규칙을 확인해 봐.",
  str_guide_circle_yingzi_LtT = "사념-섀도",
  str_guide_circle_yingzi_Lt = "사념에 침식되어 소환 능력에 변화가 발생했습니다.",
  str_guide_circle_yingzi_RtT = "적 특성",
  str_guide_circle_yingzi_Rt = "매회 소환되는 룬의 개수가 대폭 증가합니다.",
  str_guide_circle_miran_LtT = "사념-레지스터",
  str_guide_circle_miran_Lt = "사념에 침식되어 공격 능력에 변화가 발생했습니다.",
  str_guide_circle_miran_RtT = "적 특성",
  str_guide_circle_miran_Rt = "플레이어에게 공격 명중 시 플레이어의 행동력을 2포인트 감소시킵니다.",
  str_guide_circle_aogeyang_LtT = "사념-프라이드 스피어",
  str_guide_circle_aogeyang_Lt = "사념에 침식되어 능력에 변화가 발생했습니다.",
  str_guide_circle_aogeyang_RtT = "적 특성",
  str_guide_circle_aogeyang_Rt = "이동 능력이 대폭 향상되며, 2턴마다 근처에 적을 소환해 플레이어를 공격합니다.",
  str_guide_circle_jingmianta_LtT = "미러 타워-활성화",
  str_guide_circle_jingmianta_Lt = "특수한 환경에서 변화하는 거울 장치입니다. 오로리안 팀에 도움이 될 수 있습니다.",
  str_guide_circle_jingmianta_RtT = "장치 특성",
  str_guide_circle_jingmianta_Rt = "필드에 존재할 시 팀에 특수한 에너지를 제공하며, 팀이 턴마다 회복하는 행동력이 1 증가합니다.",
  str_guide_circle_laolong_LtT = "사념-우리",
  str_guide_circle_laolong_Lt = "우리 안에는 모종의 특별한 이유로 갇혀 있는 적들이 있습니다. 그들이 풀려난다면 보스에게 도움이 될 수도, 약점이 될 수도 있습니다.",
  str_guide_circle_laolong_RtT = "장치 특성",
  str_guide_circle_laolong_Rt = "장치를 터치하고 행동력 3포인트를 소모해 우리 속 적을 풀어줄 수 있습니다. 직접 활용할 수는 없지만, 적이 받는 피해의 일부가 보스에게 전달됩니다.",
  str_guide_circle_paotai_LtT = "포탑",
  str_guide_circle_paotai_Lt = "성능이 좋은 포탑입니다. 수동으로 조작해야 하지만 자동보다 효과가 더 좋을 수도 있습니다.",
  str_guide_circle_paotai_RtT = "장치 특성",
  str_guide_circle_paotai_Rt = "장치를 터치하고 행동력 2포인트를 소모해 공격을 1회 진행하며, 전방 직선 범위 내 가장 가까운 적에게 상당한 피해를 입히고 디버프 효과를 추가합니다.",
  str_guide_circle_fengchuan_RtT = "장치 특성",
  str_guide_circle_fengchuan_Rt = "휴대성이 좋아지고 사용하기 쉬워졌으며, 팀 행동력을 소모해 스킬을 시전할 수 있습니다.",
  str_guide_circle_8024001 = "「악을 베는 밤」에서는 팀이 더는 기존 규칙에 따라 이동하지 않고, 「행동력」을 소모해서 이동해요.",
  str_guide_circle_8024002 = "여기 가장 왼쪽에 현재 「행동력」이 표시돼요. 연결하면 실시간으로 남은 「행동력」을 확인할 수도 있어요.",
  str_guide_circle_8024003 = "방금 이동하면서 「행동력」이 소진됐어요. 하지만 괜찮아요. 턴이 시작될 때마다 일정량의 「행동력」를 받게 될 테니까요. 다음 턴에 회복되는 행동력은 가장 오른쪽에서 확인할 수 있어요.",
  str_guide_circle_8024004 = "여길 눌러서 지금 적용되는 특성 효과를 확인할 수 있어요.",
  str_guide_circle_8024005 = "턴마다 소모되지 않은 「행동력」은 턴 종료 후에도 사라지지 않아요. 따라서 가끔은 「행동력」을 1턴 사용하지 않는 것도 좋은 선택이 될 수 있어요.",
  str_guide_season_talent_tree_1 = "「특수기 편성」 몇 개의 진안과 특수기로 구성되고, 버프 효과를 제공해 줘요. 그럼 첫 번째 「진안」을 활성화해 보세요!",
  str_guide_season_talent_tree_2 = "「활성화」 버튼을 선택하고, 「길운」을 소비해서 첫 번째 「진안」을 활성화해 보세요.",
  str_guide_season_talent_tree_3 = "진안이 활성화되면 진안 효과가 그대로 전투에 적용돼요. 일부 「진안」은 「특수기 슬롯」도 개방할 수 있어요.",
  str_guide_season_talent_tree_4 = "이어서 첫 번째 「패시브 특수기」를 개방해 보세요. 이 「패시브 특수기」를 누르세요.",
  str_guide_season_talent_tree_5 = "「활성화」 버튼을 선택하고, 「길운」을 소비해서 특수기를 활성화해 보세요.",
  str_guide_season_talent_tree_6 = "활성화하면 이 「특수기」를 대응하는 타입의 「특수기 슬롯」으로 끌어서 장착할 수 있어요. 그럼 전투 중에 적용될 거예요.",
  str_guide_season_talent_tree_7 = "「특수기 슬롯」에 장착할 수 있는 특수기 유형은 제한이 있어요. 첫 번째 슬롯에만 「아이테르 특수기」를 장착할 수 있고, 나머지 슬롯은 「패시브 특수기」만 장착할 수 있어요.",
  str_guide_season_talent_tree_8 = "더 자세한 내용은 설명을 확인해 보세요.",
  str_guide_season_trade_out_1 = "「항해하는 낮」은 새롭게 개방된 경영 콘텐츠예요. 조종사 씨는 여기서 부두와 상선을 경영하며 「운영 자금」과 「길운」을 벌 수 있어요.",
  str_guide_season_trade_out_2 = "「악을 베는 밤」은 새롭게 개방된 스테이지 콘텐츠예요. 조종사 씨는 새로운 이동 방식을 사용하고, 풍수의 특수기를 활용해서 전투를 도울 수 있어요!",
  str_guide_season_trade_in_1 = "「부두」와 「상선」은 주요 경영 대상이에요. 오른쪽 상단의 「개축 레벨업」을 누르면 선택 중인 대상을 레벨업할 수 있어요.",
  str_guide_season_trade_in_2 = "「부두」와 「상선」 레벨은 부두의 하역 속도, 상선의 적재 잔여량, 그리고 수송 완료 후의 하역 시간에 영향을 미치게 돼요.",
  str_guide_season_trade_in_3 = "「수행원」은 고용 후에 각 「상선」에 배정할 수 있어요. 그리고 한 「수행원」은 동시에 한 척의 「상선」에만 배정할 수 있어요.",
  str_guide_season_trade_in_4 = "「수행원」은 「관리 능력」, 「해운 능력」, 「정비 능력」의 능력치를 가지고 있어요. 고레벨 「부두」는 더 능력이 강한 「수행원」을 고용할 수 있어요.",
  str_guide_season_trade_in_5 = "「상선 상태」는 배정된 승무원의 능력치에 따라 결정돼요. 현재 「상선 레벨」의 요구 수준에 도달하지 않으면 상태가 크게 저하되어 수익에 영향을 미칠 거예요.",
  str_guide_season_trade_in_6 = "「출항」으로 번 누적 「운영 자금」이 각 단계의 목표에 도달하면 「상회 번영도 등급」이 높아지고, 보상도 받을 수 있어요!",
  str_guide_season_trade_in_7 = "열심히 「부두」와 「상선」 레벨을 높이고, 적절하게 선원을 배치해 항해 사건에 대응해서 출항 수익을 높여 보세요!",
  str_guide_season_trade_in_8 = "더 자세한 내용은 설명을 확인해 보세요.",
  str_guide_mouse_Rt = "체형이 작고 수행이 부족한 잡식성 수요령입니다. 아직 야성이 남아 있어 오로리안의 집에 들어가 양식을 훔치기도 하며, 흉악한 개체는 사람을 해치기도 합니다.",
  str_guide_mouse_RtT = "수요령·쥐",
  str_guide_mouse_Lt = "움직임이 민첩해 공격 후 즉시 대상의 후방으로 이동합니다.",
  str_guide_mouse_LtT = "적 특성",
  str_guide_mouse_Lb = "공격 시 파티에서 방어력이 가장 낮은 오로리안을 목표로 피해를 입힙니다. 되도록 방어력이 너무 낮은 오로리안을 출전시키지 않는 것이 좋습니다.",
  str_guide_mouse_LbT = "대응 전략",
  str_guide_circle_2909301_Lt = "매년 춘삭절 섣달그믐날 밤이 되면, 사나운 야수 형태의 수요령이 용주에 강림해 사방에 혼란을 일으킵니다. 년수를 몰아내는 데 성공한 자는 한해의 안녕과 행운을 얻을 수 있다고 합니다.",
  str_guide_circle_2909301_LtT = "수요령·년수",
  str_guide_circle_2909301_Rt = "액티브 스킬로 년수를 놀라게 하면 공격을 늦출 수 있습니다.",
  str_guide_circle_2909301_RtT = "대응 전략",
  str_guide_circle_2909301_Lb = "전방으로 도약해 피해를 입히며, 주변 1서클의 칸을 이동할 수 없게 만듭니다. 년수가 문을 파괴하면 전투에서 패배합니다.",
  str_guide_circle_2909301_LbT = "적 특성",
  str_guide_circle_80050001_Rt = "턴이 시작될 때마다 「전투 에너지」 10포인트가 누적되며, 턴이 끝날 때마다 자신의 「전투 에너지」가 30포인트를 초과하면 필드 내 모든 적의 공격력이 증가합니다.",
  str_guide_circle_80050001_RtT = "정보 암귀-블랙박서",
  str_guide_circle_80050001_Rb = "오로리안은 액티브 스킬을 시전하거나 일반공격을 통해 블랙박서에게 피해를 입혀 「전투 에너지」를 감소시킬 수 있습니다. 블랙박서 처치 시 필드 내 모든 적이 피해를 입습니다.",
  str_guide_circle_80050001_RbT = "대응 전략",
  str_guide_warn_80050111 = "조종사, 여기 좀 봐! 꿈의 세계에서 새로운 능력을 얻었어!",
  str_guide_warn_80050112 = "꿈의 세계에 더 깊이 들어갈수록 능력이 더 강해질 테니까, 잊지 말고 꼭 활용해 봐!",
  str_guide_circle_80150101 = "팀이 더는 기존 규칙에 따라 이동하지 않으며, 「행동력」을 소모해 칸을 무시하고 이동합니다.",
  str_guide_circle_80150102 = "이곳에는 플레이어의 「행동력」이 표시됩니다. 왼쪽부터 플레이어의 「현재 행동력」, 「저장 한도」, 「행동력 회복량」이 표시됩니다.",
  str_guide_circle_80150103 = "플레이어는 턴이 시작될 때마다 「행동력 회복량」에 따라 자동으로 행동력을 회복하며, 「행동력 회복량」은 턴이 지날수록 증가합니다.",
  str_guide_circle_80150201 = "본 콘텐츠에서 플레이어가 짙은 칸 1개를 소모할 때마다 행동력을 1 회복할 수 있습니다.",
  str_guide_circle_80150301 = "행동력을 소모해 터치하면 암석을 제거할 수 있습니다.",
  str_guide_circle_80250101 = "본 콘텐츠에서 플레이어가 연쇄 스킬을 시전할 때 짙은 칸 소모 시 칸 2개로 판정됩니다.",
  str_guide_circle_2921201_Lt = "「사일런트 예거」의 대장이었지만, 이제는 자신을 그토록 믿어주었던 대원들에게 칼을 겨누고 있습니다... 그는 왕국을 위해 타협한 끝에 이 결말에 다다르게 되었습니다.",
  str_guide_circle_2921201_LtT = "그라디우스",
  str_guide_circle_2921201_Rt = "전장 상황에 따라 연결 이동 후 공격하거나, 일반 이동 후 2회 공격을 진행합니다. HP가 감소하면 특수 스킬을 시전해 전장을 가르고, 상대와 더 좁은 공간에서 결투를 벌입니다.",
  str_guide_circle_2921201_RtT = "적 특성",
  str_guide_circle_2921201_Lb = "특수 스킬에 맞지 않도록 주의하세요. 나머지는 자신의 실력에 달려 있습니다.",
  str_guide_circle_2921201_LbT = "대응 전략",
  str_guide_circle_2909401_Lt = "행적이 비밀스러운 강력한 팬텀으로, 평생을 각지에서 수행해 왔습니다. 그의 숨결에는 공포의 힘이 담겨 있으며, 그의 분노에 닿은 생물은 모두 죽음을 면치 못합니다.",
  str_guide_circle_2909401_LtT = "아이라",
  str_guide_circle_2909401_Rt = "다크매터를 사용해 전투 중 「고스트파이어」를 소환할 수 있습니다.",
  str_guide_circle_2909401_RtT = "적 특성",
  str_guide_circle_2909401_Lb = "주의: 아이라가 소환하는 분노의 다크매터 운석은 아군 오로리안을 즉시 처치할 수 있습니다. 경고 구역에 주의하며 제때 회피하세요!",
  str_guide_circle_2909401_LbT = "대응 전략",
  str_guide_n43_1 = "「빛의 유적」 이벤트가 시작됐어!\n이제 두 번째 스페셜 챕터의 이야기가 펼쳐질 거야!",
  str_guide_n43_2 = "이쪽에서 이번 이벤트에 개방된 스토리 챕터와 지금까지 탐색한 챕터를 확인할 수 있어.",
  str_guide_n43_3 = "「탐색하기」를 누르면 탐색 맵으로 바로 이동하고, 메인 스테이지와 자원 정비 스테이지에서 프리즘을 소모하면 이벤트 아이템 「아이테르의 깃털」을 얻을 수 있어.",
  str_guide_n43_4 = "획득한 「아이테르의 깃털」은 「오로라 교환」에서 각종 보상으로 교환할 수 있어.",
  str_guide_n43_5 = "이벤트에 참가하면 특별 사건부의 임무를 완료할 수 있어.",
  str_guide_n43_6 = "매일 출석하면 조종 출석 보상을 수령할 수 있으니까, 매일 로그인하는 것도 잊지 말아줘.",
  str_guide_n43_7 = "이벤트에 대해 더 궁금한 점이 있다면, 이벤트의 상세 규칙을 확인해 봐.",
  str_guide_warn_90010702 = "안내, 여길 누르면 「판타즘 스톤」 메뉴를 열 수 있습니다.",
  str_guide_warn_90010703 = "안내, 「계몽의 나선」에는 여러 개의 빈자리가 있습니다. 빈자리에 「판타즘 스톤」을 넣으면 「판타즘 스톤」의 힘을 분석하고 시전할 수 있습니다.",
  str_guide_warn_90010704 = "안내, 「판타즘 스톤」에 대한 상세 정보를 보려면 「판타즘 스톤」을 누르세요.",
  str_guide_warn_90010705 = "안내, 「조립」 버튼을 누르면 「판타즘 스톤」을 「계몽의 나선」에 넣을 수 있습니다. 「판타즘 스톤」을 빈 공간에 직접 끌어당겨도 됩니다.",
  str_guide_warn_90010706 = "설명, 충분한 에너지가 있어야만 「계몽의 나선」에 있는 「판타즘 스톤」의 힘을 시전할 수 있습니다. 걱정하지 마세요. 계몽자는 아버지가 전투 중에 충분한 에너지를 축적할 수 있을 거라 믿습니다.",
  str_guide_warn_90010707 = "안내, 「판타즘 스톤」이 여러 개인 경우, 이를 합성해 더 높은 레벨의 「판타즘 스톤」을 획득하는 것도 고려해 보세요.",
  str_guide_warn_90010708 = "같은 레벨의 「판타즘 스톤」 2개를 1레벨 높은 「판타즘 스톤」 1개로 합성할 수 있습니다.",
  str_guide_warn_90010709 = "안내, 더 궁금한 점이 있다면 이곳에서 상세 규칙을 확인해 주세요.",
  str_guide_circle_2004901_LbT = "증오의 안개",
  str_guide_circle_2004901_Lb = "적 사망 시 주변의 다크매터가 빠르게 응집되어 이루어진 결과물입니다. 적의 분노와 원한이 담겨 있으니 주의해야 합니다.",
  str_guide_circle_2004901_RtT = "적 특성",
  str_guide_circle_2004901_Rt = "받는 모든 피해가 1로 감소합니다. 공격하지 않지만 오로리안을 향해 이동합니다.\n증오의 안개는 웨이브 갱신 및 스테이지 승리 조건에 포함되지 않습니다.",
  str_guide_circle_2004901_RbT = "대응 전략",
  str_guide_circle_2004901_Rb = "증오의 안개는 넉백, 끌어당김, 강제이동 효과를 받으면 즉시 사라지며, 또는 일정 턴 이후 소멸합니다.",
  str_guide_circle_80060313_LbT = "정예 특성: 증오의 안개",
  str_guide_circle_80060313_Lb = "해당 정예 특성을 지닌 적 사망 시 증오의 안개를 생성하며, 생성 수량은 적의 크기에 따라 결정됩니다.\n적 터치 시 자세한 설명을 확인할 수 있습니다.",
  str_guide_circle_2909501_LbT = "가시덩굴 당근",
  str_guide_circle_2909501_Lb = "어두운 곳에서 원한을 과도하게 흡수해 타락한 당근입니다. 다크매터의 힘을 얻어 결국 복수만을 생각하는 형언할 수 없는 존재로 성장했습니다.",
  str_guide_circle_2909501_RtT = "적 특성",
  str_guide_circle_2909501_Rt = "당근을 던져 여러 차례 피해를 입힐 수 있으며, 고속으로 회전 시 주변의 넓은 범위에 여러 차례의 피해를 입히고 넉백시킵니다.",
  str_guide_circle_2909501_RbT = "대응 전략",
  str_guide_circle_2909501_Rb = "적의 체형이 크니 버스터 오로리안을 출전시켜 상대하세요!",
  str_guide_circle_2909502_LbT = "가시덩굴 당근",
  str_guide_circle_2909502_Lb = "어두운 곳에서 원한을 과도하게 흡수해 타락한 당근입니다. 다크매터의 힘을 얻어 결국 복수만을 생각하는 형언할 수 없는 존재로 성장했습니다.",
  str_guide_circle_2909502_RtT = "적 특성",
  str_guide_circle_2909502_Rt = "당근을 던져 여러 차례 피해를 입힐 수 있으며, 고속으로 회전 시 주변의 넓은 범위에 여러 차례의 피해를 입히고 넉백시킵니다.\n위급한 순간에는 크기가 줄어들어 땅으로 파고들고, 계속해서 싸울 수 있습니다.",
  str_guide_circle_2909502_RbT = "대응 전략",
  str_guide_circle_2909502_Rb = "적의 체형이 크니 버스터 오로리안을 출전시켜 상대하세요!\n주의: HP 자물쇠 도달 시 적이 4칸 형태로 변신합니다!",
  str_guide_circle_80060101_RtT = "꿈의 세계 내 출혈 효과",
  str_guide_circle_80060101_Rt = "현재 꿈의 세계의 특수 효과에 따라, 기존의 모든 「출혈」 상태는 스테이지 내에서 「중상」 상태로 대체되며, 발동 방식은 기존의 「출혈」 상태와 동일합니다.",
  str_guide_circle_80060101_RbT = "중상 시스템",
  str_guide_circle_80060101_Rb = "「중상」 상태의 적은 턴마다 오로리안 팀의 평균 공격력에 따라 피해를 받게 됩니다. 팀의 HP 퍼센트 및 「중상」 단계가 높을수록 피해도 증가합니다. 「중상」 상태는 최대 5회까지 중첩될 수 있으며, 턴이 지나도 사라지지 않습니다.",
  str_guide_circle_80060102_LtT = "중상 상태",
  str_guide_circle_80060102_Lt = "초기 스테이지의 적은 기본적으로 1개의 「중상」 상태를 가지며, 턴마다 중상 피해를 입습니다. 몬스터 터치 시 해당 「중상」 효과를 확인할 수 있습니다.",
  str_guide_circle_80060201_RtT = "폭발 암석",
  str_guide_circle_80060201_Rt = "평범해 보이지만, 실제로는 폭발물이 들어 있는 암석입니다. 파괴 시 주변 적에게 피해를 입히고, 「중상」 1단계를 추가합니다.",
  str_guide_circle_80060201_LtT = "폭발 확산",
  str_guide_circle_80060201_Lt = "일부 암석은 놀라울 정도로 강해서, 여러 번 때려야 부술 수 있습니다. 암석의 HP바 1개마다 폭발 범위가 1서클 확대됩니다.",
  str_guide_circle_80060401_RtT = "특수 가시",
  str_guide_circle_80060401_Rt = "왠지 익숙해 보이는 특수 가시입니다. 이번에는 오로리안에게 해를 끼치지 않는 것 같습니다. 턴이 종료되면 가시 위의 몬스터가 피해를 입고, 「중상」 단계가 추가됩니다.",
  str_guide_circle_2909701_LbT = "그리드-마그마",
  str_guide_circle_2909701_Lb = "돌연변이 암귀입니다. 다크매터 외에도 용암을 분출해 피해를 입힙니다.",
  str_guide_circle_2909701_RtT = "적 특성",
  str_guide_circle_2909701_Rt = "넓은 지역에 피해를 입히는 능력이 있으며, 용암 실드를 소환해 자신을 보호할 수도 있습니다.",
  str_guide_circle_2909701_RbT = "대응 전략",
  str_guide_circle_2909701_Rb = "그리드-마그마가 실드를 가지고 있을 시 근접 일반공격을 피하고 반격합니다. 지면에서 뿜어져 나오는 화염에도 주의하세요!",
  str_guide_warn_811400101 = "「위기의 전조」 개방 기간에 조종사는 각 「흉조의 서」를 선택해 도전할 수 있습니다. 「흉조의 서」는 시간에 따라 순차 개방됩니다.",
  str_guide_warn_811400102 = "「흉조의 서」를 터치해 도전 화면으로 진입하세요.",
  str_guide_warn_811400103 = "각 「흉조의 서」는 3개의 난이도로 나누어져 있으며, 이곳에서 다양한 난이도를 전환해 도전할 수 있습니다.",
  str_guide_warn_811400104 = "이곳에서는 「전장 특성」을 확인하고 「흉조의 서」 보스의 특성을 알아볼 수 있습니다.",
  str_guide_warn_811400105 = "각 「흉조의 서」에서 조종사는 1~3개의 강화 효과를 선택해 전투 능력을 강화할 수 있습니다. 난이도가 높을수록 더 많은 강화 기능을 선택할 수 있습니다.",
  str_guide_warn_811400106 = "슬롯을 터치해 강화 효과를 선택하세요.",
  str_guide_warn_811400107 = "강화 효과는 3개의 구역으로 나누어져 있으며, 영역마다 위에서부터 순서대로 개방해야 합니다.",
  str_guide_warn_811400108 = "틀을 터치해 해당하는 강화 효과를 선택할 수 있습니다.",
  str_guide_warn_811400109 = "확인을 터치해 선택한 강화 효과를 저장하세요.",
  str_guide_warn_811400110 = "스테이지 클리어 후 도전 퀘스트를 완료해 풍성한 보상을 획득할 수 있습니다.",
  str_guide_circle_2909801_LbT = "어썰트호-부식된 악의",
  str_guide_circle_2909801_Lb = "한때 이클립스를 위해 적진에 돌격하던 전투형 콜로서스였으나, 괴력에 의해 파손된 후 지금은 완전히 부서졌다. 그저 살의를 감춘 꼬리뼈만 남은 채 계속해서 악의를 품고 있다.",
  str_guide_circle_2909801_RtT = "적 특성",
  str_guide_circle_2909801_Rt = "넓은 범위의 대상에게 피해를 입히며, 무리 지어 행동하는 말초 조각을 생성해 오로리안을 방해한다.",
  str_guide_circle_2909801_RbT = "대응 전략",
  str_guide_circle_2909801_Rb = "자신을 보호하기 위해 지속적으로 말초 조각을 소환합니다. 말초 조각을 피해 공격하세요.",
  str_guide_2005101_Rt = "원래는 콜로서스 「어썰트호」의 꼬리를 구성하는 일부였으나, 지금은 조각조각 분리되어 지하 유적에 흩어져 있다.",
  str_guide_2005101_RtT = "말초 조각",
  str_guide_2005101_Lt = "신비한 힘에 의해 조종되는 비행형 적으로, 끊임없이 기괴한 대형을 형성하고 침입자에게 근접 공격을 가할 수 있다.",
  str_guide_2005101_LtT = "적 특성",
  str_guide_2005101_Lb = "진형을 형성하는 말초 조각은 대상을 쉽게 포위합니다. 서둘러 관절을 격파하고 말초 조각을 분리하세요.",
  str_guide_2005101_LbT = "대응 전략",
  str_guide_2910001_Lt = "각 부위를 활용해 오로리안을 공격할 수 있습니다. 슈르톤의 어떤 부위라도 공격 시 슈르톤에게 피해를 입힐 수 있습니다.",
  str_guide_2910001_LtT = "적 특성",
  str_guide_2910001_Lb = "공격을 피하고, 최대한 여러 부위를 공격하세요!",
  str_guide_2910001_LbT = "대응 전략",
  str_guide_2910002_Lt = "각 부위를 활용해 오로리안을 공격할 수 있습니다. 슈르톤의 어떤 부위라도 공격 시 슈르톤에게 피해를 입힐 수 있습니다.",
  str_guide_2910002_LtT = "적 특성",
  str_guide_2910002_Lb = "주의하세요! 슈르톤의 꼬리는 타깃형 피해만 입습니다!",
  str_guide_2910002_LbT = "대응 전략",
